/* --- procedural bosses ----------------------------------------------------
   Fifty-two rungs cannot each have a hand-built boss, and fifty-two copies of
   one boss is worse than having none. The avatar at the end of a delve is the
   Deceiver either way -- he is the fiction -- but what he is capable of is
   rolled per rung and stays rolled: the same rung always answers with the same
   thing, so a delve is learnable, and two rungs apart are not the same fight.

   Every mutator has to be visible in play. A boss that quietly has more hit
   points is not a different boss, it is the same boss taking longer, so each
   of these changes something you can see and respond to.
   -------------------------------------------------------------------- */
const MUTATORS = [
  { id: 'sundering', name: 'the Sundering',
    note: 'His hand comes down where you stand.',
    apply: b => { b.slam = true; b.slamCd = 2.2; b.slamR = 1.5; } },
  { id: 'legion', name: 'the Legion',
    note: 'He does not come with two. He comes with five.',
    apply: b => { b.extraGuard = 2; } },
  { id: 'wreathed', name: 'the Wreathed',
    note: 'More of him is a lie than usual.',
    apply: b => { b.split = 4.5; b.mirages = 5; } },
  { id: 'unblinking', name: 'the Unblinking',
    note: 'This one does not step away. It walks.',
    apply: b => { b.blink = 1e9; b.speed *= 1.5; b.hp = b.maxHp = b.maxHp * 1.35; } },
  { id: 'ravenous', name: 'the Ravenous',
    note: 'He eats what dies near him.',
    apply: b => { b.ravenous = true; } },
  { id: 'riftborn', name: 'the Riftborn',
    note: 'The ground does not close behind him.',
    apply: b => { b.riftborn = true; } },
  { id: 'unbroken', name: 'the Unbroken',
    note: 'He gathers himself, and for a moment almost nothing touches him.',
    apply: b => { b.guardCd = 7.5; } }
];
const MUTATOR_BY_ID = {};
for (const m of MUTATORS) MUTATOR_BY_ID[m.id] = m;

// A cheap integer hash, so a rung's boss is a property of the rung rather than
// of the run. Rolling it per delve would make the ladder unlearnable.
function hash32(n) {
  n = (n ^ 61) ^ (n >>> 16);
  n = (n + (n << 3)) | 0;
  n = n ^ (n >>> 4);
  n = Math.imul(n, 0x27d4eb2d);
  return (n ^ (n >>> 15)) >>> 0;
}

// The name a rung's boss will carry, built from the same roll the fight uses.
function bossTitle(L) {
  return deceiverName((L.mutators || []).map(id => MUTATOR_BY_ID[id]).filter(Boolean));
}

// The first thing that is unusual about a rung's boss, said plainly. This is
// where the mutator flavour lives -- read before you descend, not shouted at
// you while he arrives.
function bossNote(L) {
  const m = MUTATOR_BY_ID[(L.mutators || [])[0]];
  return m ? ' \u2014 ' + m.note : '';
}

function deceiverName(ms) {
  if (!ms.length) return 'The Gilded Deceiver';
  const n = ms.map(m => m.name);
  const last = n.pop();
  return 'The Deceiver, ' + (n.length ? n.join(', ') + ' and ' + last : last);
}

function rollMutators(index, depth) {
  // Math.min/max rather than clamp: this runs while LEVELS is being built,
  // which is before clamp's own const is initialised. The same shape of bug
  // took the whole page down once before.
  const want = Math.max(1, Math.min(3, 1 + Math.round(depth * 2)));
  const out = [];
  let h = hash32(index * 2654435761 + 17);
  for (let i = 0; i < want; i++) {
    for (let k = 0; k < MUTATORS.length; k++) {
      const pick = MUTATORS[(h + k * 7) % MUTATORS.length];
      if (out.indexOf(pick.id) >= 0) continue;
      out.push(pick.id);
      break;
    }
    h = hash32(h + i + 1);
  }
  return out;
}

/* --- the onboarding ramp --------------------------------------------------
   The first three rungs teach the game by leaving things out of it, not by
   explaining them. Each one adds exactly one thing the player has to have an
   answer for, and until they have met it nothing else is allowed to arrive at
   the same time:

     the mouth   thralls and the gate, and nothing else. Walk, cut, gather,
                 leave. No champion, no pitch, no invader, no epithet on the
                 avatar, and no escort holding him.
     the second  eclipses. Something that does not come at you down the middle,
                 met while nothing else is complicating the room.
     the third   breakers and pitch. Ground that has to be taken, and ground
                 that cannot be stood on.
     the fourth  husks, carrying their own detonation.
     the fifth   cantors, which never close.
     the sixth   flayers, which wait out of the fight and take your back.
     the seventh gorgers, heavy enough to break the ground they land on.
     the eighth  shamans, which never come forward at all.

   From the ninth the delve is the whole game. Nothing here is announced --
   the player is not told a lesson is happening, only handed one thing at a
   time until they are not being handed things any more. Past the eighth rung
   the roster does not grow again; what changes is how much of it turns up.
   -------------------------------------------------------------------- */
const RAMP = [
  { horde: ['thrall'],
    elites: 0, pitch: 0, invade: 0, guard: 0, mutate: false,
    lesson: 'Cut, gather, and find the ley-gate.' },
  { horde: ['thrall', 'eclipse'],
    elites: 0.05, pitch: 0, invade: 0, guard: 1, mutate: false,
    lesson: 'Some of them will not come at you down the middle.' },
  { horde: ['thrall', 'eclipse', 'breaker'],
    elites: 0.11, pitch: 0.4, invade: 0, guard: 1, mutate: true,
    lesson: 'Some ground is held. Some cannot be stood on.' },
  { horde: ['thrall', 'eclipse', 'breaker', 'husk'],
    elites: 0.13, pitch: 0.5, invade: 0, guard: 1, mutate: true,
    lesson: 'Some of them are carrying it with them. Break those early.' },
  { horde: ['thrall', 'eclipse', 'breaker', 'husk', 'cantor'],
    elites: 0.15, pitch: 0.6, invade: 1, guard: 1, mutate: true,
    lesson: 'Some of them never close at all. Put stone between you.' },
  { horde: ['thrall', 'eclipse', 'breaker', 'husk', 'cantor', 'flayer'],
    elites: 0.16, pitch: 0.6, invade: 1, guard: -1, mutate: true,
    lesson: 'Something is waiting in the dark for your back to turn.' },
  { horde: ['thrall', 'eclipse', 'breaker', 'husk', 'cantor', 'flayer', 'gorger'],
    elites: 0.17, pitch: 0.65, invade: 1, guard: -1, mutate: true,
    lesson: 'One of them breaks the floor it lands on. Do not be on it.' },
  { horde: ['thrall', 'eclipse', 'breaker', 'husk', 'cantor', 'flayer', 'gorger', 'shaman'],
    elites: 0.18, pitch: 0.7, invade: 1, guard: -1, mutate: true,
    lesson: 'One of them fights from the back. Reach it or fight in its fire.' }
];

// The roster once the ramp has finished teaching: everything.
const FULL_HORDE = RAMP[RAMP.length - 1].horde.slice();

function buildLevels() {
  const out = [];
  const regions = ['slag', 'vaelk', 'kraggen', 'weald', 'firth'];
  for (let i = 0; i < LEVEL_COUNT; i++) {
    const d = i / (LEVEL_COUNT - 1);                 // 0 at the mouth, 1 at the deep
    const name = i < DELVE_NAMES.length
      ? DELVE_NAMES[i]
      : DELVE_NAMES[i % DELVE_NAMES.length] + ' \u00b7 ' +
        ['II', 'III', 'IV'][Math.floor(i / DELVE_NAMES.length) - 1];
    // Region pool widens as you go down: the first delves are one place, the
    // deepest could be cut from anywhere in the realm.
    const pool = i === 0 ? regions.slice()
               : regions.slice(0, Math.min(regions.length, 1 + Math.floor(d * 5)));
    const ramp = RAMP[i];
    const horde = ramp ? ramp.horde.slice() : FULL_HORDE.slice();
    out.push({
      id: i === 0 ? 'test' : 'delve' + i,
      name: name,
      tag: i === 0 ? 'TEST LEVEL' : 'DELVE ' + i,
      note: i === 0
        ? 'A proving ground cut across all five regions of the Shattered Realm.'
        : 'Cut from ' + pool.length + (pool.length === 1 ? ' region' : ' regions') +
          ' of the Shattered Realm.',
      regions: pool,
      horde: horde,
      boss: 'deceiver',
      // The first rungs meet the avatar plainly. An epithet is a rule you have
      // to read, and there is nothing to read it against yet.
      mutators: (!ramp || ramp.mutate) ? rollMutators(i, d) : [],
      elites: ramp ? ramp.elites : ELITE_CHANCE,
      pitch: ramp ? ramp.pitch : PITCH_RATE,
      invade: ramp ? ramp.invade : 1,
      guard: ramp ? ramp.guard : -1,       // -1 means "however deep it is"
      lesson: ramp ? ramp.lesson : null,
      // Expected power, and the terms that follow from it.
      power: Math.round(4 + d * 96),
      depth: d,
      quota: Math.round(125 + d * 145),
      channel: 4.0
    });
  }
  return out;
}
const LEVELS = buildLevels();

/* Difficulty is the bargain the genre runs on: harder ground pays better.
   Threat scales enemy health and damage; the loot rates scale how often gear
   falls and how often a piece of the Regalia is among it. `riven` carries the
   values the balance harness was tuned against. */
const DIFFICULTIES = [
  { id:'harrowed', name:'Harrowed', threat:1.00, lootRate:0.85, setRate:0.6,
    note:'A delve you can learn on.' },
  { id:'riven',    name:'Riven',    threat:1.42, lootRate:1.00, setRate:1.0,
    note:'The Rivenmark as it is. Roughly one delve in three ends at the gate.' },
  { id:'sundered', name:'Sundered', threat:1.95, lootRate:1.35, setRate:1.8,
    note:'Champions in every hall. The Regalia surfaces here.' }
];
const DIFF_BY_ID = {};
for (const d of DIFFICULTIES) DIFF_BY_ID[d.id] = d;
let DIFF = DIFF_BY_ID.riven;

const LEVEL_BY_ID = {};
for (const L of LEVELS) {
  if (L.quota   == null) L.quota   = EXTRACT_QUOTA;
  if (L.channel == null) L.channel = EXTRACT_CHANNEL;
  LEVEL_BY_ID[L.id] = L;
}

// How a delve's expected power compares with what you are carrying. Advisory,
// not a gate: the ladder guides, it does not lock the door.
function delveStanding(L, pw) {
  const d = pw - L.power;
  if (d >= 14) return { id: 'trivial', text: 'well within you', colour: '#7fa869' };
  if (d >= 0)  return { id: 'even',    text: 'an even match',   colour: '#c4b795' };
  if (d >= -12) return { id: 'hard',   text: 'above your weight', colour: '#c9863e' };
  return { id: 'deadly', text: 'far beyond you', colour: '#c0503f' };
}
const REGION_BY_ID = {};
for (const R of REGIONS) REGION_BY_ID[R.id] = R;

/* --- the Vanguard's own strength ------------------------------------------
   Slag is experience now and nothing else: it drives a hero level that
   persists across delves. Boons chosen mid-run are gone -- power comes from
   the level you have earned and the gear you are wearing, and both survive
   the delve that won them.
   ---------------------------------------------------------------------- */
const HERO_MAX_LEVEL = 60;

// Slag needed to reach a given level, from 1. Deliberately shallow early and
// steep late, so the first delves move and the fiftieth still means something.
function xpForLevel(l) {
  return Math.round(38 * Math.pow(l, 1.62));
}
function levelForXp(xp) {
  let l = 1;
  while (l < HERO_MAX_LEVEL && xp >= xpForLevel(l + 1)) l++;
  return l;
}

// What a level is worth on the sheet. Flat and legible rather than clever:
// the interesting numbers are supposed to come off the gear.
function heroLevelBonus(l) {
  const n = l - 1;
  return { maxHp: n * 6, damage: n * 1.15, ward: Math.min(0.12, n * 0.0022) };
}

/* Power level: one number for "how strong am I", averaging what the hero
   brings with what the kit brings, so a level-40 hero in rags and a level-10
   hero in a full set both read honestly. It is what the delve ladder is
   measured against. */
function itemPower(it) {
  if (!it) return 0;
  const tier = RARITY.findIndex(r => r.id === it.rarity);
  let p = 6 + tier * 5;
  for (const af of it.affixes) {
    const a = AFFIX_BY_ID[af.id];
    if (!a) continue;
    p += a.mul ? Math.abs(af.v) * 90 : Math.abs(af.v) * (a.id === 'life' ? 0.5 : 2.2);
  }
  return p;
}
function powerLevel(gear, level) {
  let kit = 0;
  for (const sl of SLOTS) kit += itemPower(gear && gear[sl.id]);
  kit /= SLOTS.length;                       // average, not sum
  return Math.max(1, Math.round((level * 2.1 + kit) / 2));
}
const stashPower = () => powerLevel(stash.gear, stash.level || 1);

const UPGRADES = [
  { id:'dmg',    glyph:'✦', name:'Keen Edge',   desc:'your ward bites a quarter deeper',   max:99, apply:p=>p.damage      *= 1.25 },
  { id:'rate',   glyph:'❧', name:'Quickening',  desc:'the blade answers faster',           max:8,  apply:p=>p.fireDelay   *= 0.85 },
  { id:'speed',  glyph:'❯', name:'Windstep',    desc:'your stride lengthens',              max:6,  apply:p=>p.speed       *= 1.10 },
  { id:'plate',  glyph:'❖', name:'Ironhide',    desc:'+25 life, and 25 mended now',        max:99, apply:p=>{p.maxHp += 25;}, onTake:p=>{p.hp = Math.min(p.maxHp, p.hp + 25);} },
  { id:'range',  glyph:'◎', name:'Long Reach', desc:'your crescents carry a seventh further', max:5, apply:p=>p.range   *= 1.15 },
  { id:'split',  glyph:'⁂', name:'Twin Crescent', desc:'a second crescent leaves the edge',   max:4,  apply:p=>p.shots    += 1 },
  { id:'pierce', glyph:'⌁', name:'Broad Sweep',   desc:'your arc cuts a wider swathe',        max:4,  apply:p=>p.sweep    *= 1.22 },
  { id:'magnet', glyph:'❂', name:'Soul Draw',   desc:'essence comes to you from further',  max:4,  apply:p=>p.magnet      *= 1.5 },
  { id:'regen',  glyph:'✚', name:'Mending',     desc:'0.8 life knits back each second',    max:5,  apply:p=>p.regen       += 0.8 },
  { id:'vel',    glyph:'➤', name:'Swift Edge',    desc:'your crescents run a fifth faster',   max:4,  apply:p=>p.arcSpeed *= 1.20 }
];

/* ---------------------------------------------------------------------------
   GEAR

   Power comes from two places that stack: boons, chosen on rank-up and fixed
   for the run, and gear, found on the floor and swapped freely. Because gear
   comes off as easily as it goes on, no stat can be accumulated by mutating
   the player -- everything is recomputed from the hero's base each time
   anything changes. See recomputeStats.
   ------------------------------------------------------------------------ */

// Both heroes fight unhelmeted, which the compendium is explicit about, so
// there is no head slot to put a helm in.
// The mark is what a cell shows instead of a bare colour. A vault of a
// hundred and twenty identical squares sorted by pickup order is a pile, not
// an inventory -- you cannot find a blade in it without opening every one.
const SLOTS = [
  // A dagger, not crossed swords: U+2694 falls back to a thin cross in most
  // system fonts, and in a grid of buttons a cross reads as "discard".
  { id:'blade',   name:'Blade',    mark:'\u2020' },
  { id:'offhand', name:'Off-hand', mark:'\u25d6' },
  { id:'mail',    name:'Mail',     mark:'\u2593' },
  { id:'girdle',  name:'Girdle',   mark:'\u2550' },
  { id:'boots',   name:'Boots',    mark:'\u25e2' },
  { id:'amulet',  name:'Amulet',   mark:'\u2727' },
  { id:'ring1',   name:'Ring',     mark:'\u25cb' },
  { id:'ring2',   name:'Ring',     mark:'\u25cb' }
];
// Cell index into the icon strip. Both rings share one -- they are the same
// object worn twice -- and the last three are not slots at all.
// Cell indices into the icon strip. The first ten are the slot fallbacks and
// the loose glyphs; every base name after that has its own, so a Falchion and
// a Glaive are no longer the same picture with a different word under it.
// Built by tools/build-art.py, which owns both this order and the strip.
const ICON = { blade:0, offhand:1, mail:2, girdle:3, boots:4, amulet:5,
               ring1:6, ring2:6, ring:6, coin:7, skull:8, gem:9,
               'Longsword':10, 'Falchion':11, 'Warblade':12, 'Glaive':13,
               'Cleaver':14,
               'Kite Shield':15, 'Buckler':16, 'Warding Focus':17,
               'Tower Shield':18,
               'Ringmail':19, 'Scale Hauberk':20, 'Plated Coat':21,
               'Padded Jack':22,
               'Leather Girdle':23, 'Plated Belt':24, 'Sash of Cord':25,
               'Marching Boots':26, 'Greaves':27, 'Soft Treads':28,
               'Bone Amulet':29, 'Ley-Charm':30, 'Sun Pendant':31,
               'Iron Band':32, 'Signet':33, 'Twisted Ring':34 };
const icoTag = (key, px) =>
  '<i class="ico" style="--i:' + (ICON[key] || 0) + ';--sz:' + px + 'px"></i>';
// What an item should be drawn as: its own base if the strip carries one,
// otherwise whatever its slot uses.
const icoKey = it => (it && ICON[it.base] !== undefined) ? it.base
                   : (it ? it.slot : 'blade');

// A price, with the coin drawn rather than spelled. The icon comes off the
// same strip as everything else, so it is graded into the palette already.
const coinTag = n => icoTag('coin', 13) + '<span class="coinN">' + n + '</span>';

const SLOT_BY_ID = {};
for (const s of SLOTS) SLOT_BY_ID[s.id] = s;

// Colours are the classic ladder -- white, green, blue, purple, orange -- so a
// tier means here what it means in every other game the player has met. `tier`
// is the class the interface hangs off it, and lives beside the colour so the
// two can never drift apart.
const RARITY = [
  { id:'worn',    name:'Worn',           colour:'#e8e2d4', tier:'common',   affixes:1, weight:52 },
  { id:'tempered',name:'Tempered',       colour:'#3fc44a', tier:'uncommon', affixes:2, weight:28 },
  { id:'wrought', name:'Spirit-wrought', colour:'#3a7ffb', tier:'rare',     affixes:3, weight:14 },
  { id:'hallowed',name:'Hallowed',       colour:'#a238e6', tier:'epic',     affixes:4, weight:5  },
  { id:'riven',   name:'Riven',          colour:'#ff8000', tier:'legend',   affixes:5, weight:1  },
  // Never rolled by rollRarity -- set pieces are the only mythics, and they
  // come off elites and the avatar rather than out of the ordinary drop table.
  { id:'mythic',  name:'Mythic',         colour:'#e0563f', tier:'set',      affixes:5, weight:0  }
];

/* --- The Sundered Regalia -------------------------------------------------
   One set, eight pieces, one per slot. Pieces drop only from elites and from
   the Deceiver. Each carries fixed, better-than-random affixes, and wearing
   several together pays a bonus on top -- so a half-set is a real decision
   against eight good rolled items rather than an obvious upgrade.
   ---------------------------------------------------------------------- */
const SET_ID = 'regalia';
const SET_NAME = 'The Sundered Regalia';
const SET_PIECES = {
  blade:   { base:'Aegis-Shard Blade',  affixes:[['damage',9],['damageP',0.22],['cadence',-0.12],['reach',0.12],['sweep',0.14]] },
  offhand: { base:'Unbroken Ward',      affixes:[['ward',0.10],['life',30],['damageP',0.12],['regen',0.7],['sweep',0.10]] },
  mail:    { base:'Hauberk of the Vigil',affixes:[['life',38],['ward',0.09],['regen',0.8],['speed',0.07],['damageP',0.10]] },
  girdle:  { base:'Girdle of Held Light',affixes:[['life',26],['ward',0.07],['magnet',0.35],['regen',0.6],['speed',0.05]] },
  boots:   { base:'Treads of the Last March',affixes:[['speed',0.12],['life',22],['ward',0.05],['magnet',0.25],['regen',0.4]] },
  amulet:  { base:'Pendant of Dúath',   affixes:[['damageP',0.20],['life',24],['regen',0.7],['magnet',0.30],['reach',0.10]] },
  ring1:   { base:'Band of the Vigil',  affixes:[['damage',7],['damageP',0.14],['life',18],['ward',0.05],['cadence',-0.08]] },
  ring2:   { base:'Band of the Vigil',  affixes:[['damage',7],['damageP',0.14],['life',18],['ward',0.05],['cadence',-0.08]] }
};
// Bonuses granted for wearing N pieces. Additive terms and multipliers are
// folded in by recomputeStats exactly like an affix, so nothing special has to
// happen anywhere else.
const SET_BONUSES = [
  { at:2, text:'+18 life, +5% ward',           add:{ maxHp:18, ward:0.05 } },
  { at:4, text:'+12% damage, +8% stride',      mul:{ damage:0.12, speed:0.08 } },
  { at:6, text:'+10% reach and sweep, +1 life a second',
                                               mul:{ range:0.10, sweep:0.10 }, add:{ regen:1.0 } },
  { at:8, text:'a second crescent with every strike', add:{ shots:1 } }
];

function rollSetPiece(slotId) {
  const slot = slotId || SLOTS[(Math.random() * SLOTS.length) | 0].id;
  const def = SET_PIECES[slot];
  return { uid: ++itemSeq, slot, base: def.base, rarity: 'mythic', set: SET_ID,
           affixes: def.affixes.map(a => ({ id: a[0], v: a[1] })),
           name: def.base };
}

const setWorn = p => SLOTS.reduce((n, sl) =>
  n + (p.gear[sl.id] && p.gear[sl.id].set === SET_ID ? 1 : 0), 0);

// Base items per slot. `key` picks which affix pool the base leans on, so a
// blade rolls like a weapon and boots roll like boots.
const BASES = {
  blade:   ['Longsword', 'Falchion', 'Warblade', 'Glaive', 'Cleaver'],
  offhand: ['Kite Shield', 'Buckler', 'Warding Focus', 'Tower Shield'],
  mail:    ['Ringmail', 'Scale Hauberk', 'Plated Coat', 'Padded Jack'],
  girdle:  ['Leather Girdle', 'Plated Belt', 'Sash of Cord'],
  boots:   ['Marching Boots', 'Greaves', 'Soft Treads'],
  amulet:  ['Bone Amulet', 'Ley-Charm', 'Sun Pendant'],
  ring1:   ['Iron Band', 'Signet', 'Twisted Ring'],
  ring2:   ['Iron Band', 'Signet', 'Twisted Ring']
};

// An affix is a stat, a roll range, and how it is worded. `mul` stats are
// multiplicative and stack by product; the rest add.
const AFFIXES = [
  { id:'damage',  stat:'damage',    mul:false, lo:2,    hi:7,    dp:0, name:'Keen',      word:'+@ damage' },
  { id:'damageP', stat:'damage',    mul:true,  lo:0.06, hi:0.20, dp:0, name:'Cruel',     word:'+@ damage' },
  { id:'life',    stat:'maxHp',     mul:false, lo:8,    hi:26,   dp:0, name:'Stout',     word:'+@ life' },
  { id:'ward',    stat:'ward',      mul:false, lo:0.03, hi:0.09, dp:0, pct:true,
    name:'Warded',    word:'@ harm turned' },
  { id:'speed',   stat:'speed',     mul:true,  lo:0.03, hi:0.09, dp:0, name:'Fleet',     word:'+@ stride' },
  { id:'reach',   stat:'range',     mul:true,  lo:0.04, hi:0.13, dp:0, name:'Far',       word:'+@ reach' },
  { id:'sweep',   stat:'sweep',     mul:true,  lo:0.05, hi:0.16, dp:0, name:'Broad',     word:'+@ sweep' },
  { id:'cadence', stat:'fireDelay', mul:true,  lo:-0.12,hi:-0.04,dp:0, name:'Quick',     word:'@ swing time' },
  { id:'magnet',  stat:'magnet',    mul:true,  lo:0.10, hi:0.35, dp:0, name:'Drawing',   word:'+@ draw' },
  { id:'regen',   stat:'regen',     mul:false, lo:0.2,  hi:0.9,  dp:1, name:'Mending',   word:'+@ life a second' }
];
// Global dial on how much a roll is worth. Gear should be felt, but a full kit
// of eight items multiplies together fast: at 1.0 the bot's escape rate went
// from 30% to 73%. Left mutable so the balance harness can sweep it.
let AFFIX_SCALE = 1;

/* Some affixes suit one hero far more than the other, and say so. A `hero`
   tag pays a bonus when it is worn by the Vanguard it was made for, which
   turns "which is the bigger number" into "which is the bigger number for me"
   -- and gives the two heroes genuinely different best-in-slot. */
const SYNERGY = [
  { id:'isaacWard',  hero:'isaac', stat:'ward',   mul:false, lo:0.04, hi:0.10, dp:0, pct:true,
    name:"Warden's",  word:'@ harm turned',
    slots:['offhand','mail','girdle','ring1','ring2'] },
  { id:'isaacSweep', hero:'isaac', stat:'sweep',  mul:true,  lo:0.10, hi:0.26, dp:0,
    name:'Sun-Wide',  word:'+@ sweep',
    slots:['blade','offhand','amulet'] },
  { id:'zaydReach',  hero:'zayd',  stat:'range',  mul:true,  lo:0.10, hi:0.24, dp:0,
    name:'Glaive-Cut', word:'+@ reach',
    slots:['blade','amulet','ring1','ring2'] },
  { id:'zaydHaste',  hero:'zayd',  stat:'fireDelay', mul:true, lo:-0.20, hi:-0.08, dp:0,
    name:'Frost-Quick', word:'@ swing time',
    slots:['blade','boots','ring1','ring2'] }
];
for (const sy of SYNERGY) AFFIXES.push(sy);
// The slot pools are declared below, so registering into them waits until
// they exist -- see the loop after SLOT_AFFIXES.
// Worn by the hero it was forged for, a synergy affix is worth half again.
const SYNERGY_BONUS = 1.5;

const AFFIX_BY_ID = {};
for (const a of AFFIXES) AFFIX_BY_ID[a.id] = a;

// Which affixes a slot can roll. Keeps a blade feeling like a blade.
const SLOT_AFFIXES = {
  blade:   ['damage','damageP','reach','sweep','cadence'],
  offhand: ['ward','life','damageP','sweep','regen'],
  mail:    ['life','ward','regen','speed'],
  girdle:  ['life','ward','magnet','regen'],
  boots:   ['speed','life','magnet','ward'],
  amulet:  ['damageP','life','regen','magnet','reach'],
  ring1:   ['damage','damageP','life','ward','speed','magnet','cadence'],
  ring2:   ['damage','damageP','life','ward','speed','magnet','cadence']
};

// Hero-tagged affixes join the pools of the slots they were forged for. Done
// here rather than beside SYNERGY itself because the pools are declared after
// it, and touching them earlier is a temporal-dead-zone error that takes the
// whole page down at load.
for (const sy of SYNERGY) {
  for (const sl of sy.slots) if (SLOT_AFFIXES[sl]) SLOT_AFFIXES[sl].push(sy.id);
}

function rollRarity(depth) {
  // Deeper ground gives up better things. Shift weight off the bottom tier.
  const lift = 1 + depth * 2.4;
  let total = 0;
  const w = RARITY.map((r, i) => {
    const ww = i === 0 ? r.weight / lift : r.weight * (1 + depth * i * 0.5);
    total += ww;
    return ww;
  });
  let roll = Math.random() * total;
  for (let i = 0; i < RARITY.length; i++) {
    roll -= w[i];
    if (roll <= 0) return RARITY[i];
  }
  return RARITY[0];
}

let itemSeq = 0;

function rollItem(depth, slotId) {
  const slot = slotId || SLOTS[(Math.random() * SLOTS.length) | 0].id;
  const rarity = rollRarity(clamp(depth, 0, 1));
  const bases = BASES[slot];
  const base = bases[(Math.random() * bases.length) | 0];
  const pool = SLOT_AFFIXES[slot].slice();
  const affixes = [];
  const n = Math.min(rarity.affixes, pool.length);
  // Item level lifts the rolls, so a deep drop is better than a shallow one of
  // the same rarity rather than merely more likely.
  const ilvl = (0.55 + clamp(depth, 0, 1) * 0.75 + (LEVEL.depth || 0) * 0.9) * AFFIX_SCALE;
  for (let i = 0; i < n; i++) {
    const id = pool.splice((Math.random() * pool.length) | 0, 1)[0];
    const a = AFFIX_BY_ID[id];
    let v = (a.lo + Math.random() * (a.hi - a.lo)) * ilvl;
    v = a.dp ? +v.toFixed(a.dp) : (Math.abs(a.lo) >= 1 ? Math.max(1, Math.round(v)) : v);
    affixes.push({ id, v });
  }
  return { uid: ++itemSeq, slot, base, rarity: rarity.id, affixes,
           name: affixes.length ? AFFIX_BY_ID[affixes[0].id].name + ' ' + base : base };
}

function affixText(af, hero) {
  const a = AFFIX_BY_ID[af.id];
  if (!a) return '';
  let v;
  // An additive affix whose roll is a fraction has to say so, or it prints the
  // float: the synergy ward is `isaacWard`, so keying the percentage off the
  // id `ward` missed it and put "+0.03952737067873269 harm turned" on the
  // card. `pct` is carried by the affix rather than inferred, so the next
  // fractional stat added does not have to rediscover this.
  if (a.mul || a.pct) v = (af.v >= 0 && !a.pct ? '+' : '') + Math.round(af.v * 100) + '%';
  else v = (af.v >= 0 ? '+' : '') + (a.dp ? af.v.toFixed(a.dp) : Math.round(af.v));
  let out = a.word.replace('+@', v).replace('@', v);
  if (a.hero) {
    out += ' \u2014 ' + HEROES[a.hero].name +
           (hero === a.hero ? ' (worn: half again)' : '');
  }
  return out;
}

const rarityOf = it => RARITY.find(r => r.id === it.rarity) || RARITY[0];

/* Rebuild every derived stat from the hero's base. Boons and gear both feed
   in here and nothing accumulates on the player, so a ring can come off
   without leaving its damage behind. Current life is preserved, only clamped,
   or swapping a +life item would be a free heal. */
function recomputeStats() {
  const p = player;
  const H = HEROES[p.hero] || HEROES.isaac;
  const base = Object.assign({}, BASE_PLAYER);
  base.maxHp = H.maxHp; base.speed = H.speed; base.damage = H.damage;
  base.fireDelay = H.fireDelay; base.range = H.range;
  base.sweep = H.sweep; base.arcSpeed = H.arcSpeed;
  base.ward = 0;

  // What the hero has earned. Applied before gear so the kit multiplies a
  // level's worth of strength rather than the other way round.
  const hb = heroLevelBonus(p.level || 1);
  base.maxHp += hb.maxHp;
  base.damage += hb.damage;
  base.ward += hb.ward;

  // The hall's own. Additive with the hero's level for the same reason: gear
  // should multiply everything you brought, not everything except this.
  const ws = wardStone();
  base.maxHp += ws.maxHp;
  base.ward += ws.ward;

  // Gear on top: additive terms first, then the multiplicative ones, so the
  // order two items were equipped in cannot change the result.
  const add = {}, mul = {};
  for (const sl of SLOTS) {
    const it = p.gear[sl.id];
    if (!it) continue;
    for (const af of it.affixes) {
      const a = AFFIX_BY_ID[af.id];
      if (!a) continue;
      // An affix forged for this Vanguard pays more in their hands.
      const k = (a.hero && a.hero === p.hero) ? SYNERGY_BONUS : 1;
      const v = af.v * k;
      if (a.mul) mul[a.stat] = (mul[a.stat] === undefined ? 1 : mul[a.stat]) * (1 + v);
      else add[a.stat] = (add[a.stat] || 0) + v;
    }
  }
  // Set bonuses ride in on the same two piles, so they cannot be applied twice
  // or in the wrong order relative to the affixes themselves.
  const worn = setWorn(p);
  for (const b of SET_BONUSES) {
    if (worn < b.at) continue;
    if (b.add) for (const k in b.add) add[k] = (add[k] || 0) + b.add[k];
    if (b.mul) for (const k in b.mul) mul[k] = (mul[k] === undefined ? 1 : mul[k]) * (1 + b.mul[k]);
  }

  for (const k in add) base[k] = (base[k] || 0) + add[k];
  for (const k in mul) base[k] = (base[k] || 0) * mul[k];

  base.ward = clamp(base.ward, 0, 0.75);      // never immune
  base.fireDelay = Math.max(0.08, base.fireDelay);

  for (const k in base) {
    if (k === 'r' || k === 'iframe') continue;
    p[k] = base[k];
  }
  p.hp = Math.min(p.hp, p.maxHp);
  hudCache.hp = -1;
}

/* ---------------------------------------------------------------------------
   2. MATH HELPERS
   ------------------------------------------------------------------------ */

const TAU = Math.PI * 2;
const clamp = (v, lo, hi) => v < lo ? lo : v > hi ? hi : v;
const lerp  = (a, b, t) => a + (b - a) * t;
const rand  = (a, b) => a + Math.random() * (b - a);
const dist2 = (ax, ay, bx, by) => { const dx = bx - ax, dy = by - ay; return dx*dx + dy*dy; };

// Shortest signed angle from a to b, so rotation never spins the long way round.
function angleDelta(a, b) {
  let d = (b - a) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d < -Math.PI) d += TAU;
  return d;
}

/* ---------------------------------------------------------------------------
   3. SPATIAL HASH
   Replaces the prototype's O(n^2) sweeps. Buckets are reused between frames --
   clear() empties the arrays instead of dropping them, so a steady-state frame
   allocates nothing.
   ------------------------------------------------------------------------ */

class SpatialHash {
  constructor(cell) {
    this.cell = cell;
    this.buckets = new Map();
    this.stride = Math.ceil(Math.max(WORLD.w, WORLD.h) / cell) + 4;
  }
  key(cx, cy) { return (cy + 2) * this.stride + (cx + 2); }
  clear() { for (const b of this.buckets.values()) b.length = 0; }
  insert(item, x, y) {
    const k = this.key(Math.floor(x / this.cell), Math.floor(y / this.cell));
    let b = this.buckets.get(k);
    if (!b) { b = []; this.buckets.set(k, b); }
    b.push(item);
  }
  // Collects everything in the cells overlapping the circle into `out`.
  // Callers still do the exact distance test; this only narrows the field.
  query(x, y, r, out) {
    out.length = 0;
    const c = this.cell;
    const x0 = Math.floor((x - r) / c), x1 = Math.floor((x + r) / c);
    const y0 = Math.floor((y - r) / c), y1 = Math.floor((y + r) / c);
    for (let cy = y0; cy <= y1; cy++) {
      for (let cx = x0; cx <= x1; cx++) {
        const b = this.buckets.get(this.key(cx, cy));
        if (b) for (let i = 0; i < b.length; i++) out.push(b[i]);
      }
    }
    return out;
  }
}

/* ---------------------------------------------------------------------------
   4. WORLD GENERATION
   ------------------------------------------------------------------------ */

let walls = [];              // {x,y,w,h} -- and {pit:true} for a chasm
let pitGrid = null;          // cells that are a hole rather than masonry
let wallGrid = null;         // SpatialHash of wall indices
let wallSeen = null;         // stamp buffer for deduping multi-cell walls
let wallStamp = 0;

function pointInWalls(x, y, pad) {
  const cand = wallsNear(x, y, pad + 2);
  for (let i = 0; i < cand.length; i++) {
    const w = walls[cand[i]];
    if (x > w.x - pad && x < w.x + w.w + pad &&
        y > w.y - pad && y < w.y + w.h + pad) return true;
  }
  return false;
}

/* --- cave generation ----------------------------------------------------
   Cellular automata gives organic rock; a carved skeleton of chambers and
   corridors gives the maze structure and guarantees the place is traversable.
   CA runs first, the skeleton is cut through it afterwards, then a flood fill
   from spawn fills in anything it could not reach -- so every open cell in the
   finished map is reachable from every other one.

   Collision still wants axis-aligned rectangles, so the finished grid is
   greedy-merged into as few rects as possible and handed to the same spatial
   hash and AABB code as before.
   ---------------------------------------------------------------------- */

const CELL_W = 40;                       // world units per cave cell
const GW = Math.floor(WORLD.w / CELL_W);
const GH = Math.floor(WORLD.h / CELL_W);
const SOLID = 1, OPEN = 0;

let grid = null;          // Uint8Array, row-major
let edges = [];           // {x1,y1,x2,y2,nx,ny} lit rock/floor boundaries
let props = [];           // {x,y,rot,kind} scenery instances
// Just the ones that can be broken, so the crescent's per-substep test walks a
// handful of entries rather than the several hundred pieces of furniture in a
// delve.
let propGrid = [];
let lamps = [];           // {x,y,color} ambient light sources
let openCells = [];       // {x,y} world centres of every reachable cell
// Walls touching each open cell, 0..4. A corridor scores 2, a dead end 3.
const narrowGrid = new Uint8Array(GW * GH);

const gi = (cx, cy) => cy * GW + cx;
const inGrid = (cx, cy) => cx >= 0 && cy >= 0 && cx < GW && cy < GH;
const cellAt = (cx, cy) => (inGrid(cx, cy) ? grid[gi(cx, cy)] : SOLID);

function carveDisc(cx, cy, r) {
  const r2 = r * r;
  for (let y = Math.max(1, cy - r); y <= Math.min(GH - 2, cy + r); y++) {
    for (let x = Math.max(1, cx - r); x <= Math.min(GW - 2, cx + r); x++) {
      const dx = x - cx, dy = y - cy;
      if (dx * dx + dy * dy <= r2) grid[gi(x, y)] = OPEN;
    }
  }
}

// L-shaped corridor, `half` cells either side of the centre line.
// An L of two rectangles. This used to step a disc along each leg, which left
// every corridor with a scalloped edge -- a row of overlapping circles rather
// than a straight cut -- and that read as the ragged winding passage it was.
function carveCorridor(ax, ay, bx, by, half) {
  carveRect(Math.min(ax, bx) - half, ay - half, Math.max(ax, bx) + half, ay + half);
  carveRect(bx - half, Math.min(ay, by) - half, bx + half, Math.max(ay, by) + half);
}

// A hollow rectangle of rock, with a gap left in the middle of each side.
// Landmarks are built from this rather than from rings of cells stepped round
// a circle: a ring rasterises to a staircase at this cell size, which is the
// opposite of a clean geometric block.
function carveWalls(x0, y0, x1, y1, gap) {
  const midX = (x0 + x1) >> 1, midY = (y0 + y1) >> 1;
  for (let x = x0; x <= x1; x++) {
    if (Math.abs(x - midX) > gap) { setCell(x, y0, SOLID); setCell(x, y1, SOLID); }
  }
  for (let y = y0; y <= y1; y++) {
    if (Math.abs(y - midY) > gap) { setCell(x0, y, SOLID); setCell(x1, y, SOLID); }
  }
}

function carveRect(x0, y0, x1, y1) {
  for (let y = Math.max(1, y0); y <= Math.min(GH - 2, y1); y++)
    for (let x = Math.max(1, x0); x <= Math.min(GW - 2, x1); x++)
      grid[gi(x, y)] = OPEN;
}

/* A depth-first maze over coarse cells, then braided: roughly a third of the
   remaining walls are knocked through, which turns a perfect maze (all dead
   ends, one route between any two points) into a looping network. Dead ends
   are death in a game where a horde follows you, and loops give both sides
   room to flank. */
/* The delve used to be solid rock with corridors cut out of it, which left the
   stone between them two to four cells thick -- a blobby mass rather than
   built walls. It is the other way round now: the ground is open, and single
   cell wall runs are laid along the maze boundaries that were never linked.
   Corridors are the space between walls, so the whole map reads as walled
   paths instead of tunnels bored through a lump. */
/* --- the layout ----------------------------------------------------------
   Rooms and corridors, not a maze. The maze this replaced was built by drawing
   single-cell wall lines on open ground, which is exactly what produced the
   narrow winding passages: every route was one cell wide, every wall was one
   cell thick, and the two were the same thing seen from opposite sides.

   This starts solid and cuts into it. A binary split carves the map into
   leaves, each leaf gets one axis-aligned rectangular room with rock left as a
   margin around it, and the rooms are joined by corridors three cells wide.
   Nothing is ever one cell of anything: the thinnest wall between two rooms is
   two cells and the narrowest floor is three, so corridors are walkable
   abreast and walls have a body to them.
   -------------------------------------------------------------------- */
function carveHalls() {
  const LY = REGION.layout || {};
  const CORR = LY.corridor || 3;          // corridor width, in cells
  const MINR = LY.roomMin || 6;           // shortest room side
  const MAXR = LY.roomMax || 13;          // and its longest
  const MARGIN = 2;                       // rock kept between a room and its leaf

  grid.fill(SOLID);

  const leaves = [];
  const minLeaf = MINR + MARGIN * 2 + 1;
  const split = (x, y, w, h, depth) => {
    const canW = w >= minLeaf * 2, canH = h >= minLeaf * 2;
    if (depth >= 6 || (!canW && !canH) || (depth >= 3 && Math.random() < 0.12)) {
      leaves.push({ x, y, w, h });
      return;
    }
    const horiz = canW && canH ? (w === h ? Math.random() < 0.5 : w > h) : canW;
    if (horiz) {
      const cut = minLeaf + ((Math.random() * (w - minLeaf * 2 + 1)) | 0);
      split(x, y, cut, h, depth + 1);
      split(x + cut, y, w - cut, h, depth + 1);
    } else {
      const cut = minLeaf + ((Math.random() * (h - minLeaf * 2 + 1)) | 0);
      split(x, y, w, cut, depth + 1);
      split(x, y + cut, w, h - cut, depth + 1);
    }
  };
  split(1, 1, GW - 2, GH - 2, 0);

  // One room per leaf, and capped in size rather than filling whatever leaf it
  // landed in. Letting a room take its whole leaf gave single chambers of
  // twenty-eight by twenty-seven that swallowed a quarter of the map each, and
  // the result read as open ground with rocks in it rather than as rooms. A
  // large leaf now holds a normal room with a lot of rock around it.
  const halls = [];
  for (const L of leaves) {
    const maxW = Math.min(MAXR, L.w - MARGIN * 2);
    const maxH = Math.min(MAXR, L.h - MARGIN * 2);
    if (maxW < MINR || maxH < MINR) continue;
    const w = MINR + ((Math.random() * (maxW - MINR + 1)) | 0);
    const h = MINR + ((Math.random() * (maxH - MINR + 1)) | 0);
    const x = L.x + MARGIN + ((Math.random() * (L.w - MARGIN * 2 - w + 1)) | 0);
    const y = L.y + MARGIN + ((Math.random() * (L.h - MARGIN * 2 - h + 1)) | 0);
    carveRect(x, y, x + w - 1, y + h - 1);
    halls.push({ x, y, w, h, cx: x + (w >> 1), cy: y + (h >> 1) });
  }

  // L-shaped joins, cut as two rectangles so a corridor is a clean run rather
  // than a chain of overlapping discs with a scalloped edge.
  const lo = (CORR - 1) >> 1, hi = CORR >> 1;
  const join = (a, b) => {
    const bendFirstX = Math.random() < 0.5;
    const kx = bendFirstX ? b.cx : a.cx;
    const ky = bendFirstX ? a.cy : b.cy;
    carveRect(Math.min(a.cx, kx) - lo, ky - lo, Math.max(a.cx, kx) + hi, ky + hi);
    carveRect(kx - lo, Math.min(a.cy, ky) - lo, kx + hi, Math.max(a.cy, ky) + hi);
    carveRect(Math.min(kx, b.cx) - lo, b.cy - lo, Math.max(kx, b.cx) + hi, b.cy + hi);
    carveRect(b.cx - lo, Math.min(ky, b.cy) - lo, b.cx + hi, Math.max(ky, b.cy) + hi);
  };

  // A spanning chain first so everything is reachable, then a few extra links
  // so the map loops rather than being one line of rooms.
  halls.sort((a, b) => (a.cx + a.cy) - (b.cx + b.cy));
  for (let i = 1; i < halls.length; i++) join(halls[i - 1], halls[i]);
  const extra = Math.max(1, halls.length >> 2);
  for (let i = 0; i < extra; i++) {
    const a = halls[(Math.random() * halls.length) | 0];
    const b = halls[(Math.random() * halls.length) | 0];
    if (a !== b) join(a, b);
  }

  // The rim of the world stays solid, so nothing walks off the edge.
  for (let y = 0; y < GH; y++)
    for (let x = 0; x < GW; x++)
      if (x < 1 || y < 1 || x >= GW - 1 || y >= GH - 1) grid[gi(x, y)] = SOLID;

  return halls;
}

function generateWorld(spawn, portal) {
  grid = new Uint8Array(GW * GH);
  const halls = carveHalls();

  // Roughening and widening both existed to break up a solid rock mass. With
  // walls a single cell thick there is no mass to break up -- flipping
  // boundary cells just punches holes through the walls and dissolves the
  // layout -- so neither pass runs any more.

  // Spawn pocket and portal apron, cut after the roughening so they are clean.
  const sc = { x: clamp(Math.floor(spawn.x / CELL_W), 2, GW - 3),
               y: clamp(Math.floor(spawn.y / CELL_W), 2, GH - 3) };
  const pc = { x: clamp(Math.floor(portal.x / CELL_W), 2, GW - 3),
               y: clamp(Math.floor(portal.y / CELL_W), 2, GH - 3) };
  carveRect(sc.x - 4, sc.y - 4, sc.x + 4, sc.y + 4);
  carveRect(pc.x - 3, pc.y - 3, pc.x + 3, pc.y + 3);
  carveCorridor(sc.x, sc.y, pc.x, pc.y, 1);   // never strand the objective


  // The lone-pillar sweep is gone with them: on a thin-wall map an isolated
  // cell is usually a corner post or the end of a run, not debris.

  dressRooms(halls, sc, pc);
  buildLandmark(pc);
  connectPortal(sc, pc);

  // The apron was cut before the landmark was built, and a landmark is built
  // at the same centre -- a curtain wall or a redoubt puts solid cells straight
  // back over the gate. Cut it again, last, wide enough for the whole gate
  // circle plus a body, so the extraction point can never load inside rock.
  const apron = Math.ceil((PORTAL_R + 22) / CELL_W) + 1;
  carveRect(pc.x - apron, pc.y - apron, pc.x + apron, pc.y + apron);

  // Keep only what is reachable from spawn; everything else becomes rock.
  const seen = indexOpenCells(sc);
  for (let k = 0; k < grid.length; k++) if (!seen[k]) grid[k] = SOLID;

  buildWallRects();
  cutChasms(sc, pc);
  // A chasm turns standable floor into a hole, so the index has to be taken
  // again. Without this every pass that samples openCells -- pack seeding,
  // scenery, the loot scatter, the corpse, the ambush ring -- can drop
  // something into a pit, and a body that starts inside a wall rect is
  // resolved out of it at the next step. That was invisible while the rock
  // was thin maze wall; with rooms cut from continuous masses the same rect
  // is hundreds of units across and the body left the room.
  indexOpenCells(sc);
  buildEdges();
  buildStains(spawn, portal);
  buildScenery(spawn, portal);
}

// Flood from the spawn: every cell you can actually stand on, and how penned
// in each one is. Called once before the unreachable rock is filled in, and
// again after the chasms are cut, since a chasm takes floor away.
function indexOpenCells(sc) {
  const seen = new Uint8Array(GW * GH);
  const stack = [gi(sc.x, sc.y)];
  seen[stack[0]] = 1;
  openCells = [];
  narrowGrid.fill(0);
  while (stack.length) {
    const k = stack.pop();
    const cx = k % GW, cy = (k / GW) | 0;
    openCells.push({ x: cx * CELL_W + CELL_W / 2, y: cy * CELL_W + CELL_W / 2 });
    // How penned in this cell is, 0 (a crossroads) to 4 (a dead end). The
    // anchors read it to find ground worth holding.
    let walls = 0;
    if (cellAt(cx + 1, cy) === SOLID) walls++;
    if (cellAt(cx - 1, cy) === SOLID) walls++;
    if (cellAt(cx, cy + 1) === SOLID) walls++;
    if (cellAt(cx, cy - 1) === SOLID) walls++;
    narrowGrid[k] = walls;
    for (let i = 0; i < 4; i++) {
      const nx = cx + (i === 0 ? 1 : i === 1 ? -1 : 0);
      const ny = cy + (i === 2 ? 1 : i === 3 ? -1 : 0);
      if (!inGrid(nx, ny)) continue;
      const nk = gi(nx, ny);
      if (seen[nk] || grid[nk] === SOLID) continue;
      seen[nk] = 1; stack.push(nk);
    }
  }
  return seen;
}

// A curtain wall can seal its own gate, and Vaelk's rifts can strand a corner.
// Rather than forbid that, prove reachability and repair the one case that
// matters: flood from spawn, and if the gate is not in the reached set, cut
// the shortest link to it. Scars the map far less than carving blind.
function connectPortal(sc, pc) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const seen = new Uint8Array(GW * GH);
    const q = [gi(sc.x, sc.y)];
    if (grid[q[0]] === SOLID) carveRect(sc.x - 2, sc.y - 2, sc.x + 2, sc.y + 2);
    seen[q[0]] = 1;
    let best = -1, bestD = Infinity;
    while (q.length) {
      const k = q.pop();
      const x = k % GW, y = (k / GW) | 0;
      if (x === pc.x && y === pc.y) return true;
      const d = (x - pc.x) * (x - pc.x) + (y - pc.y) * (y - pc.y);
      if (d < bestD) { bestD = d; best = k; }
      for (let i = 0; i < 4; i++) {
        const nx = x + (i === 0 ? 1 : i === 1 ? -1 : 0);
        const ny = y + (i === 2 ? 1 : i === 3 ? -1 : 0);
        if (!inGrid(nx, ny)) continue;
        const nk = gi(nx, ny);
        if (seen[nk] || grid[nk] === SOLID) continue;
        seen[nk] = 1; q.push(nk);
      }
    }
    if (best < 0) return false;
    carveCorridor(best % GW, (best / GW) | 0, pc.x, pc.y, 1);
  }
  return false;
}

// The place the region is named for. Built around the ley-gate, because the
// objective should be somewhere, not a circle on blank ground.
function setCell(cx, cy, v) { if (inGrid(cx, cy)) grid[gi(cx, cy)] = v; }

/* --- room archetypes -----------------------------------------------------
   A braided maze is uniform corridor and near-uniform chamber: nothing you
   would recognise on the way back. These stamp a handful of rooms with a shape
   you can name, and record themselves so the stain layer and the scenery pass
   can dress each one to match.
   --------------------------------------------------------------------- */
let rooms = [];

/* Dress rooms that already exist rather than cutting new ones. This used to
   carve three to five more rectangles on top of the layout and run a corridor
   from each to the gate, and between the extra rooms and the extra channels
   the map stopped being rooms-and-corridors and became one connected cavern.
   The layout decides where the rooms are; this decides what is in them. */
function dressRooms(halls, sc, pc) {
  rooms = [];
  const KINDS = ['hall', 'barracks', 'collapse', 'cistern'];
  const want = Math.min(halls.length, 3 + ((Math.random() * 3) | 0));
  const picked = [];

  for (const h of halls) {
    if (picked.length >= want) break;
    if (h.w < 7 || h.h < 6) continue;                 // too small to furnish
    const near = (a, b) => Math.abs(h.cx - a) + Math.abs(h.cy - b) < 10;
    if (near(sc.x, sc.y) || near(pc.x, pc.y)) continue;
    picked.push(h);
  }

  for (const h of picked) {
    const kind = KINDS[(Math.random() * KINDS.length) | 0];
    const x0 = h.x + 1, y0 = h.y + 1;
    const x1 = h.x + h.w - 2, y1 = h.y + h.h - 2;

    if (kind === 'hall') {
      // Pillars on a regular grid: the one shape that reads as built rather
      // than as eroded, and it gives a fight cover to break line of sight on.
      for (let py = y0 + 1; py <= y1 - 1; py += 3)
        for (let px = x0 + 1; px <= x1 - 1; px += 3) setCell(px, py, SOLID);
    } else if (kind === 'barracks') {
      // Stub walls in rows, like bunk partitions off one side.
      for (let py = y0 + 1; py <= y1 - 1; py += 2) {
        const len = 1 + ((Math.random() * Math.max(1, h.w - 3)) | 0);
        for (let px = 0; px < len; px++) setCell(x0 + px, py, SOLID);
      }
    } else if (kind === 'collapse') {
      // A caved-in ceiling: a scatter of loose blocks, no pattern at all.
      const n = 4 + ((Math.random() * 5) | 0);
      for (let i = 0; i < n; i++) {
        setCell(x0 + ((Math.random() * (x1 - x0 + 1)) | 0),
                y0 + ((Math.random() * (y1 - y0 + 1)) | 0), SOLID);
      }
    }
    // a cistern is left bare -- a wide empty room is its own kind of place

    const half = Math.max(h.w, h.h) >> 1;
    rooms.push({ kind, cx: h.cx, cy: h.cy, half,
                 x: h.cx * CELL_W + CELL_W / 2, y: h.cy * CELL_W + CELL_W / 2,
                 r: half * CELL_W });
  }
}

function buildLandmark(pc) {
  const kind = REGION.build;
  const cx = clamp(pc.x, 10, GW - 11), cy = clamp(pc.y, 10, GH - 11);
  // Every landmark used to be a ring of cells stepped round a circle, which at
  // a forty-unit cell rasterises to a staircase. They are built square now --
  // curtain walls, colonnades and bars -- so the place at the gate reads as
  // masonry someone laid rather than as a scribble of blocks.

  if (kind === 'keep') {
    // A ruined curtain wall with a breach in each side, and a broken inner ward.
    carveRect(cx - 8, cy - 8, cx + 8, cy + 8);
    carveWalls(cx - 7, cy - 7, cx + 7, cy + 7, 2);
    carveWalls(cx - 3, cy - 3, cx + 3, cy + 3, 1);
    for (let i = -3; i <= 3; i += 3) {                   // collapsed corners
      setCell(cx - 4 + (i > 0 ? 8 : 0), cy + i, OPEN);
    }
  } else if (kind === 'redoubt') {
    // Cliffside fort: a walled approach with one mouth, and two bastions.
    carveRect(cx - 7, cy - 7, cx + 7, cy + 7);
    for (let x = cx - 6; x <= cx + 6; x++) {
      setCell(x, cy - 6, SOLID);
      if (x < cx - 1 || x > cx + 1) setCell(x, cy + 6, SOLID);
    }
    for (let y = cy - 6; y <= cy + 6; y++) { setCell(cx - 6, y, SOLID); setCell(cx + 6, y, SOLID); }
    for (let y = cy - 3; y <= cy + 3; y += 3) { setCell(cx - 3, y, SOLID); setCell(cx + 3, y, SOLID); }
  } else if (kind === 'shattergate') {
    // The breach itself: a colonnade on a square grid, four wide mouths.
    carveRect(cx - 8, cy - 8, cx + 8, cy + 8);
    for (let i = -6; i <= 6; i += 3) {
      for (const j of [-6, 6]) {
        if (Math.abs(i) <= 1) continue;                 // the mouths
        setCell(cx + i, cy + j, SOLID);
        setCell(cx + j, cy + i, SOLID);
      }
    }
  } else if (kind === 'thicket') {
    // A clearing choked with growth: cover everywhere, sightlines nowhere.
    carveRect(cx - 8, cy - 8, cx + 8, cy + 8);
    for (let gy = -6; gy <= 6; gy += 2) {
      for (let gx = -6; gx <= 6; gx += 2) {
        if (Math.abs(gx) < 3 && Math.abs(gy) < 3) continue;
        if (Math.random() < 0.42) setCell(cx + gx, cy + gy, SOLID);
      }
    }
  } else {
    // Ash shoals: open ground broken by long drifting bars.
    carveRect(cx - 9, cy - 8, cx + 9, cy + 8);
    for (let i = 0; i < 5; i++) {
      const y = cy - 6 + i * 3, len = 5 + ((Math.random() * 7) | 0);
      const x0 = cx - 7 + ((Math.random() * 6) | 0);
      for (let x = x0; x < x0 + len; x++) setCell(x, y, SOLID);
    }
  }
  carveRect(cx - 2, cy - 2, cx + 2, cy + 2);   // the gate always stands clear
}

// No passage may be one cell wide: the widest enemy is 46 units across and a
// cell is 40, so a single-cell throat is a wall the swarm would pile up behind.
// Widen toward whichever side already has more room, so corridors open out
// rather than punching through into unrelated pockets.
function openness(cx, cy) {
  let n = 0;
  for (let dy = -1; dy <= 1; dy++)
    for (let dx = -1; dx <= 1; dx++)
      if (cellAt(cx + dx, cy + dy) === OPEN) n++;
  return n;
}

function widenPassages() {
  const snap = new Uint8Array(grid);
  const solid = (cx, cy) => (cx < 0 || cy < 0 || cx >= GW || cy >= GH) ? 1 : snap[gi(cx, cy)];
  const toOpen = [];
  for (let y = 2; y < GH - 2; y++) {
    for (let x = 2; x < GW - 2; x++) {
      if (snap[gi(x, y)] !== OPEN) continue;
      if (solid(x - 1, y) && solid(x + 1, y)) {
        toOpen.push(openness(x - 1, y) >= openness(x + 1, y) ? gi(x - 1, y) : gi(x + 1, y));
      }
      if (solid(x, y - 1) && solid(x, y + 1)) {
        toOpen.push(openness(x, y - 1) >= openness(x, y + 1) ? gi(x, y - 1) : gi(x, y + 1));
      }
    }
  }
  for (let i = 0; i < toOpen.length; i++) grid[toOpen[i]] = OPEN;
}

// Greedy rectangle merge: far fewer, larger boxes for the collision system
// than one per cell, which keeps the AABB and spatial-hash work cheap.
function buildWallRects() {
  walls = [];
  const used = new Uint8Array(GW * GH);
  for (let y = 0; y < GH; y++) {
    for (let x = 0; x < GW; x++) {
      const k = gi(x, y);
      if (grid[k] !== SOLID || used[k]) continue;
      let w = 1;
      while (x + w < GW && grid[gi(x + w, y)] === SOLID && !used[gi(x + w, y)]) w++;
      let h = 1;
      grow: while (y + h < GH) {
        for (let i = 0; i < w; i++) {
          const kk = gi(x + i, y + h);
          if (grid[kk] !== SOLID || used[kk]) break grow;
        }
        h++;
      }
      for (let yy = 0; yy < h; yy++)
        for (let xx = 0; xx < w; xx++) used[gi(x + xx, y + yy)] = 1;
      walls.push({ x: x * CELL_W, y: y * CELL_W, w: w * CELL_W, h: h * CELL_W });
    }
  }

  rebuildWallGrid();
}

// The broad-phase index over the wall list. Split out because chasms are added
// after the rects are merged, and the index has to take them in too.
function rebuildWallGrid() {
  wallGrid = new SpatialHash(WALL_CELL);
  wallSeen = new Int32Array(walls.length);
  wallStamp = 0;
  for (let i = 0; i < walls.length; i++) {
    const w = walls[i];
    const x0 = Math.floor(w.x / WALL_CELL), x1 = Math.floor((w.x + w.w) / WALL_CELL);
    const y0 = Math.floor(w.y / WALL_CELL), y1 = Math.floor((w.y + w.h) / WALL_CELL);
    for (let cy = y0; cy <= y1; cy++)
      for (let cx = x0; cx <= x1; cx++) {
        const k = wallGrid.key(cx, cy);
        let b = wallGrid.buckets.get(k);
        if (!b) { b = []; wallGrid.buckets.set(k, b); }
        b.push(i);
      }
  }
}

// Every face where rock meets open floor. Drawn as one batched neon rim, which
// is what makes a grid of boxes read as a carved cave wall.
/* Holes in the floor. A chasm is impassable like a wall, so it rides in the
   same list and the same collision -- but it is a hole, not a mass, so it is
   flagged and drawn as a pit falling away to black instead of coursed stone.
   Cut after the wall rects so a chasm is always its own rect and never merged
   into a run of masonry. */
function cutChasms(sc, pc) {
  pitGrid = new Uint8Array(GW * GH);
  const want = 3 + ((Math.random() * 4) | 0);
  let cut = 0;
  for (let tries = 0; tries < 700 && cut < want; tries++) {
    const w = 2 + ((Math.random() * 3) | 0), h = 2 + ((Math.random() * 3) | 0);
    const cx = 3 + ((Math.random() * (GW - w - 6)) | 0);
    const cy = 3 + ((Math.random() * (GH - h - 6)) | 0);
    // open floor only, with a margin, and never near the spawn or the gate
    let ok = true;
    for (let y = cy - 1; y <= cy + h && ok; y++)
      for (let x = cx - 1; x <= cx + w && ok; x++)
        if (!inGrid(x, y) || cellAt(x, y) === SOLID) ok = false;
    if (!ok) continue;
    if (Math.abs(cx - sc.x) + Math.abs(cy - sc.y) < 9) continue;
    if (Math.abs(cx - pc.x) + Math.abs(cy - pc.y) < 9) continue;

    // A hole that severs the delve is a broken delve, so cut it, check every
    // open cell is still reachable from the spawn, and put it back if not.
    const undo = [];
    for (let y = cy; y < cy + h; y++)
      for (let x = cx; x < cx + w; x++) { undo.push(gi(x, y)); grid[gi(x, y)] = SOLID; }
    if (!allReachable(sc)) {
      for (const k of undo) grid[k] = OPEN;
      continue;
    }
    for (const k of undo) pitGrid[k] = 1;
    walls.push({ x: cx * CELL_W, y: cy * CELL_W,
                 w: w * CELL_W, h: h * CELL_W, pit: true });
    cut++;
  }
  if (cut) rebuildWallGrid();
}

// Is every open cell still walkable from the spawn? Used to refuse a chasm
// that would cut the delve in two.
function allReachable(sc) {
  const seen = new Uint8Array(GW * GH);
  const stack = [gi(sc.x, sc.y)];
  if (grid[stack[0]] === SOLID) return false;
  seen[stack[0]] = 1;
  let n = 1, total = 0;
  for (let i = 0; i < grid.length; i++) if (grid[i] === OPEN) total++;
  while (stack.length) {
    const k = stack.pop();
    const cx = k % GW, cy = (k / GW) | 0;
    for (let i = 0; i < 4; i++) {
      const nx = cx + (i === 0 ? 1 : i === 1 ? -1 : 0);
      const ny = cy + (i === 2 ? 1 : i === 3 ? -1 : 0);
      if (!inGrid(nx, ny)) continue;
      const nk = gi(nx, ny);
      if (seen[nk] || grid[nk] === SOLID) continue;
      seen[nk] = 1; n++; stack.push(nk);
    }
  }
  return n === total;
}

function buildEdges() {
  const C = CELL_W;
  // Collect faces per line, then merge collinear neighbours into single long
  // segments. A straight run of wall emitted one 40-unit stub per cell; the
  // rim is stroked three times a frame with round caps, so segment count is
  // the cost. Merging cuts it by roughly two thirds for an identical picture.
  const lines = new Map();
  const add = (key, a, b) => {
    let arr = lines.get(key);
    if (!arr) { arr = []; lines.set(key, arr); }
    arr.push([a, b]);
  };
  for (let y = 1; y < GH - 1; y++) {
    for (let x = 1; x < GW - 1; x++) {
      if (grid[gi(x, y)] !== SOLID) continue;
      if (cellAt(x, y - 1) === OPEN) add('h|' + y + '|-1', x, x + 1);
      if (cellAt(x, y + 1) === OPEN) add('h|' + (y + 1) + '|1', x, x + 1);
      if (cellAt(x - 1, y) === OPEN) add('v|' + x + '|-1', y, y + 1);
      if (cellAt(x + 1, y) === OPEN) add('v|' + (x + 1) + '|1', y, y + 1);
    }
  }

  edges = [];
  for (const [key, arr] of lines) {
    const parts = key.split('|');
    const horiz = parts[0] === 'h';
    const at = +parts[1] * C;
    const sign = +parts[2];
    arr.sort((a, b) => a[0] - b[0]);
    let s0 = arr[0][0], s1 = arr[0][1];
    for (let i = 1; i <= arr.length; i++) {
      if (i < arr.length && arr[i][0] === s1) { s1 = arr[i][1]; continue; }
      const a = s0 * C, b = s1 * C;
      // Does this run end at a corner, or does the wall simply stop? Courses
      // are laid past a corner so the square between two perpendicular faces
      // is covered -- but doing that at a free end hangs masonry out over open
      // floor. The rock one cell beyond the run tells them apart.
      const solid = horiz
        ? (sign === -1 ? +parts[1] : +parts[1] - 1)     // solid row
        : (sign === -1 ? +parts[1] : +parts[1] - 1);    // solid column
      const capA = horiz ? cellAt(s0 - 1, solid) === SOLID
                         : cellAt(solid, s0 - 1) === SOLID;
      const capB = horiz ? cellAt(s1, solid) === SOLID
                         : cellAt(solid, s1) === SOLID;
      edges.push(horiz
        ? { x1: a, y1: at, x2: b, y2: at, nx: 0, ny: sign, capA, capB }
        : { x1: at, y1: a, x2: at, y2: b, nx: sign, ny: 0, capA, capB });
      if (i < arr.length) { s0 = arr[i][0]; s1 = arr[i][1]; }
    }
  }
}

function buildScenery(spawn, portal) {
  props = [];
  lamps = [];
  const C = CELL_W;

  // Wall-mounted fittings, oriented to face the open side. Edges are merged
  // into long runs, so step along each one rather than placing a single
  // fitting at its midpoint -- otherwise a 20-metre wall gets one vent.
  const STRIDE = 58;
  for (let i = 0; i < edges.length; i++) {
    const e = edges[i];
    const len = Math.hypot(e.x2 - e.x1, e.y2 - e.y1);
    const ux = (e.x2 - e.x1) / (len || 1), uy = (e.y2 - e.y1) / (len || 1);
    const rot = Math.atan2(e.ny, e.nx);
    for (let d = STRIDE * 0.5; d < len; d += STRIDE) {
    if (Math.random() > 0.34) continue;
    const jitter = rand(-9, 9);
    const mx = e.x1 + ux * clamp(d + jitter, 6, len - 6) + e.nx * 7;
    const my = e.y1 + uy * clamp(d + jitter, 6, len - 6) + e.ny * 7;
    const roll = Math.random();
    const kind = roll < 0.24 ? 'torch' : roll < 0.52 ? 'chain' :
                 roll < 0.80 ? 'banner' : 'sconce';
    const q = ((Math.round(rot / (Math.PI / 2)) % 4) + 4) % 4;
    props.push({ x: mx, y: my, q, kind });
    // Torches are the light. Everything else is just furniture.
    if (kind === 'torch') {
      lamps.push({ x: mx + e.nx * 12, y: my + e.ny * 12, color: PAL.ember });
    } else if (kind === 'sconce' && Math.random() < 0.34) {
      lamps.push({ x: mx + e.nx * 12, y: my + e.ny * 12, color: PAL.teal });
    }
    }
  }

  // Torch count follows the edge count, so a fretted map can light itself into
  // a performance problem. Thin evenly rather than clipping a region dark.
  const LAMP_CAP = 46;
  if (lamps.length > LAMP_CAP) {
    const keep = [];
    const step = lamps.length / LAMP_CAP;
    for (let i = 0; i < LAMP_CAP; i++) keep.push(lamps[Math.floor(i * step)]);
    lamps = keep;
  }

  // Floor scenery. Two rules keep it from reading as floating debris:
  // man-made decals snap to right angles (only rubble and stains rotate
  // freely), and the loud ones cluster against the rock, where equipment and
  // spillage would actually accumulate. Open floor gets only quiet marks, so
  // the middle of a chamber stays readable during a fight.

  for (let i = 0; i < openCells.length; i++) {
    const c = openCells[i];
    if (dist2(c.x, c.y, spawn.x, spawn.y) < 110 * 110) continue;
    if (dist2(c.x, c.y, portal.x, portal.y) < 110 * 110) continue;

    const cx = Math.floor(c.x / C), cy = Math.floor(c.y / C);
    const byRock = cellAt(cx - 1, cy) === SOLID || cellAt(cx + 1, cy) === SOLID ||
                   cellAt(cx, cy - 1) === SOLID || cellAt(cx, cy + 1) === SOLID;
    const roll = Math.random();
    let kind = null;
    // The place should look looted and lived-in. Heavier against the rock
    // where things pile up, lighter in the open so a fight stays readable.
    // Thin background texture only. The loud objects arrive in knots below --
    // an independent roll per cell, however weighted, produces exactly the
    // even sprinkle it looks like, because that is what it is.
    if (byRock) {
      if (roll > 0.20) continue;
      kind = roll < 0.05 ? 'rubble' : roll < 0.10 ? 'moss' :
             roll < 0.15 ? 'crack'  : 'bones';
    } else {
      if (roll > 0.085) continue;
      kind = roll < 0.035 ? 'crack' : roll < 0.06 ? 'moss' : 'rubble';
    }
    props.push({ x: c.x + rand(-C * 0.22, C * 0.22),
                 y: c.y + rand(-C * 0.22, C * 0.22),
                 q: (Math.random() * 4) | 0, kind });
  }

  scatterKnots(spawn, portal);
  standPillars(spawn, portal);
  indexBreakables();
}

// Columns, set where a hall would have been built with them: down the middle
// of the wider open ground, and in pairs flanking a long run of wall.
function standPillars(spawn, portal) {
  let placed = 0;
  for (let tries = 0; tries < 900 && placed < 26; tries++) {
    const c = openCells[(Math.random() * openCells.length) | 0];
    if (dist2(c.x, c.y, spawn.x, spawn.y) < 170 * 170) continue;
    if (dist2(c.x, c.y, portal.x, portal.y) < 170 * 170) continue;
    // needs room around it, or it blocks a corridor it has no business in
    let clear = true;
    for (let a = 0; a < 8 && clear; a++) {
      const t = a / 8 * TAU;
      if (pointInWalls(c.x + Math.cos(t) * 46, c.y + Math.sin(t) * 46, 6)) clear = false;
    }
    if (!clear) continue;
    let near = false;
    for (let i = 0; i < props.length && !near; i++) {
      if (props[i].kind !== 'pillar') continue;
      if (dist2(props[i].x, props[i].y, c.x, c.y) < 120 * 120) near = true;
    }
    if (near) continue;
    props.push({ x: c.x + rand(-6, 6), y: c.y + rand(-6, 6), q: 0, kind: 'pillar' });
    placed++;
  }
}

/* Debris arrives in knots, where it would actually collect: jammed into
   dead ends, banked into corners, and dressed through the rooms to match what
   each one was. Everything else stays background texture, so a knot reads as
   somebody having been here rather than as more of the same scatter. */
const KNOT_SETS = {
  store:   ['crate', 'barrel', 'urn', 'crate', 'coins'],
  killed:  ['bones', 'sword', 'shield', 'hornskull', 'bones', 'tomb'],
  spoil:   ['coins', 'scroll', 'urn', 'coins', 'bones'],
  fallen:  ['rubble', 'rubble', 'crack', 'bones', 'rubble', 'tomb'],
  damp:    ['moss', 'moss', 'rubble', 'grate', 'moss']
};

function knot(x, y, set, n, spread) {
  const pool = KNOT_SETS[set];
  for (let i = 0; i < n; i++) {
    const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * spread;
    const px = x + Math.cos(a) * d, py = y + Math.sin(a) * d;
    if (pointInWalls(px, py, 7)) continue;
    props.push({ x: px, y: py, q: (Math.random() * 4) | 0,
                 kind: pool[(Math.random() * pool.length) | 0] });
  }
}

function scatterKnots(spawn, portal) {
  const C = CELL_W;
  // Dead ends and corners first -- the places a corridor stops being a route.
  const ends = [], corners = [];
  for (let cy = 1; cy < GH - 1; cy++) {
    for (let cx = 1; cx < GW - 1; cx++) {
      if (cellAt(cx, cy) === SOLID) continue;
      let w = 0;
      const L = cellAt(cx - 1, cy) === SOLID, R = cellAt(cx + 1, cy) === SOLID;
      const U = cellAt(cx, cy - 1) === SOLID, D = cellAt(cx, cy + 1) === SOLID;
      w = L + R + U + D;
      const p = { x: cx * C + C / 2, y: cy * C + C / 2 };
      if (dist2(p.x, p.y, spawn.x, spawn.y) < 150 * 150) continue;
      if (dist2(p.x, p.y, portal.x, portal.y) < 150 * 150) continue;
      if (w >= 3) ends.push(p);
      else if (w === 2 && ((L || R) && (U || D))) corners.push(p);
    }
  }
  const pick = (arr, n) => {
    const out = [];
    for (let i = 0; i < n && arr.length; i++) {
      out.push(arr.splice((Math.random() * arr.length) | 0, 1)[0]);
    }
    return out;
  };
  // A dead end is where something was dumped, dragged, or died.
  for (const p of pick(ends, Math.min(22, ends.length))) {
    const r = Math.random();
    knot(p.x, p.y, r < 0.34 ? 'store' : r < 0.68 ? 'killed' : 'spoil',
         3 + ((Math.random() * 4) | 0), 26);
  }
  // Corners bank debris the way a current does.
  for (const p of pick(corners, Math.min(26, corners.length))) {
    knot(p.x, p.y, Math.random() < 0.5 ? 'fallen' : 'killed',
         2 + ((Math.random() * 3) | 0), 22);
  }
  // Rooms get dressed as what they were.
  for (let i = 0; i < rooms.length; i++) {
    const rm = rooms[i];
    const set = rm.kind === 'barracks' ? 'store' :
                rm.kind === 'cistern'  ? 'damp'  :
                rm.kind === 'collapse' ? 'fallen' : 'spoil';
    const knots = 4 + ((Math.random() * 4) | 0);
    for (let k = 0; k < knots; k++) {
      const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * rm.r * 0.85;
      knot(rm.x + Math.cos(a) * d, rm.y + Math.sin(a) * d, set,
           3 + ((Math.random() * 4) | 0), 30);
    }
  }
}

const _wallOut = [], _wallHits = [];
// Wall indices whose cells overlap the circle, deduped.
function wallsNear(x, y, r) {
  wallGrid.query(x, y, r, _wallOut);
  _wallHits.length = 0;
  wallStamp++;
  for (let i = 0; i < _wallOut.length; i++) {
    const idx = _wallOut[i];
    if (wallSeen[idx] === wallStamp) continue;
    wallSeen[idx] = wallStamp;
    _wallHits.push(idx);
  }
  return _wallHits;
}

/* ---------------------------------------------------------------------------
   5. COLLISION
   Circle-vs-AABB, resolved one axis at a time. Doing X and Y as separate
   passes is what produces clean sliding: a body pressed into a corner still
   keeps whichever component of its motion is unobstructed, instead of
   snagging the way a single-vector push-out does.
   ------------------------------------------------------------------------ */

function circleHitsRect(x, y, r, w) {
  const nx = clamp(x, w.x, w.x + w.w);
  const ny = clamp(y, w.y, w.y + w.h);
  const dx = x - nx, dy = y - ny;
  return dx * dx + dy * dy < r * r;
}

function moveEntity(e, dx, dy) {
  // Resolution puts the body against the nearer face of the block, not the
  // face its travel came from. For a normal step those are the same face --
  // a frame moves a body a few units, so the side it entered is the side it
  // is nearest. They differ only for a body that is already inside the rock,
  // and there the travel-side rule threw it clean through: rooms are cut out
  // of continuous masses now, so one block can be six hundred units across
  // and "push it out the way it was going" teleports it to the far side of
  // the map. Nearest-face is the same answer for real motion and a sane one
  // for a body that should not have been in there to begin with.
  if (dx !== 0) {
    e.x += dx;
    const hits = wallsNear(e.x, e.y, e.r);
    for (let i = 0; i < hits.length; i++) {
      const w = walls[hits[i]];
      if (circleHitsRect(e.x, e.y, e.r, w)) {
        const left = w.x - e.r, right = w.x + w.w + e.r;
        e.x = (e.x - left) < (right - e.x) ? left : right;
      }
    }
  }
  if (dy !== 0) {
    e.y += dy;
    const hits = wallsNear(e.x, e.y, e.r);
    for (let i = 0; i < hits.length; i++) {
      const w = walls[hits[i]];
      if (circleHitsRect(e.x, e.y, e.r, w)) {
        const up = w.y - e.r, down = w.y + w.h + e.r;
        e.y = (e.y - up) < (down - e.y) ? up : down;
      }
    }
  }
  e.x = clamp(e.x, e.r, WORLD.w - e.r);
  e.y = clamp(e.y, e.r, WORLD.h - e.r);
}

/* ---------------------------------------------------------------------------
   6. ENTITIES & SPAWNING
   ------------------------------------------------------------------------ */

let player, enemies, arcs, loot, drops, particles, rings, portal;
let floaters = [];
let enemyGrid = new SpatialHash(ENEMY_CELL);
const _near = [];
// wakeEnemy runs from inside damageEnemy, which is itself called while
// updateArcs iterates _near -- so the alarm query needs its own scratch or it
// clobbers the array being walked.
const _alert = [];

let run;  // per-run state: timers, counters, difficulty

function makePlayer(x, y, heroId) {
  const H = HEROES[heroId] || HEROES.isaac;
  const p = Object.assign({}, BASE_PLAYER);
  p.hero = H.id;
  p.maxHp = H.maxHp; p.speed = H.speed; p.damage = H.damage;
  p.fireDelay = H.fireDelay; p.range = H.range;
  p.sweep = H.sweep; p.arcSpeed = H.arcSpeed;
  p.x = x; p.y = y; p.angle = -Math.PI / 2;
  p.hp = p.maxHp;
  p.face = 1;
  p.fireTimer = 0; p.invuln = 0; p.hitFlash = 0;
  p.swing = 0; p.swingA = 0;
  p.gait = 0; p.pace = 0;
  p.strike = 0; p.recov = 0;
  p.bleed = 0; p.bleedDps = 0; p.bleedTick = 0;
  p.upg = {};
  p.level = stash.level || 1;
  p.gear = {};
  // Wear what came home from the last delve.
  for (const sl of SLOTS) p.gear[sl.id] = (stash.gear && stash.gear[sl.id]) || null;
  p.bag = [];
  p.ward = 0;
  p.gcd = 0; p.gcdMax = GCD_TIME;   // the beat, and what it was set from
  p.charges = 0; p.chargePop = 0;   // Isaac's Sun-Gold
  p.tension = 0;                    // Zayd's Ley-Tension
  p.jars = JAR_USES;
  p.cds = {}; p.channel = null;
  p.mitigate = 0; p.rooted = 0; p.swapCd = 0;
  return p;
}

function typeWeights(t) {
  let total = 0;
  const out = [];
  for (const k of LEVEL.horde) {
    const d = ENEMY_TYPES[k];
    if (t < d.from) continue;
    // Ramp in over 20s so a new archetype trickles in rather than flooding.
    const w = d.weight * clamp((t - d.from) / 20 + 0.25, 0.25, 1);
    total += w;
    out.push({ k, w });
  }
  return { out, total };
}

// Put one body on the map, dormant, at a given spot. Depth (0 at the spawn
// pocket, 1 at the far edge of the delve) stands in for the old run-time
// health ramp: waves used to get tougher as the clock ran, and a placed
// dungeon gets tougher the further in you go instead.
function placeEnemy(kind, x, y, depth) {
  if (enemies.length >= MAX_ENEMIES) return null;
  const d = ENEMY_TYPES[kind];
  const scale = (1 + depth * PACK_DEPTH_HP) * DIFF.threat * (1 + (LEVEL.depth || 0) * 1.6);
  // Same body newBody makes, then the things that only a placed one has: it is
  // asleep where the generator put it, it remembers that spot, and a heavy one
  // notices further off.
  const e = newBody(kind, x, y, 0);
  e.hp = e.maxHp = d.hp * scale;
  e.dmg = d.dmg * DIFF.threat;
  e.awake = false;
  e.home = { x, y };
  e.aggro = d.r >= 20 ? AGGRO_FAR : AGGRO_NEAR;
  e.elite = false;
  enemies.push(e);
  return e;
}

// Promote a body to the champion of its pack: harder, worth more, and the only
// thing besides the avatar that carries a piece of the Regalia.
function makeElite(e) {
  if (!e || e.kind === 'mirage' || e.kind === 'deceiver') return e;
  e.elite = true;
  e.hp = e.maxHp = e.maxHp * ELITE_HP;
  e.dmg *= 1.35;
  e.speed *= 0.92;
  e.mass *= 1.6;
  // A champion is bodily bigger, but the spot was chosen for the body it was
  // before -- growing the radius blind can wedge it in rock it used to fit
  // through. Take the size only if the ground still takes it.
  const bigger = Math.round(e.r * 1.22);
  if (!pointInWalls(e.x, e.y, bigger)) e.r = bigger;
  e.tech = Math.max(3, Math.round(e.tech * 4));
  e.aggro = AGGRO_FAR;
  return e;
}

// How far away the player is *by ground a body could walk*, so a pack does not
// rouse through a wall. The flow field is a BFS from the player rebuilt only
// when they cross a cell, so this is one array read; straight-line distance
// stands in only before the first field exists.
function noticeDist(e, straight) {
  if (!flowDist) return straight;
  const cx = clamp(Math.floor(e.x / CELL_W), 0, GW - 1);
  const cy = clamp(Math.floor(e.y / CELL_W), 0, GH - 1);
  const steps = flowDist[gi(cx, cy)];
  if (steps < 0) return Infinity;               // no path: it never hears you
  return steps * CELL_W;
}

// Wake a body, and pass the alarm to its neighbours a beat later so a pack
// rouses in sequence rather than all at once.
function wakeEnemy(e, chain) {
  if (e.awake || e.hp <= 0) return;
  e.awake = true;
  e.alert = 0;
  if (chain === false) return;
  // The body you walked into always wakes. What the cap stops is the alert
  // running on past it, so the fight in front of you stays a fight rather
  // than becoming the whole delve at once.
  if ((run.awake || 0) >= HORDE_LIVE) return;
  enemyGrid.query(e.x, e.y, ALERT_R, _alert);
  for (let i = 0; i < _alert.length; i++) {
    const o = _alert[i];
    if (o === e || o.awake || o.hp <= 0) continue;
    if (o.alert > 0) continue;
    if (dist2(e.x, e.y, o.x, o.y) > ALERT_R * ALERT_R) continue;
    o.alert = ALERT_DELAY;
  }
}

// Populate the delve: packs spread across the reachable floor, none of them
// near the spawn pocket, biggest and meanest deepest in, plus a guard on the
// ley-gate itself. Placement stops once enough slag is on the map to make the
// quota with room to spare -- the level has to be completable by clearing it.
// What a pack member is, by how deep in the delve its site sits. Deeper packs
// lean on the heavier archetypes and the near ones are thralls. Written out
// twice once -- in the main placement and in the top-up pass -- which meant
// two copies of the same table to keep in step by hand.
// What a pack is made of, as a weight per kind and the depth it starts
// appearing at. This was cumulative bands on a single roll, which is a trap:
// widening one band silently narrowed every kind after it, and the breaker's
// share was cut from 0.28 to 0.22 that way without anyone noticing until a
// delve got shorter. A weight is only ever relative to the kinds actually in
// the roster, so adding one here cannot quietly rewrite another.
// A weight here is NOT the share that ends up on the map. `from` gates a kind
// to pack sites at least that far out from the spawn, and the far band holds a
// minority of sites, so a late kind has to carry a much larger weight to land
// the same number of bodies -- that is why the breaker's 44 sits beside the
// thrall's 12 and both come out near an eighth of the delve. The shares these
// produce were measured on the map, not reasoned about; kindcensus.js prints
// them, and changing a number here without re-running it is guessing.
const PACK_MIX = [
  { kind: 'breaker', from: 0.62, w: 44 },
  { kind: 'gorger',  from: 0.52, w: 11 },   // rare: three of them is a wall
  { kind: 'cantor',  from: 0.45, w: 12 },
  { kind: 'shaman',  from: 0.56, w: 10 },   // rarest: two chanters stack fire
  { kind: 'husk',    from: 0.28, w: 13 },
  { kind: 'flayer',  from: 0.22, w: 11 },
  { kind: 'eclipse', from: 0.30, w: 11 },
  { kind: 'thrall',  from: 0,    w: 12 }
];

function packKind(roster, depth) {
  let total = 0;
  for (const e of PACK_MIX) {
    if (depth >= e.from && roster.indexOf(e.kind) >= 0) total += e.w;
  }
  if (total <= 0) return roster[0];
  let r = Math.random() * total;
  for (const e of PACK_MIX) {
    if (depth < e.from || roster.indexOf(e.kind) < 0) continue;
    r -= e.w;
    if (r < 0) return e.kind;
  }
  return roster[0];
}

function placePacks(spawn) {
  if (!openCells.length) return;
  const far = Math.hypot(WORLD.w, WORLD.h) * 0.5;
  const sites = [];
  const roster = LEVEL.horde;

  const budget = Math.round((LEVEL.quota || 125) * SLAG_HEAD);
  // Reservoir of candidate sites, kept apart so packs read as separate groups.
  // A deep delve needs more of them to carry its larger budget, but they still
  // have to fit: the cap is a ceiling, and the loop stops early if the floor
  // cannot hold that many at PACK_APART.
  const wantSites = clamp(Math.round(14 + budget / 11), 20, 44);
  for (let tries = 0; tries < 7000 && sites.length < wantSites; tries++) {
    const c = openCells[(Math.random() * openCells.length) | 0];
    const ds = Math.hypot(c.x - spawn.x, c.y - spawn.y);
    if (ds < PACK_SAFE) continue;
    let ok = true;
    for (let i = 0; i < sites.length && ok; i++) {
      if (dist2(c.x, c.y, sites[i].x, sites[i].y) < PACK_APART * PACK_APART) ok = false;
    }
    if (!ok) continue;
    sites.push({ x: c.x, y: c.y, depth: clamp(ds / far, 0, 1) });
  }
  // Nearest first, so the slag budget is spent from the spawn outwards and a
  // short delve is not left with every pack in one far corner.
  sites.sort((a, b) => a.depth - b.depth);

  let slag = 0;
  for (let i = 0; i < sites.length && slag < budget; i++) {
    const st = sites[i];
    const n = 3 + ((Math.random() * 3) | 0) + (st.depth > 0.55 ? 1 : 0) +
              Math.round((LEVEL.depth || 0) * 2);
    for (let k = 0; k < n; k++) {
      const kind = packKind(roster, st.depth);
      // The site is kept clear of the spawn pocket, but members scatter off
      // the site -- so the clearance has to be enforced on the body, not the
      // site, or one can drift back inside its own aggro radius of the player.
      const pos = scatterNear(st.x, st.y, 86, ENEMY_TYPES[kind].r + 4, spawn);
      if (!pos) continue;
      const e = placeEnemy(kind, pos.x, pos.y, st.depth);
      if (e) {
        // One champion at most, and only in some packs -- an elite in every
        // group is just a tougher baseline rather than a thing you notice.
        if (k === 0 && Math.random() <
            ((LEVEL.elites === undefined ? ELITE_CHANCE : LEVEL.elites) +
             st.depth * 0.14 * (LEVEL.elites === 0 ? 0 : 1)) *
            DIFF.setRate) makeElite(e);
        slag += e.tech;
      }
    }
  }

  // If the ground would not hold enough separate sites for the budget, the
  // shortfall goes back into the sites that did fit rather than leaving the
  // delve short of its own quota. Packs get denser at depth; they never get
  // fewer than the quota needs.
  for (let pass = 0; pass < 4 && slag < budget; pass++) {
    for (let i = 0; i < sites.length && slag < budget; i++) {
      const st = sites[i];
      const kind = packKind(roster, st.depth);
      const pos = scatterNear(st.x, st.y, 110, ENEMY_TYPES[kind].r + 4, spawn);
      if (!pos) continue;
      const e = placeEnemy(kind, pos.x, pos.y, st.depth);
      if (e) slag += e.tech;
    }
  }

  // Pitch where the fighting will be. Scattered by the scenery pass a delve
  // averaged five barrels across four million square units -- you would go
  // whole runs without ever standing near one, and a tactic you cannot reach
  // is not a tactic. They go beside the packs instead, which is the only place
  // a barrel is interesting: something has to be standing next to it.
  for (let i = 0; i < sites.length; i++) {
    if (Math.random() > (LEVEL.pitch === undefined ? PITCH_RATE : LEVEL.pitch)) continue;
    const st = sites[i];
    const n = 1 + ((Math.random() * 2) | 0);
    for (let k = 0; k < n; k++) {
      const pos = scatterNear(st.x, st.y, 74, 16, spawn);
      if (!pos) continue;
      props.push({ x: pos.x, y: pos.y, q: (Math.random() * 4) | 0, kind: 'barrel' });
    }
  }

  // The gate is the objective, so it is guarded -- and that guard is awake to
  // nobody until you come for it.
  for (let k = 0; k < 6; k++) {
    const kind = k < 2 && roster.indexOf('breaker') >= 0 ? 'breaker' : roster[0];
    const pos = scatterNear(portal.x, portal.y, 150, ENEMY_TYPES[kind].r + 4, spawn);
    const g = pos && placeEnemy(kind, pos.x, pos.y, 0.85);
    // The gate is held by champions -- except on a rung that has not shown the
    // player one yet, where the two standing guards were the only champions in
    // the delve and walked straight through the ramp's whole point.
    if (g && k < 2 && LEVEL.elites !== 0) makeElite(g);
  }

  // The barrels above were added after the scenery pass indexed itself.
  indexBreakables();
}

// A free spot within `spread` of a point, clear of rock. Returns null rather
// than a wedged position if the ground there will not take a body.
function scatterNear(x, y, spread, pad, keepFrom) {
  for (let i = 0; i < 26; i++) {
    const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * spread;
    const nx = clamp(x + Math.cos(a) * d, pad + 4, WORLD.w - pad - 4);
    const ny = clamp(y + Math.sin(a) * d, pad + 4, WORLD.h - pad - 4);
    if (pointInWalls(nx, ny, pad)) continue;
    if (keepFrom && dist2(nx, ny, keepFrom.x, keepFrom.y) < PACK_SAFE * PACK_SAFE) continue;
    return { x: nx, y: ny };
  }
  return null;
}

// lo/hi scale the band the body arrives in, as multiples of the default ring.
// The hold passes a tight band so its surges land just off screen instead of
// two screens out, where they dissolve on the walk in.
function spawnEnemy(t, lo, hi) {
  if (enemies.length >= MAX_ENEMIES) return;

  const { out, total } = typeWeights(t);
  let roll = Math.random() * total, kind = out[0].k;
  for (const o of out) { roll -= o.w; if (roll <= 0) { kind = o.k; break; } }
  const d = ENEMY_TYPES[kind];

  // In a cave most of the map is rock, so sampling a ring blind mostly lands
  // in stone. Draw from the reachable floor instead and accept the first cell
  // in the band just past the viewport -- guaranteeing the spawn can actually
  // walk to the player, since every open cell is connected to every other.
  if (!openCells.length) return;
  const ring = Math.max(view.w, view.h) * 0.55 + 60;
  const r0 = ring * (lo || 1), r1 = ring * (hi || 2.1);
  const near = r0 * r0, far = r1 * r1;
  let x = 0, y = 0, ok = false;
  for (let tries = 0; tries < 34 && !ok; tries++) {
    const c = openCells[(Math.random() * openCells.length) | 0];
    const dd = dist2(c.x, c.y, player.x, player.y);
    if (dd < near || dd > far) continue;
    if (pointInWalls(c.x, c.y, d.r + 3)) continue;
    x = c.x; y = c.y; ok = true;
  }
  if (!ok) return;

  enemies.push(newBody(kind, x, y, t));
  return enemies[enemies.length - 1];
}

// One body of the given kind, standing where it was put and already awake --
// anything raised through here was called to the player rather than stumbled
// on, so it never needs rousing. Health creeps up with run time so late
// arrivals stay meaningful.
function newBody(kind, x, y, t) {
  const d = ENEMY_TYPES[kind];
  const scale = (1 + (t || 0) / 200) * DIFF.threat;
  return {
    kind, x, y, r: d.r, speed: d.speed * rand(0.92, 1.08),
    hp: d.hp * scale, maxHp: d.hp * scale, dmg: d.dmg * DIFF.threat, tech: d.tech,
    cd: d.cd, mass: d.mass, color: d.color, halo: d.halo,
    atk: rand(0, d.cd), hitFlash: 0, wob: Math.random() * TAU, angle: 0, face: 1,
    awake: true, alert: 0, drowse: Math.random() * TAU, aggro: AGGRO_NEAR,
    role: d.role || 'press', spin: Math.random() < 0.5 ? -1 : 1,
    markX: 0, markY: 0, markT: 0, markCd: 0,
    slam: !!d.slam, slamCd: rand(1.2, SLAM_CD), slamR: d.slamR || 1,
    fracture: !!d.fracture,
    postX: 0, postY: 0, posted: false, guard: rand(0, BRACE_UP), braced: false,
    // Started somewhere random in the cycle, or a pack arrives in lockstep.
    gait: Math.random() * GAIT_STEP * GAIT_N, pace: 0,
    fuse: 0,                                   // husk: counting down to the burst
    cast: rand(0, 1.2), casting: 0,            // cantor: between throws, and mid-throw
    lurk: rand(0, STALK_BACK), run: 0, struck: false,  // flayer: waiting, running, spent
    chant: rand(0, 2), chanting: 0, spell: 0,  // shaman: between, mid-cast, and which
    calcify: 0, calcified: false,             // the retreat, and whether it has used it
    consume: 0, fed: false,                   // and whether it has eaten
  };
}

// The ground an anchor decides to hold.
//
// Not a corridor: a heavy body is forty-six units across and a corridor cell
// is forty, so it cannot stand in one -- measured, a breaker fits half the
// open cells in a delve and a thrall fits ninety-eight per cent of them. That
// split is worth keeping (it is why the Deceiver blinks instead of walking),
// so the anchor holds the *mouth* instead: ground it fits on whose neighbours
// are pinched. That is the cell you have to come through anyway.
//
// Score is its own walls plus the tightest of its neighbours', tie broken by
// distance. On genuinely open floor with no mouth in reach it holds where it
// woke, which is the right answer for a body with nothing to guard.
function takePost(e) {
  e.postX = e.x; e.postY = e.y;
  e.posted = true;
  const cx = clamp(Math.floor(e.x / CELL_W), 0, GW - 1);
  const cy = clamp(Math.floor(e.y / CELL_W), 0, GH - 1);
  const span = Math.ceil(ANCHOR_POST / CELL_W);
  const mouth = (x, y) => {
    let best = 0;
    if (cellAt(x + 1, y) !== SOLID) best = Math.max(best, narrowGrid[gi(x + 1, y)]);
    if (cellAt(x - 1, y) !== SOLID) best = Math.max(best, narrowGrid[gi(x - 1, y)]);
    if (cellAt(x, y + 1) !== SOLID) best = Math.max(best, narrowGrid[gi(x, y + 1)]);
    if (cellAt(x, y - 1) !== SOLID) best = Math.max(best, narrowGrid[gi(x, y - 1)]);
    return narrowGrid[gi(x, y)] + best;
  };
  let bestS = -1, bestD = 0;
  for (let y = cy - span; y <= cy + span; y++) {
    for (let x = cx - span; x <= cx + span; x++) {
      if (x < 0 || y < 0 || x >= GW || y >= GH) continue;
      if (cellAt(x, y) === SOLID) continue;
      const wx = x * CELL_W + CELL_W / 2, wy = y * CELL_W + CELL_W / 2;
      const dd = dist2(wx, wy, e.x, e.y);
      if (dd > ANCHOR_POST * ANCHOR_POST) continue;
      const sc = mouth(x, y);
      if (sc < bestS) continue;
      if (sc === bestS && dd >= bestD) continue;
      if (pointInWalls(wx, wy, e.r + 2)) continue;
      bestS = sc; bestD = dd; e.postX = wx; e.postY = wy;
    }
  }
}

// A ring of champions closing on a point. Used by the corpse ambush: the
// bodies form up *around* you at a distance you can still see across, so the
// beat reads as being surrounded rather than as a swarm materialising on top
// of you. Spots are taken from open ground the flow field says is actually
// walkable, so nothing spawns sealed behind rock.
function spawnAmbush(cx, cy, n) {
  const kinds = ['breaker', 'thrall', 'thrall', 'eclipse'];
  let born = 0;
  for (let i = 0; i < n; i++) {
    if (enemies.length >= MAX_ENEMIES) break;
    const kind = kinds[(Math.random() * kinds.length) | 0];
    const rr0 = ENEMY_TYPES[kind].r + 6;
    const base = (i / n) * TAU;
    let x = 0, y = 0, ok = false;
    for (let tries = 0; tries < 26 && !ok; tries++) {
      const a = base + rand(-0.36, 0.36);
      const rad = AMBUSH_R * rand(0.72, 1.3);
      x = clamp(cx + Math.cos(a) * rad, 60, WORLD.w - 60);
      y = clamp(cy + Math.sin(a) * rad, 60, WORLD.h - 60);
      if (pointInWalls(x, y, rr0)) continue;
      if (flowDist) {
        const gx = clamp(Math.floor(x / CELL_W), 0, GW - 1);
        const gy = clamp(Math.floor(y / CELL_W), 0, GH - 1);
        if (flowDist[gi(gx, gy)] < 0) continue;   // no path: it would just stand there
      }
      ok = true;
    }
    // The ring is where it wants them, not where it will settle for them.
    // Sampling one arc of the circle and giving up put three or four of the
    // five asked for on the map -- measured, it came up short in twenty-three
    // of thirty cuts and once put down only two. A partial ring is not the
    // beat this is for, so a spot that will not take a body falls back to any
    // reachable floor in the band around the corpse.
    if (!ok) {
      const lo = AMBUSH_R * 0.6, hi = AMBUSH_R * 1.9;
      for (let tries = 0; tries < 90 && !ok; tries++) {
        const c = openCells[(Math.random() * openCells.length) | 0];
        const d = Math.hypot(c.x - cx, c.y - cy);
        if (d < lo || d > hi) continue;
        if (pointInWalls(c.x, c.y, rr0)) continue;
        if (flowDist) {
          const gx = clamp(Math.floor(c.x / CELL_W), 0, GW - 1);
          const gy = clamp(Math.floor(c.y / CELL_W), 0, GH - 1);
          if (flowDist[gi(gx, gy)] < 0) continue;
        }
        x = c.x; y = c.y; ok = true;
      }
    }
    if (!ok) continue;
    const e = newBody(kind, x, y, run.time);
    enemies.push(e);
    makeElite(e);
    ring(e.x, e.y, CORPSE_HUE, 6, 46, 0.5);
    born++;
  }
  return born;
}

function fire() {
  // Auto-target: nearest enemy inside weapon range. The spatial hash means
  // this is a handful of cells, not a full pass over the swarm.
  const R = player.range;
  enemyGrid.query(player.x, player.y, R, _near);
  // Nearest-target alone cannot fight a boss: while he is escorted, every
  // crescent lands in the escort and he never takes a scratch. The Vanguard put
  // the avatar first. Mirages stay targetable -- being decoys is their whole
  // purpose -- except for Isaac, who is immune to the illusion and ignores
  // them outright.
  // Rock stops a crescent, so a target must be reachable as well as near, and
  // a body with a wall in the way is not a target at all -- the blade holds
  // rather than swinging at stone. An earlier version kept blocked bodies as a
  // fallback "once nothing clear is left", which is exactly the case where the
  // player is behind cover and every swing goes into rock for nothing.
  const blind = player.hero === 'isaac';
  let best = null, bestD = R * R, avatar = null, avatarD = R * R;
  for (let i = 0; i < _near.length; i++) {
    const e = _near[i];
    if (blind && e.kind === 'mirage') continue;
    if (!clearShot(player.x, player.y, e.x, e.y)) continue;
    const d = dist2(player.x, player.y, e.x, e.y);
    // The avatar comes first among what can actually be hit -- nearest-target
    // alone cannot fight a boss, because his escort soaks every crescent.
    if (e.kind === 'deceiver') { if (d < avatarD) { avatarD = d; avatar = e; } }
    if (d < bestD) { bestD = d; best = e; }
  }
  best = avatar || best;
  if (!best) return false;

  const base = Math.atan2(best.y - player.y, best.x - player.x);
  // Extra crescents stagger behind the first rather than fanning out: two
  // blades of light chasing the same line reads as a combination strike, where
  // a spread reads as a shotgun.
  for (let i = 0; i < player.shots; i++) {
    const a = base + (i === 0 ? 0 : (i % 2 ? 1 : -1) * 0.15 * Math.ceil(i / 2));
    releaseCrescent(a, i * 0.055);
  }
  player.swing    = SWING_TIME;
  player.recov    = 0;
  player.swingA   = base;
  // Next form in the cycle. Slash, then rise, then chop, then round again --
  // three swings before the picture repeats instead of one.
  player.strike   = (player.strike + 1) % STRIKES.length;
  player.angle    = base;
  if (Math.abs(Math.cos(base)) > 0.25) player.face = Math.cos(base) < 0 ? -1 : 1;
  return true;
}

// One crescent of magic, thrown from the edge. `bow` is the radius the blade
// scribes, so the band bulges forward the way a swung edge does; `half` is how
// far along that band it reaches. Both are carried per-crescent so a boon can
// widen the sweep without re-forging anything.
//
// ON THE SPEED. A crescent's whole flight is `range / arcSpeed`, and it used
// to be 0.47s for Isaac against a swing that finishes in SWING_TIME, 0.17s.
// That is the swing and the hit reading as two separate attacks: you bring the
// blade round, it completes, and something dies half a second later at the far
// end of the room. The speeds are set so a crescent crosses its own full range
// in about 0.12s -- inside the swing -- and the blow lands while the edge is
// still coming through. It is the same single attack it always was; it just
// stopped arriving after the animation that threw it.
//
// The stat stays a stat rather than becoming `range / 0.12` so the boons keep
// meaning what they say: Long Reach still buys reach at a little flight time,
// and Swift Edge still buys the flight time back.
function releaseCrescent(a, delay) {
  const half = player.sweep;
  const bow  = Math.max(half * 1.15, 52);
  arcs.push({
    x: player.x + Math.cos(a) * (player.r + 8),
    y: player.y + Math.sin(a) * (player.r + 8),
    dx: Math.cos(a), dy: Math.sin(a), a: a,
    speed: player.arcSpeed, dmg: player.damage,
    half: half, bow: bow, band: 11,
    delay: delay || 0,
    life: player.range / player.arcSpeed,
    maxLife: player.range / player.arcSpeed,
    hit: [], dead: false
  });
}

// Is there open ground the whole way between two points? Sampled rather than
// swept: at 14-unit steps nothing thinner than half a cell can hide between
// samples, and it runs only for bodies already inside weapon reach.
function clearShot(x0, y0, x1, y1) {
  const dx = x1 - x0, dy = y1 - y0;
  const len = Math.hypot(dx, dy);
  const steps = Math.min(24, Math.max(1, Math.ceil(len / 14)));
  for (let i = 1; i < steps; i++) {
    const t = i / steps;
    if (pointInWalls(x0 + dx * t, y0 + dy * t, 3)) return false;
  }
  return true;
}

function dropLoot(e) {
  loot.push({
    x: e.x, y: e.y,
    vx: rand(-38, 38), vy: rand(-38, 38),
    value: e.tech, r: 6, spin: Math.random() * TAU, life: 0, pulled: false
  });
  maybeDropItem(e);
}

const BAG_MAX = 20;

// Gear falls where the body did. Chance and quality both follow how deep the
// body was standing, so pushing further in is what pays.
function maybeDropItem(e) {
  const depth = clamp(Math.hypot(e.x - run.spawnX, e.y - run.spawnY) /
                      (Math.hypot(WORLD.w, WORLD.h) * 0.5), 0, 1);
  // What killed matters as much as where. A thrall is a lottery ticket; a
  // champion is the reason to fight one.
  let chance = e.kind === 'deceiver' ? 1 :
               e.elite               ? 0.85 :
               e.kind === 'breaker'  ? 0.22 :
               e.kind === 'mirage'   ? 0 : 0.055;
  chance *= (1 + depth * 0.8) * DIFF.lootRate;
  const n = e.kind === 'deceiver' ? 3 : e.elite ? 2 : 1;

  // Regalia pieces come off champions and the avatar only -- and an invader
  // always. Being hunted through a delve you did not plan to fight in is the
  // price, and it should be paid.
  const setOdds = e.invader ? 1 : e.kind === 'deceiver' ? 0.55 : e.elite ? 0.14 : 0;
  // Coin falls with the gear. It is the only thing in the delve that is not
  // luck: whatever the drops do, coin accumulates, which is what makes it the
  // right currency for buying your way past a bad streak.
  const purse = e.kind === 'deceiver' ? 90 : e.elite ? 26 : e.kind === 'breaker' ? 9 : 2;
  if (purse) {
    run.coins += Math.round(purse * (0.7 + Math.random() * 0.7) *
                            (1 + (LEVEL.depth || 0) * 1.4) * DIFF.lootRate);
  }

  const push = it => drops.push({
    x: e.x + rand(-14, 14), y: e.y + rand(-14, 14),
    vx: rand(-46, 46), vy: rand(-46, 46),
    item: it, r: 9, life: 0, pulled: false });

  if (setOdds && Math.random() < setOdds * DIFF.setRate * setBoost()) {
    push(rollSetPiece());
    if (e.kind !== 'deceiver') return;      // one piece is the whole prize
  }
  for (let i = 0; i < n; i++) {
    if (i === 0 && Math.random() > chance) return;
    // Quality floor by what it came off, so a champion never hands you rags.
    const floor = e.kind === 'deceiver' ? 0.85 : e.elite ? 0.7 : 0;
    push(rollItem(Math.max(depth, floor)));
  }
}

/* --- what the Flayer leaves, and what the Shaman takes --------------------
   A bleed is damage that arrives after the thing that caused it has gone. It
   is the whole point of the Flayer: the run is survivable and the wound is
   what costs you, so the answer is to break it rather than to out-trade it.
   It does not stack -- a second cut refreshes the clock instead of doubling
   the rate, or a pack of them is an execution.

   The gloom is the Shaman taking the light. Nothing is hidden that was not
   already off-screen; the reach of what the Vanguard carries simply closes,
   which is enough to make a room you had read stop being read.
   -------------------------------------------------------------------- */
function openWound(dps, life) {
  player.bleed = Math.max(player.bleed || 0, life);
  player.bleedDps = dps;
  player.bleedTick = Math.min(player.bleedTick || BLEED_TICK, BLEED_TICK);
}

function updateBleed(dt) {
  if (!player.bleed || player.bleed <= 0) return;
  player.bleed -= dt;
  player.bleedTick -= dt;
  if (player.bleedTick <= 0) {
    player.bleedTick = BLEED_TICK;
    // Through the i-frames: a wound does not care that you were just hit, and
    // a bleed the player can outrun by taking another blow is not a bleed.
    const was = player.invuln;
    player.invuln = 0;
    hurtPlayerBy(player.bleedDps * BLEED_TICK, player.x, player.y);
    player.invuln = was;
    floatDmg(player.x, player.y - player.r * 1.4, player.bleedDps * BLEED_TICK, 'bleed');
    if (player.hp > 0) burst(player.x, player.y, PAL.blood, 4, 90);
  }
  if (player.bleed <= 0) { player.bleed = 0; player.bleedDps = 0; }
}

function castGloom() {
  run.gloom = GLOOM_TIME;
  shake(4);
}

function updateGloom(dt) {
  if (run.gloom > 0) run.gloom = Math.max(0, run.gloom - dt);
}

/* --- bolts ----------------------------------------------------------------
   The first thing in the delve that comes at you through the air. A cantor
   only throws when it has a clear line, and rock stops the bolt in flight, so
   a wall is cover rather than scenery -- which is what the rooms were cut for.

   Travel is substepped like the crescent's, so a bolt cannot skip a thin wall
   or step over the player between one frame and the next.
   -------------------------------------------------------------------- */
let bolts = [];

function fireBolt(e) {
  if (bolts.length >= MAX_BOLTS) return;
  const dx = player.x - e.x, dy = player.y - e.y;
  const d = Math.hypot(dx, dy) || 1;
  bolts.push({ x: e.x + (dx / d) * (e.r + 6), y: e.y + (dy / d) * (e.r + 6),
               dx: dx / d, dy: dy / d, dmg: e.dmg, colour: e.color,
               life: BOLT_RANGE / BOLT_SPEED, spin: Math.random() * TAU, dead: false });
  burst(e.x, e.y, e.color, 5, 90);
}

function updateBolts(dt) {
  let w = 0;
  for (let i = 0; i < bolts.length; i++) {
    const b = bolts[i];
    b.life -= dt;
    b.spin += dt * 9;
    if (b.life <= 0) continue;
    const travel = BOLT_SPEED * dt;
    const steps = Math.min(6, Math.max(1, Math.ceil(travel / 8)));
    const st = travel / steps;
    for (let k = 0; k < steps && !b.dead; k++) {
      b.x += b.dx * st;
      b.y += b.dy * st;
      if (b.x < 0 || b.y < 0 || b.x > WORLD.w || b.y > WORLD.h) { b.dead = true; break; }
      if (pointInWalls(b.x, b.y, BOLT_R * 0.6)) {
        b.dead = true;
        burst(b.x, b.y, b.colour, 7, 130);
        break;
      }
      if (dist2(b.x, b.y, player.x, player.y) < (player.r + BOLT_R) * (player.r + BOLT_R)) {
        b.dead = true;
        hurtPlayerBy(b.dmg, b.x, b.y);
        burst(b.x, b.y, b.colour, 9, 160);
        break;
      }
    }
    if (!b.dead) bolts[w++] = b;
  }
  bolts.length = w;
}

// A husk coming apart. The blast is a slam, because a slam is already a
// telegraphed circle of ground that is about to be taken and there is no
// reason for this to be a second one of those.
//
// The ground is marked the moment it commits, not at the end of the fuse. The
// swelling sprite alone is not a telegraph the way the rest of the game means
// one: everything else that is about to take a piece of floor says so on the
// floor, and with only the last quarter-second marked there was not room to
// walk out of ninety-four units of blast.
//
// Arming is once. A husk that commits and is then broken still goes off, on
// its own clock, where it committed -- killing it early moves nothing.
function armHusk(e, wind) {
  if (e.armed) return;
  e.armed = true;
  slams.push({ x: e.x, y: e.y, r: HUSK_R, wind: wind, t: 0,
               dmg: HUSK_DMG * DIFF.threat, struck: false, husk: true });
}

function burstHusk(e) {
  e.hp = 0;
  e.burst = true;
  armHusk(e, HUSK_FUSE * 0.45);
  burst(e.x, e.y, e.color, 12, 150);
}

/* --- coffers --------------------------------------------------------------
   Something to find. Everything in the delve up to now came off a body, which
   makes the whole map one long corridor between fights; a coffer in a dead end
   is a reason to take the turning you did not have to take.

   They sit in penned-in ground by preference -- nooks, ends, the backs of
   rooms -- so finding one is a small piece of exploring rather than something
   you walk over on the way to the gate. Opening is walking onto it, like the
   corpse: there is no free hand on a phone for an action button.
   -------------------------------------------------------------------- */
let chests = [];
// Two coffers, four frames each of coming open, cut and graded from the sheet
// in assets/ by tools/build-art.py. Row 0 is the plain one, row 1 the warded.
const CHEST_SHEET = 'data:image/png;base64,';
const CHEST_C = 32, CHEST_FRAMES = 4;
const CHEST_ROW = { coffer: 0, warded: 1 };
const CHEST_OPEN = 0.45;        // seconds the lid takes to come up
let chestImg = null;
const CHEST_REACH = 30;
const CHEST_SAFE  = 320;    // never this near the spawn pocket
const CHEST_APART = 300;    // nor this near each other

// Every coffer in a delve, opened, comes to about a third of what the whole
// horde in it is worth in coin -- measured across five depths, and it holds at
// each because both scale on the same depth term. That is meant to be plainly
// worth the detour without making the player who walks straight at the gate
// feel robbed, and the gear the warded ones carry is on top of it.
const CHEST_KINDS = {
  coffer: { coin: [34, 74],  gear: 0.34, floor: 0,    name: 'A coffer',
            colour: '#c9a24a' },
  warded: { coin: [112, 205], gear: 1,   floor: 0.62, name: 'A warded coffer',
            colour: '#8fb8ff' }
};

function placeChests(spawn, portal) {
  chests = [];
  if (!openCells.length) return;
  const depth = LEVEL.depth || 0;
  const want = 3 + Math.round(depth * 3);
  const warded = Math.random() < 0.45 + depth * 0.4 ? 1 : 0;

  // Penned-in ground first. narrowGrid is 0 at a crossroads and 4 at a dead
  // end, and it is already built by the time this runs.
  const pool = [];
  for (let i = 0; i < openCells.length; i++) {
    const c = openCells[i];
    if (pointInWalls(c.x, c.y, 20)) continue;
    if (dist2(c.x, c.y, spawn.x, spawn.y) < CHEST_SAFE * CHEST_SAFE) continue;
    if (portal && dist2(c.x, c.y, portal.x, portal.y) < 200 * 200) continue;
    const cx = Math.floor(c.x / CELL_W), cy = Math.floor(c.y / CELL_W);
    pool.push({ x: c.x, y: c.y, pen: narrowGrid[gi(cx, cy)] || 0 });
  }
  if (!pool.length) return;
  // Shuffled, then sorted by how penned in -- so it is the tightest ground
  // available rather than the first tight cell the scan happened to reach.
  for (let i = pool.length - 1; i > 0; i--) {
    const j = (Math.random() * (i + 1)) | 0;
    const t = pool[i]; pool[i] = pool[j]; pool[j] = t;
  }
  pool.sort((a, b) => b.pen - a.pen);

  const total = want + warded;
  for (let i = 0; i < pool.length && chests.length < total; i++) {
    const c = pool[i];
    let ok = true;
    for (let k = 0; k < chests.length && ok; k++) {
      if (dist2(c.x, c.y, chests[k].x, chests[k].y) < CHEST_APART * CHEST_APART) ok = false;
    }
    if (!ok) continue;
    const kind = (warded && chests.length === 0) ? 'warded' : 'coffer';
    chests.push({ x: c.x, y: c.y, kind, open: false,
                  q: (Math.random() * 4) | 0, pulse: Math.random() * TAU });
  }
}

function openChest(ch) {
  if (ch.open) return;
  ch.open = true;
  ch.t = 0;                      // the lid takes CHEST_OPEN to come up
  const K = CHEST_KINDS[ch.kind];
  const depth = LEVEL.depth || 0;
  const coin = Math.round(rand(K.coin[0], K.coin[1]) * (1 + depth * 1.4) * DIFF.lootRate);
  run.coins += coin;
  run.chests = (run.chests || 0) + 1;

  burst(ch.x, ch.y, K.colour, 18, 190);
  ring(ch.x, ch.y, K.colour, 8, 46, 0.4);
  floatDmg(ch.x, ch.y - 12, coin, 'coin');

  // Gear lands on the floor as an ordinary drop, so a full bag behaves the
  // same way here as it does everywhere else rather than silently eating it.
  if (Math.random() < K.gear * DIFF.lootRate) {
    const it = rollItem(Math.max(depth, K.floor));
    drops.push({ x: ch.x + rand(-10, 10), y: ch.y + rand(-10, 10),
                 vx: rand(-40, 40), vy: rand(-40, 40),
                 item: it, r: 9, life: 0, pulled: false });
    toast(K.name + ' — ' + it.name, rarityOf(it).colour);
  } else {
    toast(K.name + ' — ' + coin + ' coin', K.colour);
  }
}

function updateChests(dt) {
  for (let i = 0; i < chests.length; i++) {
    const ch = chests[i];
    ch.pulse += dt;
    if (ch.open) { ch.t = Math.min(CHEST_OPEN, (ch.t || 0) + dt); continue; }
    if (dist2(player.x, player.y, ch.x, ch.y) < CHEST_REACH * CHEST_REACH) openChest(ch);
  }
}

// How wide a coffer is drawn. The sheet cells are 32, so this is a 1.5x blit
// with smoothing off -- the same deal the bag icons already take.
const CHEST_DRAW = 48;

/* --- hazards --------------------------------------------------------------
   Ground you cannot stand on. A slam is a moment; a hazard is a place, and
   the difference is what turns a room into terrain. The Riftborn leaves them
   where he steps out of the world.
   -------------------------------------------------------------------- */
const HAZARD_TICK = 0.4;   // how often standing in one costs you
let hazards = [];

/* --- reactive scenery -----------------------------------------------------
   The player has a stick and an automatic blade, so the only tactical input
   they have is *where* they fight. That is what this is for: a room with a
   pitch barrel in it is a different room, and standing in the right part of
   it is a decision the controls can actually express.

   A barrel takes a beat to go up after it is broken, so setting one off and
   then standing in it is your own fault rather than the auto-aim's. A pillar
   comes down at once, because a column of stone does not hesitate.
   -------------------------------------------------------------------- */
const PROP_HP    = { barrel: 26, pillar: 70 };
// Long enough to walk out of at hero speed with room to spare. The blade aims
// itself, so the player cannot choose not to break a barrel between them and
// what they are hitting -- the fuse is the whole of their agency here, and it
// has to be generous enough that being caught is a mistake rather than a tax.
const BARREL_FUSE = 1.1;
const BARREL_R    = 96;
const PILLAR_R    = 78;
// Shorter than a barrel's -- a column of stone does not hesitate long -- but
// not nothing. The blade aims itself, so an instant collapse for a third of a
// hero's life is a blow the player was never offered the chance to avoid.
const PILLAR_FUSE = 0.5;

// Everything in reach, player included. Scenery does not take sides.
// `pierce` forces the hit through the player's i-frames. A pitch barrel should
// land whether or not you were just clipped by something -- one blast, one
// blow. A husk cascade is a different thing: each link is its own blast, and
// piercing every one of them meant three husks standing on you was a certain
// death with no cap and no counterplay. Cascades respect i-frames, so a chain
// costs one blow and then costs another only if you are still standing in it
// when they run out.
function blastAt(x, y, r, dmg, hue, pierce) {
  shake(8);
  burst(x, y, hue, 22, 300);
  ring(x, y, hue, r * 0.35, r, 0.34);
  enemyGrid.query(x, y, r + 30, _near);
  for (let i = 0; i < _near.length; i++) {
    const e = _near[i];
    if (e.hp <= 0) continue;
    const d = Math.hypot(e.x - x, e.y - y);
    if (d > r + e.r) continue;
    damageEnemy(e, dmg * (1 - Math.min(0.6, d / (r * 2))));
  }
  if (dist2(player.x, player.y, x, y) < r * r) {
    if (pierce === false) {
      hurtPlayerBy(dmg * 0.4, x, y);
    } else {
      const was = player.invuln;
      player.invuln = 0;
      hurtPlayerBy(dmg * 0.4, x, y);
      player.invuln = Math.max(player.invuln, was);
    }
  }
}

function hurtProp(pr, dmg) {
  const cap = PROP_HP[pr.kind];
  if (!cap || pr.gone) return;
  if (pr.hp === undefined) pr.hp = cap;
  pr.hp -= dmg;
  pr.shake = 0.16;
  if (pr.hp > 0) return;
  pr.gone = true;
  // Both queue a marked circle, drawn like a slam so every promise the floor
  // makes reads the same way. What differs is how long you have.
  if (pr.kind === 'barrel') {
    slams.push({ x: pr.x, y: pr.y, r: BARREL_R, wind: BARREL_FUSE, t: 0,
                 dmg: 0, struck: false, barrel: true });
  } else {
    slams.push({ x: pr.x, y: pr.y, r: PILLAR_R, wind: PILLAR_FUSE, t: 0,
                 dmg: 0, struck: false, pillar: true });
  }
}

// A struck barrel rocks before it goes. Cheap, and it is the only warning the
// player gets that the thing they are standing next to is now a bomb.
function updateProps(dt) {
  for (let i = 0; i < propGrid.length; i++) {
    const pr = propGrid[i];
    if (pr.shake > 0) pr.shake = Math.max(0, pr.shake - dt);
  }
}

// Whatever is standing inside a radius and can be broken.
function hurtPropsNear(x, y, r, dmg) {
  for (let i = 0; i < props.length; i++) {
    const pr = props[i];
    if (pr.gone || !PROP_HP[pr.kind]) continue;
    if (dist2(pr.x, pr.y, x, y) > r * r) continue;
    hurtProp(pr, dmg);
  }
}

function addHazard(x, y, r, dps, life, hue) {
  if (hazards.length > 40) hazards.shift();
  hazards.push({ x, y, r, dps, life, max: life, tick: 0,
                 hue: hue || '#b07cff', wob: Math.random() * TAU });
}

function updateHazards(dt) {
  for (let i = hazards.length - 1; i >= 0; i--) {
    const h = hazards[i];
    h.life -= dt;
    h.wob += dt;
    if (h.life <= 0) { hazards.splice(i, 1); continue; }
    h.tick -= dt;
    if (h.tick <= 0 && dist2(player.x, player.y, h.x, h.y) < h.r * h.r) {
      h.tick = HAZARD_TICK;
      // A hazard is not a hit: it ignores the invulnerability a hit grants,
      // or standing in one would be free for as long as something else was
      // also touching you.
      const was = player.invuln;
      player.invuln = 0;
      hurtPlayerBy(h.dps * HAZARD_TICK, h.x, h.y);
      player.invuln = Math.max(player.invuln, was);
    }
  }
}

// Slams land on their own clock rather than on the thrower's, so a lieutenant
// killed mid-wind still lands the blow it had already committed to.
function updateSlams(dt) {
  for (let i = slams.length - 1; i >= 0; i--) {
    const s = slams[i];
    s.t += dt;
    if (!s.struck && s.t >= s.wind) {
      s.struck = true;
      if (s.barrel) {
        const dmg = 62 * (1 + (LEVEL.depth || 0));
        blastAt(s.x, s.y, s.r, dmg, '#ff9a3c');
        // and it keeps burning, so the ground it took stays taken
        addHazard(s.x, s.y, s.r * 0.78, dmg * 0.22, 4.5, '#ff9a3c');
        // pitch spreads: a barrel takes its neighbours with it
        hurtPropsNear(s.x, s.y, s.r, 999);
      } else if (s.husk) {
        blastAt(s.x, s.y, s.r, s.dmg, '#c8d63a', false);
        addHazard(s.x, s.y, s.r * 0.5, s.dmg * 0.18, 2.6, '#c8d63a');
        hurtPropsNear(s.x, s.y, s.r, s.dmg);
      } else if (s.pillar) {
        blastAt(s.x, s.y, s.r, 88 * (1 + (LEVEL.depth || 0)), '#cbbfa4');
        for (let i = 0; i < 5; i++) {
          props.push({ x: s.x + rand(-24, 24), y: s.y + rand(-16, 16),
                       q: (Math.random() * 4) | 0, kind: 'rubble' });
        }
      } else {
        shake(s.fracture ? 12 : 7);
        burst(s.x, s.y, s.fracture ? '#e0402c' : '#ffce70', s.fracture ? 30 : 20, 300);
        ring(s.x, s.y, s.fracture ? '#e0402c' : '#ffce70', s.r * 0.5, s.r, 0.32);
        // A gorger does not just hit the floor, it opens it: the ground it
        // came down on stays broken and burning, so the corridor it chose is
        // a corridor you now have to go round.
        if (s.fracture) {
          addHazard(s.x, s.y, s.r * 0.72, FRACTURE_DPS, FRACTURE_LIFE, '#e0402c');
          for (let k = 0; k < 6; k++) {
            props.push({ x: s.x + rand(-s.r * 0.7, s.r * 0.7),
                         y: s.y + rand(-s.r * 0.5, s.r * 0.5),
                         q: (Math.random() * 4) | 0, kind: 'rubble' });
          }
        }
        // and a slam brings scenery down with it
        hurtPropsNear(s.x, s.y, s.r, s.dmg);
        if (dist2(player.x, player.y, s.x, s.y) < s.r * s.r) {
          hurtPlayerBy(s.dmg, s.x, s.y);
        }
      }
    }
    if (s.t >= s.wind + 0.34) slams.splice(i, 1);
  }
}

function updateDrops(dt) {
  const damp = Math.pow(0.1, dt);
  let w = 0;
  for (let i = 0; i < drops.length; i++) {
    const d0 = drops[i];
    d0.life += dt;
    const dx = player.x - d0.x, dy = player.y - d0.y;
    const d = Math.hypot(dx, dy) || 1;
    // Gear is drawn in at a shorter reach than slag: it should be picked up
    // on purpose, not hoovered off the far side of a room.
    // Vacuum looting. Gear used to need a deliberate walk-over; with the bag
    // now sorted between delves rather than during one, there is nothing to
    // decide in the moment, so picking it up should never cost tempo.
    if (!d0.pulled && d < player.magnet * 1.6) d0.pulled = true;
    if (d0.pulled) {
      const k = Math.min(1, dt * 6);
      d0.vx = lerp(d0.vx, (dx / d) * 420, k);
      d0.vy = lerp(d0.vy, (dy / d) * 420, k);
    } else { d0.vx *= damp; d0.vy *= damp; }
    d0.x += d0.vx * dt; d0.y += d0.vy * dt;

    if (d < player.r + 12) {
      if (player.bag.length < bagCap()) {
        player.bag.push(d0.item);
        run.found++;
        syncBagBadge();
        burst(d0.x, d0.y, rarityOf(d0.item).colour, 8, 150);
        toast(d0.item.name, rarityOf(d0.item).colour);
        continue;
      }
      // Bag full: leave it on the floor rather than silently binning it, and
      // say so once rather than every frame it is touched.
      if (!run.bagWarned) { run.bagWarned = 2.5; toast('Bag full', '#c9863e'); }
      d0.pulled = false;
      d0.vx = -(dx / d) * 90; d0.vy = -(dy / d) * 90;
    }
    drops[w++] = d0;
  }
  drops.length = w;
}

/* --- the corpse run -------------------------------------------------------
   Dying is not a reset. Everything unbanked -- the bag and the run's coin --
   stays in the delve, and the delve keeps it: descend into the same level
   again and it is lying where you fell. Only one corpse exists at a time, so
   dying on the way back to a corpse costs you the first one. That is the
   whole tension, and it is why the walk back is worth anything.
   -------------------------------------------------------------------- */

// Where you fell, snapped onto ground that exists *this* descent. The delve is
// cut fresh every time, so the recorded point is a hint rather than an
// address.
function placeCorpse() {
  const c = stash.corpse;
  if (!c || c.level_id !== LEVEL.id || !openCells.length) return null;
  if (!(c.items && c.items.length) && !c.coins) return null;
  let best = null, bestD = Infinity;
  for (let i = 0; i < openCells.length; i++) {
    const o = openCells[i];
    if (pointInWalls(o.x, o.y, 16)) continue;
    const d = dist2(o.x, o.y, c.x, c.y);
    if (d < bestD) { bestD = d; best = o; }
  }
  if (!best) return null;
  return { x: best.x, y: best.y, items: c.items || [], coins: c.coins || 0,
           pulse: Math.random() * TAU, taken: 0 };
}

// Reclaiming it is the ambush: the delve raises a ring of champions and forces
// the ley-gate open. You get your things back and a way out at the same
// moment, and no time at all to spend deciding which.
function claimCorpse() {
  const c = run.corpse;
  if (!c || c.taken) return;
  c.taken = 1;

  let took = 0;
  for (const it of c.items) {
    if (player.bag.length >= bagCap()) break;
    player.bag.push(it);
    took++;
  }
  const left = c.items.length - took;
  run.found += took;
  run.coins += c.coins;
  syncBagBadge();

  // Anything the bag could not hold stays on the floor as ordinary drops
  // rather than evaporating.
  for (let i = took; i < c.items.length; i++) {
    drops.push({ x: c.x + rand(-26, 26), y: c.y + rand(-26, 26),
                 vx: rand(-40, 40), vy: rand(-40, 40),
                 item: c.items[i], r: 9, life: 0, pulled: false });
  }

  stash.corpse = null;
  saveStash();

  burst(c.x, c.y, CORPSE_HUE, 30, 240);
  ring(c.x, c.y, CORPSE_HUE, 10, 150, 0.7);
  cam.shake = Math.max(cam.shake, 9);

  run.forcedOpen = true;
  portal.channel = 0;
  const n = clamp(Math.round(AMBUSH_MIN + (LEVEL.depth || 0) * 4.5),
                  AMBUSH_MIN, AMBUSH_MAX);
  const raised = spawnAmbush(c.x, c.y, n);

  run.banner = 3.4;
  run.bannerText = 'The delve gives up your dead';
  run.bannerNote = raised
    ? 'It wants them back. The ley-gate is open -- go.'
    : 'The ley-gate is open -- go.';
  toast(left ? 'Reclaimed ' + took + ' of ' + c.items.length : 'Corpse reclaimed',
        CORPSE_HUE);
}

function updateCorpse(dt) {
  const c = run.corpse;
  if (!c || c.taken) return;
  c.pulse += dt;
  if (dist2(player.x, player.y, c.x, c.y) < 34 * 34) claimCorpse();
}

// A short line above the HUD: what you just picked up, in its rarity colour.
function toast(text, colour) {
  run.toast = { text, colour, life: 2.4 };
}

// Expanding shockwave ring — a few strokes, but it is what makes a kill read
// as an event rather than a sprite vanishing.
const MAX_RINGS = 40;
function ring(x, y, color, r0, r1, life) {
  if (rings.length >= MAX_RINGS) return;
  rings.push({ x, y, color, r0, r1, life, max: life });
}

function burst(x, y, color, n, spd) {
  for (let i = 0; i < n && particles.length < MAX_PARTICLES; i++) {
    const a = Math.random() * TAU, s = rand(spd * 0.35, spd);
    particles.push({
      x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s,
      life: rand(0.22, 0.5), max: 0.5, color, size: rand(1.4, 3.2)
    });
  }
}

/* --- floating combat text -------------------------------------------------
   What a hit was worth, said in the place it landed. Without it the only
   feedback a blow gives is a flash and a health bar creeping, and the two
   things the player most needs to read -- that a braced anchor is eating the
   swing, and that the Deceiver takes almost nothing while his Lieutenants
   stand -- are invisible. Those come through as a dimmed number, so the
   mechanic teaches itself.

   Capped, and merged: a crescent sweeping eight bodies at once would
   otherwise put eight numbers in the same square inch, and text is the most
   expensive thing this renderer draws. A second hit on a body inside the
   merge window adds to the number already rising off it instead.        */
const MAX_FLOATERS = 22;
const FLOAT_LIFE   = 0.85;
const FLOAT_MERGE  = 0.22;   // a follow-up this soon joins the running total

/* --- the kit ---------------------------------------------------------------
   Until now the Vanguard had a blade that aimed itself and nothing else, and
   the whole interface was built on there being no free thumb for a button. So
   the bar is a real reversal, and it is placed accordingly: the stick floats
   under the left thumb wherever it lands, and the kit sits in a fixed arc
   under the right, where nothing else has ever been.

   An ability is data. `cost` is spent from the hero's resource, `build` puts
   it back, `cd` is its own cooldown, and `gcd` is whether it takes the beat --
   an interrupt does not, because an interrupt you have to wait for is not an
   interrupt.
   -------------------------------------------------------------------- */
const CHARGE_MAX = 3;      // Isaac's Sun-Gold Charges
const TENSION_MAX = 100;   // Zayd's Ley-Tension
const TENSION_REGEN = 4;   // a second, which is slow on purpose: the pool is
                           // meant to be refilled by interrupting, not by waiting
const SWAP_CD = 5;         // and how long before the other one can be called back
const JAR_USES = 3;        // Crimson-Infused Jars carried into a delve
const VULN_TIME  = 10;     // how long Metaphysical Vulnerability lasts
const VULN_MULT  = 5;      // and what the Guillotine does to a body under it

const ABILITIES = {
  isaac: [
    { id: 'anchor', name: 'Anchoring Strike', mark: '✦',
      note: 'A shield bash, close enough to touch. Builds a Charge.',
      cd: 0, gcd: 1, build: 1, reach: 62, dmg: 2.4 },
    { id: 'aegis', name: 'Aegis of Tor-Varden', mark: '◉',
      note: 'Spends three. A ring of Sun-Gold, and a moment behind the guard.',
      cd: 0, gcd: 1, cost: CHARGE_MAX, radius: 150, dmg: 3.2, mitigate: 2 },
    { id: 'mass', name: 'Unyielding Mass', mark: '▣',
      note: 'Rooted, unmovable, and half the harm for four seconds.',
      cd: 12, gcd: 1, root: 4 },
    { id: 'purge', name: 'Grounding Purge', mark: '✚',
      note: 'Channelled. Breaks the moment you are struck or move.',
      cd: 14, gcd: 1, channel: 3, healPct: 0.15 },
    { id: 'guillotine', name: 'Star-Forged Guillotine', mark: '⚔',
      note: 'Spends three. Comes down on one body, and on the Vulnerable it ends things.',
      cd: 0, gcd: 1.25, cost: CHARGE_MAX, reach: 96, dmg: 7 }
  ],
  zayd: [
    { id: 'truth', name: 'Piercing Truth', mark: '↠',
      note: 'A line of Azure through everything standing in it. Builds Tension.',
      cd: 0, gcd: 1, build: 14, reach: 340, dmg: 1.5 },
    { id: 'nullzone', name: 'Null-Zone Eruption', mark: '◍',
      note: 'Spends two fifths. A pool that slows what stands in it and eats what it is casting.',
      cd: 0, gcd: 1, costPct: 0.40, radius: 96, life: 7 },
    { id: 'decrypt', name: 'Focal Decryption', mark: '⌁',
      note: 'Off the beat. Snaps a cast, silences for three, and gives the Tension back.',
      cd: 8, gcd: 0, reach: 300, silence: 3 },
    { id: 'jars', name: 'Crimson-Infused Jars', mark: '⚱',
      note: 'Three to a delve. Instant, and a great deal of life at once.',
      cd: 30, gcd: 1, uses: 3, healPct: 0.45 }
  ]
};

const ABILITY_BY_ID = {};
for (const h in ABILITIES) for (const a of ABILITIES[h]) ABILITY_BY_ID[a.id] = a;

const heroKit = () => ABILITIES[player.hero] || [];

// What stops a button working, said in the order the player would ask it.
function abilityBlock(a) {
  if (state !== 'play') return 'no';
  if (player.channel) return a.id === player.channel.id ? 'no' : 'busy';
  if ((player.cds && player.cds[a.id] > 0)) return 'cd';
  if (a.gcd && onGCD()) return 'gcd';
  if (a.cost && (player.charges || 0) < a.cost) return 'cost';
  if (a.costPct && (player.tension || 0) < TENSION_MAX * a.costPct) return 'cost';
  if (a.uses && (player.jars || 0) <= 0) return 'cost';
  return null;
}

function castAbility(id) {
  const a = ABILITY_BY_ID[id];
  if (!a || abilityBlock(a)) return false;
  if (a.cost) spendCharges(a.cost);
  if (a.costPct) { player.tension = Math.max(0, (player.tension || 0) - TENSION_MAX * a.costPct);
                   player.chargePop = 1; }
  if (a.cd) { player.cds = player.cds || {}; player.cds[a.id] = a.cd; }
  if (a.gcd) startGCD(a.gcd);
  ABILITY_DO[a.id](a);
  return true;
}

// Charges are shown as pips, so gaining one has to be visible: a number that
// changes with nothing happening around it is a number nobody reads.
function gainCharge(n) {
  const was = player.charges || 0;
  player.charges = Math.min(CHARGE_MAX, was + (n || 1));
  if (player.charges !== was) {
    player.chargePop = 1;
    if (player.charges === CHARGE_MAX) shake(3);
  }
}
function spendCharges(n) {
  player.charges = Math.max(0, (player.charges || 0) - n);
  player.chargePop = 1;
}

/* --- what each one does --------------------------------------------------
   Kept apart from the table so the table stays readable as a list of terms.
   -------------------------------------------------------------------- */
const ABILITY_DO = {

  // A bash. It has to be delivered from inside touching distance, which is
  // what makes it a decision rather than a second auto-attack.
  anchor(a) {
    const t = nearestBody(a.reach);
    player.swing = SWING_TIME;
    player.strike = 2;                       // the overhead form
    if (!t) { toast('Nothing in reach', '#8c8168'); return; }
    player.angle = Math.atan2(t.y - player.y, t.x - player.x);
    if (Math.abs(Math.cos(player.angle)) > 0.25)
      player.face = Math.cos(player.angle) < 0 ? -1 : 1;
    damageEnemy(t, player.damage * a.dmg);
    knock(t, player.angle, 200);
    freeze(0.03);
    shake(5);
    burst(t.x, t.y, '#ffd870', 10, 190);
    ring(t.x, t.y, '#ffd870', 6, 44, 0.26);
    gainCharge(a.build);
  },

  // The ring. Everything in reach, and a moment of the guard afterwards.
  aegis(a) {
    ring(player.x, player.y, '#ffd870', 12, a.radius, 0.42);
    burst(player.x, player.y, '#ffe9b0', 26, 320);
    shake(9);
    freeze(0.05);
    enemyGrid.query(player.x, player.y, a.radius, _near);
    for (let i = 0; i < _near.length; i++) {
      const e = _near[i];
      if (e.hp <= 0) continue;
      if (dist2(player.x, player.y, e.x, e.y) > a.radius * a.radius) continue;
      damageEnemy(e, player.damage * a.dmg);
      knock(e, Math.atan2(e.y - player.y, e.x - player.x), 240);
    }
    player.mitigate = a.mitigate;
  },

  // Rooted. The trade is plain: you cannot leave, and almost nothing moves you.
  mass(a) {
    player.rooted = a.root;
    player.mitigate = Math.max(player.mitigate || 0, a.root);
    ring(player.x, player.y, '#e2b96a', 10, 60, 0.5);
    toast('Rooted — unmovable', '#e2b96a');
  },

  // A channel, and the most fragile thing in the kit.
  purge(a) {
    player.channel = { id: a.id, left: a.channel, total: a.channel };
    stickEnd();
  },

  // The execution. Everything about it is weight: the longest beat, the
  // hardest freeze, and on a Vulnerable body it is meant to end the fight.
  guillotine(a) {
    const t = nearestBody(a.reach);
    player.swing = SWING_TIME * 1.6;
    player.strike = 2;
    if (!t) { toast('Nothing in reach', '#8c8168'); return; }
    player.angle = Math.atan2(t.y - player.y, t.x - player.x);
    const vuln = (t.vuln || 0) > 0;
    freeze(0.08);
    shake(vuln ? 16 : 11);
    ring(t.x, t.y, vuln ? '#fff2c8' : '#ffd870', 8, vuln ? 190 : 120, 0.5);
    burst(t.x, t.y, '#fff2c8', vuln ? 40 : 22, 380);
    damageEnemy(t, player.damage * a.dmg * (vuln ? VULN_MULT : 1));
    if (vuln) toast('The guard is broken', '#fff2c8');
  },

  // A line, not a target. It rewards putting a corridor between you and the
  // horde, which is the whole of how Zayd is meant to be played.
  truth(a) {
    const ang = player.angle;
    const ex = player.x + Math.cos(ang) * a.reach;
    const ey = player.y + Math.sin(ang) * a.reach;
    beams.push({ x: player.x, y: player.y, ex, ey, life: 0.24, max: 0.24 });
    shake(4);
    let hits = 0;
    enemyGrid.query((player.x + ex) / 2, (player.y + ey) / 2, a.reach, _near);
    for (let i = 0; i < _near.length; i++) {
      const e = _near[i];
      if (e.hp <= 0) continue;
      // Distance from the body to the line, so everything standing in it is
      // struck rather than only what the beam's centre passes through.
      if (segDist(player.x, player.y, ex, ey, e.x, e.y) > e.r + 10) continue;
      if (!clearShot(player.x, player.y, e.x, e.y)) continue;
      damageEnemy(e, player.damage * a.dmg);
      burst(e.x, e.y, '#5fd0ff', 6, 150);
      hits++;
    }
    if (hits) { gainTension(a.build * hits); freeze(0.02); }
  },

  // A pool that holds ground. It does not kill; it decides where the fight
  // can happen, and it eats what the back rank is casting.
  nullzone(a) {
    tryNullify(player.x, player.y, a.radius);
    nulls.push({ x: player.x, y: player.y, r: a.radius, life: a.life, max: a.life,
                 pulse: 0 });
    ring(player.x, player.y, '#b07cff', 10, a.radius, 0.44);
    burst(player.x, player.y, '#7a4fd0', 22, 250);
    shake(6);
  },

  // Off the beat, because an interrupt you have to wait for is not one. It
  // finds what is actually casting rather than what is nearest.
  decrypt(a) {
    const t = nearestCaster(a.reach);
    if (!t) {
      // A miss costs a fraction of the cooldown, not all of it and not none.
      // The full eight seconds makes one mistimed press a disaster; nothing at
      // all makes it free to mash, and then there is no timing to get right,
      // which is the whole of what this ability is.
      if (player.cds) player.cds.decrypt = a.cd * 0.2;
      toast('Nothing is casting', '#8c8168');
      return;
    }
    silence(t, a.silence);
    gainTension(TENSION_MAX);
    beams.push({ x: player.x, y: player.y, ex: t.x, ey: t.y, life: 0.2, max: 0.2,
                 hue: '#b07cff' });
    burst(t.x, t.y, '#b07cff', 16, 220);
    ring(t.x, t.y, '#b07cff', 6, t.r * 3, 0.3);
    freeze(0.04);
    shake(7);
    toast('Snapped', '#b07cff');
  },

  // Three to a delve, configured at the Forge. Instant, and enormous.
  jars(a) {
    if ((player.jars || 0) <= 0) { toast('No jars left', '#8c8168'); return; }
    player.jars--;
    const heal = player.maxHp * a.healPct;
    player.hp = Math.min(player.maxHp, player.hp + heal);
    floatDmg(player.x, player.y - player.r * 1.4, heal, 'heal');
    burst(player.x, player.y, '#c2352a', 20, 200);
    ring(player.x, player.y, '#e0563f', 8, 54, 0.36);
  }
};

// Beams and Null-Zones: the two things Zayd leaves on the floor.
let beams = [];
let nulls = [];

// Distance from a point to a segment. Piercing Truth is a line, so everything
// standing in it has to be struck, not only what the centre line passes over.
function segDist(ax, ay, bx, by, px, py) {
  const dx = bx - ax, dy = by - ay;
  const l2 = dx * dx + dy * dy;
  if (l2 < 1e-6) return Math.hypot(px - ax, py - ay);
  let t = ((px - ax) * dx + (py - ay) * dy) / l2;
  t = clamp(t, 0, 1);
  return Math.hypot(px - (ax + dx * t), py - (ay + dy * t));
}

function gainTension(n) {
  const was = player.tension || 0;
  player.tension = Math.min(TENSION_MAX, was + n);
  if (player.tension !== was) player.chargePop = 1;
}

// Who is actually mid-cast. A cantor winding a bolt and a shaman winding a
// chant are both casting; a body walking at you is not, and an interrupt that
// fires on the nearest body is not an interrupt.
function isCasting(e) {
  // A body closing itself up is casting too. That is what gives Zayd's
  // interrupt something to do outside a boss room.
  return e.hp > 0 && ((e.casting || 0) > 0 || (e.chanting || 0) > 0 ||
                      (e.calcify || 0) > 0);
}

function nearestCaster(R) {
  enemyGrid.query(player.x, player.y, R, _near);
  let best = null, bestD = R * R;
  for (let i = 0; i < _near.length; i++) {
    const e = _near[i];
    if (!isCasting(e)) continue;
    if (!clearShot(player.x, player.y, e.x, e.y)) continue;
    const d = dist2(player.x, player.y, e.x, e.y);
    if (d < bestD) { bestD = d; best = e; }
  }
  return best;
}

// Silenced: whatever it was winding is lost, and it cannot start another.
function silence(e, seconds) {
  e.silenced = Math.max(e.silenced || 0, seconds);
  e.casting = 0; e.chanting = 0;
  if (e.calcify > 0) breakCalcify(e, true);
  // Put its own clock back too, or it starts again the instant the silence
  // lifts and the interrupt bought nothing.
  if (e.cast !== undefined) e.cast = Math.max(e.cast, seconds * 0.6);
  if (e.chant !== undefined) e.chant = Math.max(e.chant, seconds * 0.6);
}

function updateBeams(dt) {
  for (let i = beams.length - 1; i >= 0; i--) {
    beams[i].life -= dt;
    if (beams[i].life <= 0) beams.splice(i, 1);
  }
}

// The pools. They slow what stands in them and eat what it is casting, which
// is what makes a Null-Zone an answer to the back rank rather than damage.
function updateNulls(dt) {
  for (let i = nulls.length - 1; i >= 0; i--) {
    const z = nulls[i];
    z.life -= dt;
    z.pulse += dt;
    if (z.life <= 0) { nulls.splice(i, 1); continue; }
    enemyGrid.query(z.x, z.y, z.r, _near);
    for (let k = 0; k < _near.length; k++) {
      const e = _near[k];
      if (e.hp <= 0) continue;
      if (dist2(e.x, e.y, z.x, z.y) > z.r * z.r) continue;
      e.slowed = Math.max(e.slowed || 0, 0.12);
      if (e.casting > 0) e.casting = Math.min(e.casting + dt * 2.2, 1e9);
      if (e.chanting > 0) e.chanting = Math.min(e.chanting + dt * 2.2, 1e9);
    }
  }
}

// Nearest body inside a radius that is actually reachable. Shares the rule the
// blade uses: rock stops everything, and Isaac does not see mirages.
function nearestBody(R) {
  enemyGrid.query(player.x, player.y, R, _near);
  const blind = player.hero === 'isaac';
  let best = null, bestD = R * R;
  for (let i = 0; i < _near.length; i++) {
    const e = _near[i];
    if (e.hp <= 0) continue;
    if (blind && e.kind === 'mirage') continue;
    if (!clearShot(player.x, player.y, e.x, e.y)) continue;
    const d = dist2(player.x, player.y, e.x, e.y);
    if (d < bestD) { bestD = d; best = e; }
  }
  return best;
}

// Shove a body. Heavier things move less, and an anchor at its post does not
// move at all -- it is the whole of what an anchor is.
function knock(e, ang, force) {
  if (!e || e.hp <= 0) return;
  const f = force / Math.max(0.6, e.mass || 1);
  moveEntity(e, Math.cos(ang) * f * 0.05, Math.sin(ang) * f * 0.05);
}

// Cooldowns, the channel, and the timed states the kit puts on the hero.
function updateAbilities(dt) {
  if (player.cds) {
    for (const k in player.cds) {
      if (player.cds[k] > 0) player.cds[k] = Math.max(0, player.cds[k] - dt);
    }
  }
  if (player.chargePop > 0) player.chargePop = Math.max(0, player.chargePop - dt * 3);
  if (player.mitigate > 0) player.mitigate = Math.max(0, player.mitigate - dt);
  if (player.rooted > 0) player.rooted = Math.max(0, player.rooted - dt);
  if (player.swapCd > 0) player.swapCd = Math.max(0, player.swapCd - dt);
  // Tension comes back slowly on its own. It is meant to be refilled by
  // interrupting something, not by standing still and waiting.
  if (player.hero === 'zayd' && (player.tension || 0) < TENSION_MAX) {
    player.tension = Math.min(TENSION_MAX, (player.tension || 0) + TENSION_REGEN * dt);
  }

  const c = player.channel;
  if (c) {
    const a = ABILITY_BY_ID[c.id];
    c.left -= dt;
    if (a.healPct) {
      player.hp = Math.min(player.maxHp, player.hp + player.maxHp * a.healPct * dt);
    }
    if (c.left <= 0) { player.channel = null; toast('Grounded', '#9dbb5a'); }
  }
}

// Any of these ends a channel. Being struck is the obvious one; moving is the
// one that matters, because it is what stops the channel being a free heal
// you press whenever the floor is quiet.
function breakChannel(why) {
  if (!player.channel) return;
  const a = ABILITY_BY_ID[player.channel.id];
  player.channel = null;
  // A broken channel still costs its cooldown -- otherwise the answer to
  // being interrupted is to press it again immediately.
  if (a && a.cd) { player.cds = player.cds || {}; player.cds[a.id] = a.cd; }
  toast(why === 'hurt' ? 'The channel breaks' : 'You move, and it lapses', '#8c8168');
}

/* --- the beat of a fight ----------------------------------------------------
   Three things below, and all of them exist to make a blow feel like it landed
   rather than like a number changed.

   The GLOBAL COOLDOWN is the pacing rule the whole kit is written against: an
   ability locks every other ability for a beat, so a fight is a sequence of
   decisions rather than a fistful of buttons pressed at once. It is a lock on
   the ability bar only -- moving, swinging the blade and drinking are not on
   it, because a game you play with one thumb cannot afford to take movement
   away.

   The HIT-STOP freezes the simulation for a few frames on a heavy landing.
   Drawing continues, so the screen does not blink; the world simply stops for
   40ms and the blow reads as weight. It is capped and it is spent in real
   time, or a chain of heavy hits would stall the game rather than punctuate it.

   The SHAKE is bound to what actually happened -- a share of the life it cost
   you, not a constant -- so a scratch and a near-death do not shake alike.
   -------------------------------------------------------------------- */
const GCD_TIME   = 1.2;    // the beat every ability is written against
const HITSTOP_MAX = 0.09;  // never freeze longer than this, however heavy

let hitStop = 0;

// Freeze the simulation for a moment. Called at the point of impact, not at
// the point of the swing: the pause has to land with the blow.
function freeze(seconds) {
  hitStop = Math.min(HITSTOP_MAX, Math.max(hitStop, seconds));
}

// Is the bar locked? Everything on the global cooldown asks this first.
const onGCD = () => (player.gcd || 0) > 0;

// Start the beat. `mul` lets a heavier ability cost a longer one.
function startGCD(mul) {
  player.gcd = GCD_TIME * (mul === undefined ? 1 : mul);
  player.gcdMax = player.gcd;
}

/* A word where a number would go. Same lane, same easing, no arithmetic.
 *
 * NOT shed under lowFx, and neither is floatDmg below. Both used to bail on
 * it, and that was only ever invisible because nothing set the flag on a
 * desktop -- the Phaser build's frame governor sets it for real, and the first
 * thing it did was take every damage number off the screen on exactly the
 * device that needed them most.
 *
 * A number is information. The whole of the ranked-floater hierarchy exists so
 * a player can tell a scratch from a heavy landing at a glance, and a phone
 * struggling for frames is not a reason to stop telling them what their hits
 * did. It costs nothing worth having either: floaters are capped at 22, merged
 * on the way in, and pooled Text objects in the Phaser build. The mood goes
 * under lowFx; the readout stays.
 */
function floatWord(x, y, word, kind) {
  for (let i = 0; i < floaters.length; i++) {
    const f = floaters[i];
    // One at a time off one body: a tethered swing every frame would stack
    // eight of the same word up the screen.
    if (f.word === word && Math.abs(f.x0 - x) < 40 && Math.abs(f.y0 - y) < 40) {
      f.life = FLOAT_LIFE; f.pop = 1; return;
    }
  }
  floaters.push({ x0: x, y0: y, x, y, n: 0, word, kind, life: FLOAT_LIFE, pop: 1,
                  drift: rand(-14, 14), rise: rand(50, 64) });
}

function floatDmg(x, y, amount, kind) {
  const n = Math.max(1, Math.round(amount));
  // Merge into a number already climbing off the same spot.
  for (let i = 0; i < floaters.length; i++) {
    const f = floaters[i];
    if (f.kind !== kind || FLOAT_LIFE - f.life > FLOAT_MERGE) continue;
    if (Math.abs(f.x0 - x) > 26 || Math.abs(f.y0 - y) > 26) continue;
    f.n += n;
    f.life = Math.min(FLOAT_LIFE, f.life + 0.12);
    f.pop = 1;
    return;
  }
  if (floaters.length >= MAX_FLOATERS) {
    // Drop the oldest rather than the new one: the newest hit is the one the
    // player is looking for.
    let old = 0;
    for (let i = 1; i < floaters.length; i++) if (floaters[i].life < floaters[old].life) old = i;
    floaters.splice(old, 1);
  }
  floaters.push({ x0: x, y0: y, x, y, n, kind, life: FLOAT_LIFE, pop: 1,
                  drift: rand(-26, 26), rise: rand(56, 74) });
}

function updateFloaters(dt) {
  let w = 0;
  for (let i = 0; i < floaters.length; i++) {
    const f = floaters[i];
    f.life -= dt;
    if (f.life <= 0) continue;
    const t = 1 - f.life / FLOAT_LIFE;
    // Thrown up and falling back, the way a struck number reads best: fast
    // out of the body, slowing at the top.
    f.x = f.x0 + f.drift * t;
    f.y = f.y0 - f.rise * (1 - (1 - t) * (1 - t)) + 26 * t * t;
    f.pop = Math.max(0, f.pop - dt * 6);
    floaters[w++] = f;
  }
  floaters.length = w;
}

// Colour and weight by what the hit was. Soaked hits are deliberately dull and
// small -- they are meant to read as "this is not working".
// A hierarchy, not a palette. Size, colour and edge all move together, so the
// number that matters is the one the eye goes to: a heavy landing is large,
// bright and ringed; damage the target soaked is small, grey and edgeless and
// stays out of the way of the reading.
const FLOAT_STYLE = {
  hit:    { c: '#f2e6c4', px: 15, rim: 'rgba(6,4,3,.85)',    w: 3, pop: 0.22 },
  heavy:  { c: '#ffe07a', px: 24, rim: 'rgba(255,214,120,.9)', w: 4.5, pop: 0.5, glow: 14 },
  soaked: { c: '#7c7566', px: 11, rim: 'rgba(6,4,3,.4)',    w: 2, pop: 0.06 },
  taken:  { c: '#e0563f', px: 19, rim: 'rgba(6,4,3,.9)',     w: 3.5, pop: 0.34 },
  // Not a number: a blow that does nothing has no number to show, and showing
  // a nought or a one for it says the wrong thing twice over.
  tether: { c: '#e8c060', px: 13, rim: 'rgba(6,4,3,.75)',   w: 2.5, pop: 0.1 },
  bleed:  { c: '#a8242a', px: 14, rim: 'rgba(6,4,3,.8)',     w: 2.5, pop: 0.12 },
  coin:   { c: '#e8c060', px: 17, rim: 'rgba(6,4,3,.85)',    w: 3, pop: 0.22 },
  heal:   { c: '#8fe07a', px: 20, rim: 'rgba(6,20,4,.85)',   w: 3.5, pop: 0.4 }
};

/* ---------------------------------------------------------------------------
   7. INPUT — floating virtual joystick (+ keyboard on desktop)
   Pointer events unify mouse and touch. The stick locks to one pointer id, so
   a second finger (or a tap on the DOM HUD, which sits above the canvas and
   swallows its own events) can never yank movement around.
   ------------------------------------------------------------------------ */

const STICK_MAX  = 64;   // px from origin for full throttle
const STICK_DEAD = 0.15; // fraction of MAX ignored, then remapped smoothly

const stick = { active: false, id: null, ox: 0, oy: 0, x: 0, y: 0,
                dx: 0, dy: 0, mag: 0, fade: 0 };
const keys = new Set();

function stickStart(id, x, y) {
  if (stick.active) return;              // one pointer owns movement
  stick.active = true; stick.id = id;
  stick.ox = stick.x = x; stick.oy = stick.y = y;
  stick.dx = stick.dy = stick.mag = 0;
  stick.fade = 1;
}

function stickMove(x, y) {
  stick.x = x; stick.y = y;
  let dx = x - stick.ox, dy = y - stick.oy;
  const d = Math.hypot(dx, dy);
  if (d < 0.0001) { stick.mag = 0; return; }
  const ux = dx / d, uy = dy / d;
  // Drag past the ring and the origin follows, so the stick never feels capped.
  if (d > STICK_MAX) {
    stick.ox += ux * (d - STICK_MAX);
    stick.oy += uy * (d - STICK_MAX);
  }
  const norm = Math.min(d, STICK_MAX) / STICK_MAX;
  stick.dx = ux; stick.dy = uy;
  stick.mag = norm <= STICK_DEAD ? 0 : (norm - STICK_DEAD) / (1 - STICK_DEAD);
  if (stick.mag > 0.12) breakChannel('move');
}

function stickEnd() {
  stick.active = false; stick.id = null; stick.mag = 0;
}

function moveVector() {
  if (stick.active && stick.mag > 0) {
    return { x: stick.dx * stick.mag, y: stick.dy * stick.mag };
  }
  let kx = 0, ky = 0;
  if (keys.has('a') || keys.has('arrowleft'))  kx -= 1;
  if (keys.has('d') || keys.has('arrowright')) kx += 1;
  if (keys.has('w') || keys.has('arrowup'))    ky -= 1;
  if (keys.has('s') || keys.has('arrowdown'))  ky += 1;
  if (kx || ky) {
    const d = Math.hypot(kx, ky);
    return { x: kx / d, y: ky / d };
  }
  return { x: 0, y: 0 };
}

/* ---------------------------------------------------------------------------
   8. SIMULATION
   ------------------------------------------------------------------------ */

const view = { w: 0, h: 0, dpr: 1, safeT: 0, safeR: 0 };
const cam  = { x: 0, y: 0, shake: 0 };

function shake(amount) { cam.shake = Math.min(16, cam.shake + amount); }

function updateCamera(dt) {
  const tx = clamp(player.x - view.w / 2, 0, Math.max(0, WORLD.w - view.w));
  const ty = clamp(player.y - view.h / 2, 0, Math.max(0, WORLD.h - view.h));
  const k = Math.min(1, dt * 9);
  cam.x = view.w >= WORLD.w ? (WORLD.w - view.w) / 2 : lerp(cam.x, tx, k);
  cam.y = view.h >= WORLD.h ? (WORLD.h - view.h) / 2 : lerp(cam.y, ty, k);
  cam.shake *= Math.pow(0.0015, dt);
  if (cam.shake < 0.05) cam.shake = 0;
}

function hurtPlayer(e) { hurtPlayerBy(e.dmg, e.x, e.y); }

// Damage from something that is not a body -- a slam, a hazard -- comes
// through here. fx/fy is only where the spray comes from.
function hurtPlayerBy(dmg, fx, fy) {
  if (player.invuln > 0) return;
  // Ward is flat damage reduction off gear, capped well short of immunity.
  // Mitigation is the kit's own, on top of it and for a few seconds only.
  const mit = (player.mitigate || 0) > 0 ? 0.5 : 0;
  const taken = dmg * (1 - (player.ward || 0)) * (1 - mit);
  breakChannel('hurt');
  player.hp -= taken;
  player.invuln = player.iframe;
  player.hitFlash = 0.3;
  // Bound to the share of your life it took, not to a constant: a scratch and
  // a blow that nearly ends the run should not shake the same.
  shake(4 + 22 * clamp(taken / Math.max(1, player.maxHp), 0, 1));
  hitFlashUI();
  const ox = fx === undefined ? player.x : fx;
  const oy = fy === undefined ? player.y : fy;
  burst(player.x + (ox - player.x) * 0.5, player.y + (oy - player.y) * 0.5,
        PAL.blood, 10, 180);
  floatDmg(player.x, player.y - player.r * 1.2, taken, 'taken');
  if (player.hp <= 0) { player.hp = 0; endRun(false); }
}

function damageEnemy(e, dmg) {
  if (e.hp <= 0) return;
  if (!e.awake) wakeEnemy(e);          // struck from the dark: everyone hears
  // He is held up by his escort. Hitting him through it is not forbidden, just
  // close to pointless -- so the read is "kill the crimson ones" rather than a
  // rule the game refuses to let you break.
  let soaked = false;
  // Euphoric Tether. While one of his Lieutenants stands he takes nothing at
  // all -- this used to be a fourteen-per-cent soak so the rule was one you
  // could break rather than one the game refused, but a soak reads as a bad
  // health bar and the player keeps hitting the wrong thing. Immune says it
  // once. The bar says HELD, the pips say how many, and the floater says
  // TETHERED on the swing itself.
  if (e.kind === 'deceiver' && escortAlive()) {
    burst(e.x, e.y, '#e8c060', 3, 120);
    floatWord(e.x, e.y - e.r * 0.9, 'TETHERED', 'tether');
    return;
  }
  // A braced anchor eats most of it. It cannot move or swing while it does,
  // and it has to drop the guard on a rhythm, so the answer is to back off and
  // come back rather than to keep hitting the shield.
  if (e.braced) {
    dmg *= BRACE_SOAK;
    soaked = true;
    burst(e.x, e.y, '#ffe6a8', 2, 130);
  }
  e.hp -= dmg;
  e.hitFlash = 0.12;
  // A heavy enough blow shatters a body that is closing. A scratch does not:
  // the point is that you have to commit to stopping it, not graze it once.
  if (e.calcify > 0 && dmg >= e.maxHp * CALCIFY_BREAK) breakCalcify(e, true);
  // Broken across the room or broken at your feet, it goes off either way --
  // and that is the whole lesson, so it must hold however it died.
  if (e.hp <= 0 && e.kind === 'husk' && !e.burst) burstHusk(e);
  // "Heavy" is measured against the body being hit, not against a fixed
  // number: forty off a thrall is a killing blow and forty off the avatar is
  // a scratch, and the number should read like whichever it was.
  floatDmg(e.x, e.y - e.r * 0.9, dmg,
           soaked ? 'soaked' : dmg > e.maxHp * 0.34 ? 'heavy' : 'hit');
  // Every wound on an escort pushes the crystal. Killing them is how you get
  // to him, and it is also how the clock runs down -- which is the whole
  // shape of the fight in one line.
  if (e.kind === 'lieutenant' && run && run.boss && run.boss.hp > 0) {
    dawnAdd(DAWN_PER_LIEUT * clamp(dmg / Math.max(1, e.maxHp), 0, 1),
            'They bled it into him.');
  }
  if (e.hp <= 0) {
    if (e.kind === 'lieutenant' && run && run.boss && run.boss.hp > 0 &&
        !escortAlive() && !((run.breath || 0) > 0) && !run.dawnFired) {
      beginBreath(run.boss);
    }
    if (e.kind === 'mirage') {
      burst(e.x, e.y, '#e8c060', 10, 150);
      return;                                   // a lie, not a body
    }
    if (e.kind === 'deceiver') {
      // An invader is not the avatar the delve is waiting on. Killing him must
      // not open the ley-gate, or the quota stops meaning anything the moment
      // one turns up.
      if (e.invader) {
        run.invader = null;
        run.invadeKills = (run.invadeKills || 0) + 1;
        run.banner = 3.2;
        run.bannerText = 'The uninvited is broken';
        run.bannerNote = 'He was carrying something that was never his.';
        shake(12);
      } else {
        run.bossDown = true;
        run.boss = null;
        run.banner = 3.4;
        run.bannerText = 'The ley-gate answers';
        run.bannerNote = 'The false salvation is broken. Hold the circle.';
        shake(14);
      }
      for (let i = 0; i < enemies.length; i++) {
        if (enemies[i].kind === 'mirage') enemies[i].hp = 0;
      }
    }
    run.kills++;
    // The delve keeps its dead for a moment. An elite standing over one will
    // stop and take the slag out of it, which is the only time a champion is
    // holding still and not looking at you.
    noteFallen(e.x, e.y);
    // Ravenous: whatever dies near him goes into him. Fighting through the
    // horde at his feet is actively worse than pulling him off it.
    const bs = run && run.boss;
    if (bs && bs.hp > 0 && bs.ravenous && e !== bs &&
        dist2(e.x, e.y, bs.x, bs.y) < 260 * 260) {
      const fed = Math.min(bs.maxHp * 0.03, bs.maxHp - bs.hp);
      if (fed > 0) {
        bs.hp += fed;
        ring(bs.x, bs.y, '#c2352a', 6, 34, 0.35);
      }
    }
    dropLoot(e);
    burst(e.x, e.y, e.color, e.r > 18 ? 14 : 7, 190);
    if (e.r > 18) shake(3);
  } else {
    burst(e.x, e.y, '#e6d8bc', 2, 90);
  }
}

// Slag is experience. It is banked on the hero at the end of the delve rather
// than spent on a card mid-fight, so the run is never interrupted to choose.
function collectTech(v) {
  run.tech += v;
}

function updatePlayer(dt) {
  // The beat. It locks the ability bar and nothing else -- movement and the
  // blade are never taken away, because a game played with one thumb cannot
  // afford to stop answering the stick.
  if (player.gcd > 0) player.gcd = Math.max(0, player.gcd - dt);
  updateAbilities(dt);

  const mv = moveVector();
  const px0 = player.x, py0 = player.y;
  if (mv.x !== 0 || mv.y !== 0) {
    const target = Math.atan2(mv.y, mv.x);
    player.angle += angleDelta(player.angle, target) * Math.min(1, dt * 15);
    if (Math.abs(mv.x) > 0.12) player.face = mv.x < 0 ? -1 : 1;
    // Rooted, and channelling, both mean the boots stay where they are. The
    // stick still reads -- it is what lapses the channel -- but it moves
    // nothing, which is the trade Unyielding Mass is asking you to make.
    if (!(player.rooted > 0) && !player.channel)
      moveEntity(player, mv.x * player.speed * dt, mv.y * player.speed * dt);
  }
  // The gait is driven by ground actually covered, not by a clock, so the
  // feet cannot skate: walk into a wall and the stride stops with him.
  advanceGait(player, px0, py0, dt);
  player.invuln  = Math.max(0, player.invuln - dt);
  player.hitFlash = Math.max(0, player.hitFlash - dt);
  // The blade does not teleport back to the guard when the strike ends: it is
  // carried back over a short recovery, which is also the beat that makes the
  // next swing read as a separate blow rather than a continuation.
  if (player.swing > 0) {
    player.swing -= dt;
    if (player.swing <= 0) { player.swing = 0; player.recov = RECOVER_TIME; }
  } else if (player.recov > 0) {
    player.recov = Math.max(0, player.recov - dt);
  }
  if (player.regen > 0) player.hp = Math.min(player.maxHp, player.hp + player.regen * dt);

  player.fireTimer -= dt;
  if (player.fireTimer <= 0) {
    // No target in range: hold the timer at zero so the next one that walks in
    // is engaged immediately rather than after a stale cooldown.
    player.fireTimer = fire() ? player.fireDelay : 0;
  }
}

/* Swarm navigation.
   Steering straight at the player works in an open arena and fails in a maze:
   anything behind rock walks into it and stops. One breadth-first sweep of the
   cave grid from the player's cell gives every open cell its step-distance to
   the player, and the swarm simply walks downhill. It costs one pass over
   2500 cells, and only when the player crosses into a new cell -- far cheaper
   than per-enemy pathfinding, and it scales to the whole horde for free.     */

let flowDist = null, flowQueue = null, flowFrom = -1;

function rebuildFlow() {
  if (!grid) return;
  if (!flowDist) { flowDist = new Int32Array(GW * GH); flowQueue = new Int32Array(GW * GH); }
  const pcx = clamp(Math.floor(player.x / CELL_W), 0, GW - 1);
  const pcy = clamp(Math.floor(player.y / CELL_W), 0, GH - 1);
  let start = gi(pcx, pcy);

  // If the player is somehow inside rock, seed from the nearest open cell so
  // the field is never empty.
  if (grid[start] === SOLID) {
    let best = -1, bestD = Infinity;
    for (let i = 0; i < openCells.length; i++) {
      const d = dist2(openCells[i].x, openCells[i].y, player.x, player.y);
      if (d < bestD) { bestD = d; best = i; }
    }
    if (best < 0) return;
    start = gi(Math.floor(openCells[best].x / CELL_W), Math.floor(openCells[best].y / CELL_W));
  }

  flowDist.fill(-1);
  let head = 0, tail = 0;
  flowQueue[tail++] = start;
  flowDist[start] = 0;
  while (head < tail) {
    const k = flowQueue[head++];
    const cx = k % GW, cy = (k / GW) | 0;
    const nd = flowDist[k] + 1;
    for (let i = 0; i < 4; i++) {
      const nx = cx + (i === 0 ? 1 : i === 1 ? -1 : 0);
      const ny = cy + (i === 2 ? 1 : i === 3 ? -1 : 0);
      if (nx < 0 || ny < 0 || nx >= GW || ny >= GH) continue;
      const nk = gi(nx, ny);
      if (grid[nk] === SOLID || flowDist[nk] >= 0) continue;
      flowDist[nk] = nd;
      flowQueue[tail++] = nk;
    }
  }
  flowFrom = start;
}

// Direction downhill on the field, or null where there is nothing to follow.
function flowDir(e, out) {
  if (!flowDist) return false;
  const cx = clamp(Math.floor(e.x / CELL_W), 0, GW - 1);
  const cy = clamp(Math.floor(e.y / CELL_W), 0, GH - 1);
  const here = flowDist[gi(cx, cy)];
  if (here < 0) return false;
  let bestD = here, bx = -1, by = -1;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dy) continue;
      const nx = cx + dx, ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= GW || ny >= GH) continue;
      // Refuse diagonals that cut a rock corner.
      if (dx && dy && (cellAt(cx + dx, cy) === SOLID || cellAt(cx, cy + dy) === SOLID)) continue;
      const nd = flowDist[gi(nx, ny)];
      if (nd < 0 || nd >= bestD) continue;
      bestD = nd; bx = nx; by = ny;
    }
  }
  if (bx < 0) return false;
  const tx = bx * CELL_W + CELL_W / 2, ty = by * CELL_W + CELL_W / 2;
  const vx = tx - e.x, vy = ty - e.y;
  const m = Math.hypot(vx, vy) || 1;
  out.x = vx / m; out.y = vy / m;
  return true;
}

const _flow = { x: 0, y: 0 };

function updateEnemies(dt) {
  const pk = gi(clamp(Math.floor(player.x / CELL_W), 0, GW - 1),
                clamp(Math.floor(player.y / CELL_W), 0, GH - 1));
  if (pk !== flowFrom) rebuildFlow();

  enemyGrid.clear();
  for (let i = 0; i < enemies.length; i++) {
    const e = enemies[i];
    enemyGrid.insert(e, e.x, e.y);
  }

  // How many are on their feet, counted BEFORE anything is stepped. Tallying
  // this as the pass runs looks equivalent and is not: a body would then be
  // weighed against the count of bodies earlier in the array, so on the first
  // frame the counter starts at zero and every body in turn waves itself
  // through a ceiling that has not caught up yet. Measured against a crowd of
  // 140 inside their own notice, that let all 140 rise against a cap of 54.
  let awake = 0;
  for (let i = 0; i < enemies.length; i++) {
    const e = enemies[i];
    if (e.hp > 0 && e.awake) awake++;
  }
  run.awake = awake;

  for (let i = 0; i < enemies.length; i++) {
    const e = enemies[i];
    if (e.hp <= 0) continue;
    e.hitFlash = Math.max(0, e.hitFlash - dt);
    if (e.mended > 0) e.mended = Math.max(0, e.mended - dt);

    // Closing. A body doing this is not fighting, not moving and not being
    // steered by anything below -- it is a four-second window and nothing else.
    if (e.calcify > 0) { updateCalcify(e, dt); continue; }

    // Heavy bodies break off when they are nearly down. Once each: a champion
    // that can keep retreating is a champion that never dies.
    if (e.awake && !e.calcified && (e.mass || 1) >= 2.5 && e.hp > 0 &&
        e.hp < e.maxHp * CALCIFY_AT && e.kind !== 'deceiver' && !e.invader) {
      beginCalcify(e);
      continue;
    }

    // An elite over a fresh corpse stops and takes the slag out of it.
    if (tryConsume(e, dt)) continue;

    // The escort has two jobs that are not fighting you, and both of them
    // stop it dead: winding the cleave, and pouring into its master. Neither
    // is steered by anything below.
    if (e.kind === 'lieutenant' && lieutenantBusy(e, dt)) continue;

    // Both are refreshed rather than accumulated -- a Null-Zone re-applies its
    // slow every frame you stand in it, and a second interrupt on a silenced
    // body should not stack into a minute of quiet.
    if (e.slowed > 0) e.slowed = Math.max(0, e.slowed - dt);
    if (e.silenced > 0) e.silenced = Math.max(0, e.silenced - dt);
    // Metaphysical Vulnerability. Ten seconds, and the Guillotine reads it.
    if (e.vuln > 0) e.vuln = Math.max(0, e.vuln - dt);
    e.wob += dt * 7;

    if (e.kind === 'mirage') {
      e.fade -= dt;
      if (e.fade <= 0) { e.hp = 0; continue; }
    } else if (e.kind === 'deceiver') {
      // Nullified. Ten seconds on the floor with the guard down, which is the
      // only stretch of this fight where his health bar is the thing moving.
      if ((e.stun || 0) > 0) {
        e.stun -= dt;
        e.braced = false;
        if (!lowFx && Math.random() < 0.4)
          spark(e.x + rand(-40, 40), e.y + rand(-40, 40), e.x, e.y, '#b07cff');
        continue;
      }
      // Committed to the breath: he goes to the middle and stays there.
      if ((run.breath || 0) > 0) { updateBreath(e, dt); continue; }

      // Inverted Ley-Rupture: the ground under whoever is standing on it.
      e.rupture = (e.rupture || 0) - dt;
      if (e.rupture <= 0) {
        e.rupture = RUPTURE_CD;
        beginRupture(player.x, player.y);
      }

      // He does not walk the corridors -- he is an avatar, and a body this
      // wide wedges on corners anyway. He steps out of one place and into
      // another near you, which is both the fix and the character.
      // Unblinking sets this to effectively never, and walks instead.
      e.blink -= dt;
      if (e.blink <= 0) {
        e.blink = 4.4;
        for (let k = 0; k < 26; k++) {
          const a = Math.random() * TAU, dd = 140 + Math.random() * 90;
          const nx = clamp(player.x + Math.cos(a) * dd, 50, WORLD.w - 50);
          const ny = clamp(player.y + Math.sin(a) * dd, 50, WORLD.h - 50);
          if (pointInWalls(nx, ny, e.r + 6)) continue;
          burst(e.x, e.y, '#e8c060', 16, 210);
          // Riftborn: the hole he stepped through does not close.
          if (e.riftborn) addHazard(e.x, e.y, 74, e.dmg * 0.85, 7.5, '#b07cff');
          e.x = nx; e.y = ny;
          burst(e.x, e.y, '#e8c060', 16, 210);
          break;
        }
      }
      // Unbroken: he gathers, and for two seconds nothing touches him. The
      // guard is drawn, so this is a window to reposition rather than a
      // stretch of wasted swings.
      if (e.guardCd) {
        e.guardT -= dt;
        if (e.guardT <= 0) {
          e.braced = !e.braced;
          e.guardT = e.braced ? 2.0 : e.guardCd;
          if (e.braced) ring(e.x, e.y, '#e8c060', 10, 90, 0.5);
        }
      }
      e.summon -= dt;
      if (e.summon <= 0) {
        e.summon = 8.5;
        const batch = 2 + ((run.time / 90) | 0);
        for (let i = 0; i < batch; i++) spawnEnemy(run.time);
      }
      e.split -= dt;
      if (e.split <= 0) {
        e.split = e.mutators && e.mutators.indexOf('wreathed') >= 0 ? 4.5 : 9.5;
        const want = e.mirages || 3;
        let live = 0;
        for (let i = 0; i < enemies.length; i++) if (enemies[i].kind === 'mirage') live++;
        if (live < want) spawnMirages(e, want - live);
      }
    }

    const dx = player.x - e.x, dy = player.y - e.y;
    const d = Math.hypot(dx, dy) || 1;

    // --- dormant until something rouses it --------------------------------
    // A body waits where the generator put it. It wakes when you come inside
    // its notice, when you hit it, or when a neighbour that already woke
    // passes the alarm along. Dormant bodies skip the seek and the separation
    // pass entirely, which is most of the per-enemy cost.
    if (!e.awake) {
      if (e.alert > 0) {
        e.alert -= dt;
        if (e.alert <= 0 && awake < HORDE_LIVE) wakeEnemy(e);
      } else if (noticeDist(e, d) < e.aggro && awake < HORDE_LIVE) {
        // The ceiling binds here too. A body over the cap stays down until
        // something ahead of it falls -- but being struck always wakes it
        // (see damageEnemy), so nothing on the map can become unkillable and
        // the delve's slag is never locked away behind the cap.
        wakeEnemy(e);
      }
      if (!e.awake) {
        e.drowse += dt * 1.6;
        continue;
      }
      // Woken during this pass: the ceiling has to feel it now, not next
      // frame, or a whole crowd rises through a cap that only ever sees the
      // frame before.
      awake++; run.awake = awake;
    }

    e.angle = Math.atan2(dy, dx);
    if (Math.abs(dx) > 3) e.face = dx < 0 ? -1 : 1;

    // A slam is thrown at where you are now, and lands where it was thrown --
    // the whole attack is the distance between those two, so it is aimed at
    // range rather than in contact, where there would be nowhere to go.
    if (e.slam) {
      e.slamCd -= dt;
      const reach = SLAM_R * (e.slamR || 1);
      if (e.slamCd <= 0 && d < reach * 2.2 && d > e.r + player.r + 10) {
        // Three Lieutenants throwing on their own clocks carpet the floor and
        // the telegraph stops meaning anything. One marked circle at a time in
        // any given place: the others wait a beat and aim somewhere you have
        // moved to.
        let clash = false;
        for (let k = 0; k < slams.length; k++) {
          const o = slams[k];
          if (o.struck) continue;
          if (dist2(o.x, o.y, player.x, player.y) < o.r * o.r) { clash = true; break; }
        }
        if (!clash) {
          e.slamCd = SLAM_CD * rand(0.85, 1.2);
          slams.push({ x: player.x, y: player.y, r: SLAM_R * (e.slamR || 1),
                       wind: SLAM_WIND, t: 0, dmg: e.dmg * 1.3, struck: false,
                       fracture: !!e.fracture });
        } else {
          e.slamCd = 0.5;
        }
      }
    }

    // --- separation (flocking): repulsion from crowded neighbours ---------
    let rx = 0, ry = 0;
    enemyGrid.query(e.x, e.y, e.r + 26, _near);
    for (let k = 0; k < _near.length; k++) {
      const o = _near[k];
      if (o === e || o.hp <= 0) continue;
      const ox = e.x - o.x, oy = e.y - o.y;
      const want = e.r + o.r + 2;
      const od2 = ox * ox + oy * oy;
      if (od2 >= want * want) continue;
      const od = Math.sqrt(od2) || 0.01;
      const push = ((want - od) / want) * (o.mass / e.mass);
      rx += (ox / od) * push;
      ry += (oy / od) * push;
      // And the shove goes both ways. Repelling only the body being stepped
      // makes a crowd that slides past itself; pushing the neighbour too makes
      // it a crowd that has to be got through. The heavier one moves less,
      // which is what mass is for -- an anchor at its post barely stirs.
      if (o.awake && !(o.calcify > 0) && !o.braced) {
        const back = ((want - od) / want) * (e.mass / Math.max(0.5, o.mass)) * 0.5;
        moveEntity(o, -(ox / od) * back * o.speed * dt, -(oy / od) * back * o.speed * dt);
      }
    }
    // Cap the repulsion so a dense pack shoves rather than launches.
    const rl = Math.hypot(rx, ry);
    if (rl > 1.7) { rx = rx / rl * 1.7; ry = ry / rl * 1.7; }

    // --- role ------------------------------------------------------------
    // An anchor guards ground rather than chasing. It takes the most penned-in
    // cell it can find near where it woke, and steps off that post only as far
    // as ANCHOR_GUARD -- so it holds a corridor and you either fight it there
    // or go the long way, which is the whole point of a maze.
    let leash = false;
    if (e.role === 'anchor') {
      if (!e.posted) takePost(e);
      e.guard -= dt;
      if (e.guard <= 0) {
        e.braced = !e.braced;
        e.guard = e.braced ? BRACE_UP : BRACE_DOWN;
      }
      const pd = dist2(player.x, player.y, e.postX, e.postY);
      leash = pd > ANCHOR_GUARD * ANCHOR_GUARD;
    }

    // A husk commits once it is close enough that walking out is a decision
    // rather than a formality, then it is a lit fuse and nothing else.
    let planted = false;
    if (e.role === 'burst') {
      if (e.fuse > 0) {
        e.fuse -= dt;
        if (e.fuse <= 0) {
          e.hp = 0; e.burst = true;
          burst(e.x, e.y, e.color, 12, 150);
          continue;
        }
        planted = true;
      } else if (d < HUSK_NEAR) {
        e.fuse = HUSK_FUSE;
        armHusk(e, HUSK_FUSE);
        ring(e.x, e.y, e.color, e.r, HUSK_R, HUSK_FUSE);
        planted = true;
      }
    }

    // A cantor holds its distance and throws. Giving ground when you close is
    // the whole of its defence, and it will not throw through rock -- so it
    // walks to find a line, and you break the line to stop it.
    let shade = 0;    // -1 give ground, 1 close in, 2 planted to cast
    if (e.role === 'shade') {
      // Silenced: the ley-lines are snapped and nothing can be wound.
      const clear = clearShot(e.x, e.y, player.x, player.y) && !((e.silenced || 0) > 0);
      if (e.casting > 0) {
        e.casting -= dt;
        if (e.casting <= 0) {
          if (clear) fireBolt(e);
          e.cast = e.cd * rand(0.8, 1.35);
        }
        shade = 2;
      } else {
        e.cast -= dt;
        if (e.cast <= 0 && clear && d < SHADE_WANT * 1.4 && d > SHADE_NEAR * 0.5) {
          e.casting = BOLT_WIND;
          shade = 2;
        } else if (d < SHADE_NEAR) shade = -1;
        else if (d > SHADE_WANT || !clear) shade = 1;
        else shade = 2;
      }
    }

    // A flayer is not in the fight; it visits it. It holds off in the dark
    // until its own clock lets it go, crosses the ground in one run, opens
    // you and turns -- and it will not come again until it has been away.
    // The run has a fixed length rather than ending on contact, so it goes
    // past you and out the other side instead of settling into melee.
    let stalk = 0;    // 1 running in, -1 pulling back
    if (e.role === 'stalk') {
      if (e.run > 0) {
        e.run -= dt;
        stalk = 1;
        if (!e.struck && d < e.r + player.r + 8) {
          e.struck = true;
          hurtPlayer(e);
          openWound(BLEED_DPS, BLEED_TIME);
          burst(player.x, player.y, PAL.blood, 12, 200);
        }
        if (e.run <= 0) { e.lurk = STALK_BACK * rand(0.8, 1.35); e.struck = false; }
      } else {
        e.lurk -= dt;
        // It will not start a run it cannot finish: no line, no run.
        if (e.lurk <= 0 && d < STALK_HOLD * 1.5 &&
            clearShot(e.x, e.y, player.x, player.y)) {
          e.run = STALK_RUN;
          stalk = 1;
        } else {
          stalk = d < STALK_HOLD * 0.7 ? -1 : d > STALK_HOLD * 1.25 ? 1 : 0;
        }
      }
    }

    // A shaman holds the back and does one of two things: it puts fire on the
    // ground you are standing on, or it takes the light. Neither can be
    // dodged in flight the way a bolt can -- the fire is dodged by moving off
    // it and the gloom is stopped only by reaching him, which is the point.
    let chant = 0;    // -1 give ground, 1 close in, 2 planted to cast
    if (e.role === 'chant') {
      // Silenced: the ley-lines are snapped and nothing can be wound.
      const clear = clearShot(e.x, e.y, player.x, player.y) && !((e.silenced || 0) > 0);
      if (e.chanting > 0) {
        e.chanting -= dt;
        if (e.chanting <= 0) {
          if (clear) {
            if (e.spell === 0) {
              addHazard(player.x, player.y, EMBER_R, EMBER_DPS, EMBER_LIFE, '#ff7a2c');
              ring(player.x, player.y, '#ff7a2c', EMBER_R * 0.3, EMBER_R, 0.4);
            } else if (e.spell === 1) {
              castGloom();
            } else {
              // The third: it plants rather than throws. Put at its own feet,
              // in the middle of the horde it is there to mend, so reaching it
              // means going through them.
              plantTotem(e.x, e.y);
            }
          }
          e.chant = e.cd * rand(0.85, 1.3);
          // Fire, then the dark, then a totem, and round again -- so none of
          // the three is ever a surprise twice running.
          e.spell = (e.spell + 1) % 3;
        }
        chant = 2;
      } else {
        e.chant -= dt;
        if (e.chant <= 0 && clear && d < CHANT_WANT * 1.3) { e.chanting = CHANT_WIND; chant = 2; }
        else if (d < CHANT_WANT * 0.55) chant = -1;
        else if (d > CHANT_WANT || !clear) chant = 1;
        else chant = 2;
      }
    }

    // --- seek / melee -----------------------------------------------------
    let sx = 0, sy = 0;
    const touch = e.r + player.r + 3;
    // Braced, it is a wall: it does not advance and it does not swing.
    if (e.braced) {
      const bx0 = e.x, by0 = e.y;
      moveEntity(e, rx * 0.4 * e.speed * dt, ry * 0.4 * e.speed * dt);
      advanceGait(e, bx0, by0, dt);
      continue;
    }
    if (planted) {
      // Swelling. It is going off wherever it is standing.
      sx = 0; sy = 0;
    } else if (stalk === 1) {
      sx = dx / d; sy = dy / d;                 // straight at you, through you
    } else if (stalk === -1 || chant === -1) {
      sx = -dx / d; sy = -dy / d;               // straight back down the line
    } else if (chant === 2) {
      sx = 0; sy = 0;
    } else if (shade === -1) {
      // Straight back down the line it is being pressed along. Following the
      // flow field away from the player walks it into the nearest wall, and a
      // cornered cantor that cannot retreat is a cantor that stands and dies,
      // which is the fight it is meant to avoid.
      sx = -dx / d; sy = -dy / d;
    } else if (shade === 2) {
      sx = 0; sy = 0;
    } else if (stalk === 0 && e.role === 'stalk') {
      sx = 0; sy = 0;                           // holding, out in the dark
    } else if (leash) {
      // Back to its post, and stand there once it arrives.
      const px = e.postX - e.x, py = e.postY - e.y;
      const pm = Math.hypot(px, py);
      if (pm > 14) { sx = px / pm; sy = py / pm; }
    } else if (d > touch) {
      // Close in, head straight at the target so the swarm keeps its shape;
      // further out, follow the field so rock never traps anything.
      if (d < 78 || !flowDir(e, _flow)) {
        sx = dx / d; sy = dy / d;
      } else {
        sx = _flow.x * 0.82 + (dx / d) * 0.18;
        sy = _flow.y * 0.82 + (dy / d) * 0.18;
        const m = Math.hypot(sx, sy) || 1;
        sx /= m; sy /= m;
      }
      // A flanker picks a mark off the player's shoulder and runs at that
      // instead, then commits once it is close. The mark is latched when it
      // first has room to use one: recomputed every frame it recedes as the
      // body moves and the flanker just orbits, which is what a continuous
      // tangent bias does and why that version never closed at all.
      //
      // Only on a clear line: in a corridor there is nothing to go round, and
      // running at a mark through rock wedges it against a wall for the whole
      // approach.
      if (e.role === 'flank') {
        if (e.markX !== 0) {
          // Run the mark down. Crucially this is checked before the range
          // test: a straight line from out wide to a mark off the shoulder
          // passes nearer the player than the mark itself, so a version that
          // dropped the mark the moment range closed abandoned the manoeuvre
          // a third of the way through it and swung twenty degrees instead of
          // a hundred.
          e.markT -= dt;
          const vx = e.markX - e.x, vy = e.markY - e.y;
          const m = Math.hypot(vx, vy);
          if (m < 34 || e.markT <= 0) {
            e.markX = 0; e.markY = 0;
            // Press for a beat before manoeuvring again. Without this it
            // latches a fresh mark the frame it spends one and spirals: a
            // sixth of them never reached the player inside eight seconds.
            e.markCd = FLANK_COMMIT;
          } else { sx = vx / m; sy = vy / m; }
        } else if (e.markCd > 0) {
          e.markCd -= dt;
        } else if (d > FLANK_OPEN && clearShot(e.x, e.y, player.x, player.y)) {
          const bear = Math.atan2(e.y - player.y, e.x - player.x);
          for (let k = 0; k < 3; k++) {
            const want = bear + e.spin * FLANK_SWING * (1 - k * 0.33);
            const mx = player.x + Math.cos(want) * FLANK_OPEN;
            const my = player.y + Math.sin(want) * FLANK_OPEN;
            if (pointInWalls(mx, my, e.r + 2)) continue;
            e.markX = mx; e.markY = my; e.markT = 4;
            sx = (mx - e.x); sy = (my - e.y);
            const mm = Math.hypot(sx, sy) || 1;
            sx /= mm; sy /= mm;
            break;
          }
        }
      }
    } else {
      e.atk -= dt;
      if (e.atk <= 0) { e.atk = e.cd; hurtPlayer(e); }
    }

    const mx0 = e.x, my0 = e.y;
    // Slowed by a Null-Zone. The pool does not kill anything; it decides how
    // fast the ground in front of you can be crossed.
    const spd = e.speed * ((e.slowed || 0) > 0 ? 0.3 : 1);
    moveEntity(e, (sx + rx * 0.8) * spd * dt, (sy + ry * 0.8) * spd * dt);
    advanceGait(e, mx0, my0, dt);
  }
  run.awake = awake;
}

// Is an enemy inside the crescent's band? The band is an arc of radius `bow`
// centred behind the crescent, so this is two cheap tests: how far off that
// radius the enemy sits, and how far around the arc it lies from dead ahead.
function inCrescent(b, e) {
  const cx = b.x - b.dx * b.bow, cy = b.y - b.dy * b.bow;
  const vx = e.x - cx, vy = e.y - cy;
  const d = Math.sqrt(vx * vx + vy * vy);
  if (d < 1) return false;
  if (Math.abs(d - b.bow) > b.band + e.r) return false;
  // Angular half-width, widened by the body's own radius at this distance.
  let da = Math.atan2(vy, vx) - b.a;
  while (da >  Math.PI) da -= TAU;
  while (da < -Math.PI) da += TAU;
  return Math.abs(da) <= b.half / b.bow + e.r / d;
}

function updateArcs(dt) {
  let w = 0;
  for (let i = 0; i < arcs.length; i++) {
    const b = arcs[i];
    if (b.delay > 0) { b.delay -= dt; arcs[w++] = b; continue; }
    b.life -= dt;
    if (b.life <= 0) continue;

    // Substepped travel: the crescent is tested along its path rather than
    // teleporting a whole frame's distance, so it cannot skip a thin wall or
    // step clean over a body between one frame and the next.
    const travel = b.speed * dt;
    const steps = Math.min(8, Math.max(1, Math.ceil(travel / 9)));
    const st = travel / steps;

    for (let s = 0; s < steps; s++) {
      b.x += b.dx * st;
      b.y += b.dy * st;
      if (b.x < 0 || b.y < 0 || b.x > WORLD.w || b.y > WORLD.h) { b.dead = true; break; }

      // Rock stops projected magic, tested on the leading centre the way the
      // old bolt was: predictable, and it keeps a wide sweep from being
      // cancelled because one horn clipped a corner.
      const hits = wallsNear(b.x, b.y, 4);
      for (let k = 0; k < hits.length; k++) {
        const wl = walls[hits[k]];
        if (b.x > wl.x - 4 && b.x < wl.x + wl.w + 4 &&
            b.y > wl.y - 4 && b.y < wl.y + wl.h + 4) {
          b.dead = true;
          burst(b.x, b.y, HEROES[run.hero].magic, 5, 140);
          break;
        }
      }
      if (b.dead) break;

      // A crescent cuts everything it sweeps through -- it is an edge, not a
      // bolt -- but only once each, so a slow arc cannot grind one body down.
      enemyGrid.query(b.x, b.y, b.bow + b.half + b.band + 30, _near);
      for (let k = 0; k < _near.length; k++) {
        const e = _near[k];
        if (e.hp <= 0 || b.hit.indexOf(e) !== -1) continue;
        if (!inCrescent(b, e)) continue;
        damageEnemy(e, b.dmg);
        b.hit.push(e);
      }
      // A totem is a thing standing on the floor and the blade cuts it like
      // anything else. Without this the only answer to one is to wait, which
      // is not an answer.
      for (let k = 0; k < totems.length; k++) {
        const tm = totems[k];
        if (b.hit.indexOf(tm) !== -1) continue;
        if (dist2(b.x, b.y, tm.x, tm.y) > (b.bow + b.half + 22) * (b.bow + b.half + 22)) continue;
        tm.hp -= b.dmg;
        floatDmg(tm.x, tm.y - 20, b.dmg, 'hit');
        burst(tm.x, tm.y, '#9dbb5a', 4, 130);
        b.hit.push(tm);
      }
      // Scenery is in the way of an edge too. Only the leading centre is
      // tested against it rather than the whole sweep: a barrel is a thing you
      // aim at by standing somewhere, and cutting one down every time a horn
      // happened to clip it would make the room disassemble itself.
      for (let k = 0; k < propGrid.length; k++) {
        const pr = propGrid[k];
        if (pr.gone || b.hit.indexOf(pr) !== -1) continue;
        const rr = pr.kind === 'pillar' ? 18 : 13;
        if (dist2(b.x, b.y, pr.x, pr.y) > rr * rr) continue;
        hurtProp(pr, b.dmg);
        b.hit.push(pr);
      }
    }
    if (!b.dead) arcs[w++] = b;
  }
  arcs.length = w;
}

function updateLoot(dt) {
  const damp = Math.pow(0.1, dt);
  let w = 0;
  for (let i = 0; i < loot.length; i++) {
    const l = loot[i];
    l.life += dt; l.spin += dt * 3.2;
    const dx = player.x - l.x, dy = player.y - l.y;
    const d = Math.hypot(dx, dy) || 1;

    if (!l.pulled && d < player.magnet) l.pulled = true;
    if (l.pulled) {
      const k = Math.min(1, dt * 7);
      l.vx = lerp(l.vx, (dx / d) * 560, k);
      l.vy = lerp(l.vy, (dy / d) * 560, k);
    } else {
      l.vx *= damp; l.vy *= damp;
    }
    l.x += l.vx * dt; l.y += l.vy * dt;

    if (d < player.r + 10) {
      collectTech(l.value);
      burst(l.x, l.y, PAL.gold, 5, 120);
      continue;
    }
    loot[w++] = l;
  }
  loot.length = w;
}

function updateParticles(dt) {
  const damp = Math.pow(0.06, dt);
  let w = 0;
  for (let i = 0; i < particles.length; i++) {
    const p = particles[i];
    p.life -= dt;
    if (p.life <= 0) continue;
    if (p.suck) {
      // Drawn in on a cubic curve, so most of the speed is in the last third
      // of the journey and the eye reads it as being pulled rather than as
      // drifting across.
      const u = 1 - p.life / p.max, k = u * u * u;
      p.x = p.sx + (p.tx - p.sx) * k;
      p.y = p.sy + (p.ty - p.sy) * k;
    } else {
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.vx *= damp; p.vy *= damp;
    }
    particles[w++] = p;
  }
  particles.length = w;
}

function updateRings(dt) {
  let w = 0;
  for (let i = 0; i < rings.length; i++) {
    const r = rings[i];
    r.life -= dt;
    if (r.life > 0) rings[w++] = r;
  }
  rings.length = w;
}

// The level names its boss; the Deceiver is the only one built so far, so a
// level with no boss simply opens the gate on quota.
// Odds a delve is invaded at all, and when. Rolled per run rather than per
// rung: a scheduled ambush is not an ambush.
function rollInvasion() {
  if (LEVEL.invade === 0) return 0;      // not while the game is still teaching
  const dep = LEVEL.depth || 0;
  const odds = (0.16 + dep * 0.24) * (DIFF.setRate || 1);
  if (Math.random() >= odds) return 0;
  return INVADE_EARLY + Math.random() * 70;
}

function spawnInvader() {
  const d = ENEMY_TYPES.deceiver;
  const dep = LEVEL.depth || 0;
  // Far enough that the arrival is a warning rather than a hit.
  let x = 0, y = 0, ok = false;
  for (let k = 0; k < 40 && !ok; k++) {
    const a = Math.random() * TAU, dd = 420 + Math.random() * 260;
    x = clamp(player.x + Math.cos(a) * dd, 60, WORLD.w - 60);
    y = clamp(player.y + Math.sin(a) * dd, 60, WORLD.h - 60);
    ok = !pointInWalls(x, y, d.r + 6);
  }
  if (!ok) return null;

  const e = newBody('deceiver', x, y, 0);
  // Lighter than the one at the gate -- he is a fight you did not plan for and
  // may not be equipped for, and the answer to him is allowed to be running.
  e.hp = e.maxHp = d.hp * (0.55 + dep * 0.7) * DIFF.threat;
  e.dmg = d.dmg * DIFF.threat;
  e.speed = d.speed * 1.15;
  e.atk = 1.2; e.wob = 0;
  e.summon = 1e9;                 // he hunts alone
  e.split = 6.5; e.blink = 2.6;
  e.slamR = 1; e.mirages = 2; e.extraGuard = 0;
  e.ravenous = false; e.riftborn = true;
  e.guardCd = 0; e.guardT = 0;
  e.invader = true;
  e.title = 'The Gilded Deceiver, Uninvited';
  e.mutators = [];
  enemies.push(e);
  run.invader = e;
  run.invadeSince = run.time;
  run.banner = 3.4;
  run.bannerText = 'Something has come for you';
  run.bannerNote = 'He was not called. Kill him, or lose him in the dark.';
  shake(9);
  return e;
}

function updateInvasion(dt) {
  const e = run.invader;
  if (!e) {
    if (run.invadeAt && run.time >= run.invadeAt && !run.gateOpen) {
      run.invadeAt = 0;
      spawnInvader();
    }
    return;
  }
  if (e.hp <= 0) { run.invader = null; return; }
  // Losing him is a win of a kind: keep clear and he stops looking.
  const far = dist2(player.x, player.y, e.x, e.y) > INVADE_GIVEUP * INVADE_GIVEUP;
  e.lost = (e.lost || 0) + (far ? dt : -dt * 2);
  if (e.lost < 0) e.lost = 0;
  if (e.lost >= INVADE_HUNT) {
    burst(e.x, e.y, '#e8c060', 22, 240);
    e.hp = 0;                       // gone, not killed: no loot, no kill count
    e.gaveUp = true;
    run.invader = null;
    run.banner = 2.6;
    run.bannerText = 'He has lost you';
    run.bannerNote = 'For now.';
  }
}

function spawnBoss() {
  if (!LEVEL.boss) { run.bossDown = true; return; }
  if (LEVEL.boss === 'deceiver') spawnDeceiver();
}

function spawnDeceiver() {
  const d = ENEMY_TYPES.deceiver;
  const scale = 1 + run.time / 220;
  const e = newBody('deceiver', portal.x, portal.y - 4, 0);
  e.hp = e.maxHp = d.hp * scale;
  e.dmg = d.dmg; e.speed = d.speed; e.atk = 1.4; e.wob = 0;
  e.summon = 4.5; e.split = 7; e.blink = 3.2;
  // Mutator defaults. Each one that is off has to be off explicitly, or a
  // mutator that only ever raises a value cannot be told from one that is
  // absent.
  e.slamR = 1; e.mirages = 3; e.extraGuard = 0;
  e.ravenous = false; e.riftborn = false;
  e.guardCd = 0; e.guardT = 0;
  const rolled = LEVEL.mutators || [];
  const epithets = [];
  for (const id of rolled) {
    const m = MUTATOR_BY_ID[id];
    if (!m) continue;
    m.apply(e);
    epithets.push(m);
  }
  e.mutators = rolled.slice();
  enemies.push(e);
  run.boss = e;
  // He does not arrive alone. The Lieutenants are the reason he is hard to
  // reach: while one of them stands he takes almost nothing, so the fight has
  // an order to it rather than being a single large health bar with a swarm
  // in front of it.
  // The escort ramps with the ladder like everything else. A flat pair of
  // three-hundred-hit-point guards halved the extraction rate on the first
  // delve, where the horde is thirty-four-hit-point thralls and the hero has
  // power four: the fight has to be learnable before it is hard.
  const dep = LEVEL.depth || 0;
  const guard = (LEVEL.guard >= 0 ? LEVEL.guard : 1 + Math.round(dep * 2)) +
                e.extraGuard;
  for (let i = 0; i < guard; i++) {
    let ok = false, x = 0, y = 0;
    for (let k = 0; k < 20 && !ok; k++) {
      const a = (i / guard) * TAU + k * 0.6 + Math.random() * 0.5;
      const dd = 96 + k * 9;
      x = clamp(e.x + Math.cos(a) * dd, 50, WORLD.w - 50);
      y = clamp(e.y + Math.sin(a) * dd, 50, WORLD.h - 50);
      ok = !pointInWalls(x, y, ENEMY_TYPES.lieutenant.r + 3);
    }
    if (!ok) continue;
    const L = newBody('lieutenant', x, y, run.time);
    L.hp = L.maxHp = L.maxHp * (0.5 + dep * 1.3);
    // Their own clocks, spread out. Left undefined they all read as due on
    // the first frame, and the whole escort walked off to pour together --
    // forty-eight points on the crystal in ten seconds, against nobody.
    L.siphon = SIPHON_CD * (0.55 + i * 0.5);
    enemies.push(L);
  }
  // The name states what he is capable of, so the fight is legible before it
  // starts rather than after it has killed you once.
  e.title = deceiverName(epithets);
  run.bossTitle = e.title;
  run.banner = 3.8;
  run.bannerText = e.title;
  // The title already names what he is; the note is for the thing you have to
  // do about it. Letting a mutator's line take this slot buried the escort
  // instruction, and since every rung rolls at least one mutator it buried it
  // permanently. The flavour lives on the rung card instead.
  run.bannerNote = guard
    ? 'His Lieutenants hold him. Break them first.'
    : 'He offers you the gate. Look for the shattered eye.';
  shake(10);
}

// Is anything still standing between him and you?
function escortAlive() {
  for (let i = 0; i < enemies.length; i++) {
    const e = enemies[i];
    if (e.kind === 'lieutenant' && e.hp > 0) return true;
  }
  return false;
}

function spawnMirages(src, n) {
  const d = ENEMY_TYPES.mirage;
  for (let i = 0; i < n; i++) {
    // A corridor rarely has three body-widths of clear ground at one radius,
    // so sweep angle and distance rather than taking a single guess.
    let x = 0, y = 0, ok = false;
    for (let tries = 0; tries < 16 && !ok; tries++) {
      const a = (i / n) * TAU + tries * 0.7 + Math.random() * 0.4;
      const dist = 66 + tries * 7;
      x = clamp(src.x + Math.cos(a) * dist, 40, WORLD.w - 40);
      y = clamp(src.y + Math.sin(a) * dist, 40, WORLD.h - 40);
      ok = !pointInWalls(x, y, d.r * 0.6);
    }
    if (!ok) continue;
    const m = newBody('mirage', x, y, 0);
    m.speed = d.speed; m.hp = m.maxHp = 1; m.dmg = 0; m.tech = 0;
    m.atk = 99; m.wob = 0; m.fade = 9;
    enemies.push(m);
  }
}

function updatePortal(dt) {
  portal.pulse += dt;
  // Reaching the quota does not open the gate -- it draws him to it.
  if (run.tech >= LEVEL.quota && !run.bossCalled) {
    run.bossCalled = true;
    spawnBoss();
  }
  portal.active = (run.tech >= LEVEL.quota && run.bossDown) || run.forcedOpen;
  if (!portal.active) { portal.channel = 0; portal.inside = false; return; }
  const inside = dist2(player.x, player.y, portal.x, portal.y) < PORTAL_R * PORTAL_R;
  portal.inside = inside;

  if (!run.gateOpen) {
    // Winding it open. Nothing is escalating yet.
    if (inside) {
      portal.channel = Math.min(LEVEL.channel, portal.channel + dt);
      if (portal.channel >= LEVEL.channel) {
        run.gateOpen = true;
        run.holdTime = 0;
        run.holdTicks = 0;
        run.banner = 3.0;
        run.bannerText = 'The ley-gate stands open';
        run.bannerNote = 'Step through, or hold it and let them come.';
      }
    } else {
      portal.channel = Math.max(0, portal.channel - dt * 0.7);
    }
    return;
  }

  // Open. Standing in it pays, and calls the delve down on you -- the two
  // rise together, which is the whole decision.
  if (!inside) return;
  run.holdTime += dt;

  // Where in the surge we are. The old curve closed the spawn interval to its
  // floor inside twenty-two seconds and then grew the batch every twelve, which
  // saturated the body cap in under a minute -- an escalation with no room left
  // to escalate into. A surge spends a fixed budget of bodies over its active
  // window instead, so the pressure has somewhere to go for ten minutes.
  const wave   = Math.floor(run.holdTime / HOLD_WAVE);
  const inWave = run.holdTime - wave * HOLD_WAVE;
  const push   = HOLD_WAVE - HOLD_LULL;
  const lull   = inWave >= push;
  run.holdWave = wave;
  run.holdLull = lull;

  if (!lull) {
    run.holdSpawn -= dt;
    if (run.holdSpawn <= 0) {
      const budget = 12 + wave * 7;          // bodies this surge is worth
      run.holdSpawn = push / budget;
      // Close in, not out at the usual spawn band: a body that has to cross two
      // screens to reach the gate is dead before it arrives, and the surge
      // dilutes itself into nothing however many it sends.
      const e = spawnEnemy(run.time, 0.72, 1.15);
      if (e) {
        // Bodies the gate calls are harder than bodies the delve was cut with,
        // and each surge harder than the last. Without this the escalation is
        // only ever a larger number of the same thing, which a kitted hero
        // out-damages indefinitely.
        const k = 1 + wave * 0.55;
        e.hp = e.maxHp = e.maxHp * k;
        e.dmg *= 1 + wave * 0.28;
        if (wave >= 1 && Math.random() < Math.min(0.5, 0.08 + wave * 0.03)) makeElite(e);
      }
    }
  } else if (!run.holdCrest) {
    // The crest has passed: name the lull so it reads as an offer, not a bug.
    run.holdCrest = true;
  }

  // Paid at the crest of each surge you outlast, so the reward lands with the
  // breathing room rather than in the middle of the next build.
  while (run.holdTime >= run.holdTicks * HOLD_WAVE + push) {
    run.holdTicks++;
    run.holdCrest = false;
    const pay = Math.round(HOLD_COIN * Math.pow(run.holdTicks, HOLD_POW) *
                           (1 + (LEVEL.depth || 0)));
    run.coins += pay;
    toast('Surge ' + run.holdTicks + ' held \u00b7 ' + pay + ' coin', PAL.coin);
    // Every other surge, and not the best rolls until late: a piece per surge
    // arms you against the surge that follows it, and the hold ends up paying
    // for its own difficulty.
    if (run.holdTicks % 2 === 0) {
      const it = rollItem(Math.min(1, 0.42 + run.holdTicks * 0.055));
      drops.push({ x: portal.x + rand(-40, 40), y: portal.y + rand(-40, 40),
                   vx: 0, vy: 0, item: it, r: 9, life: 0, pulled: false });
    }
    // And the gate shuts on the last one, taking you with it. Being thrown out
    // of a delve you survived is an extraction, not a death.
    if (run.holdTicks >= HOLD_MAX) {
      run.banner = 3.2;
      run.bannerText = 'The ley-gate closes';
      run.bannerNote = 'It has been held as long as it can be.';
      endRun(true);
      return;
    }
  }
}

// Step through: the run ends and everything banks. Only offered once the gate
// actually stands open.
function stepThrough() {
  if (state !== 'play' || !run.gateOpen || !portal.inside) return;
  endRun(true);
}

function compactEnemies() {
  let w = 0;
  for (let i = 0; i < enemies.length; i++) {
    if (enemies[i].hp > 0) enemies[w++] = enemies[i];
  }
  enemies.length = w;
}

// The delve is populated once, at generation, and cleared by walking into it.
// Nothing is pushed at the player on a timer any more -- the only bodies that
// arrive mid-run are the ones the Deceiver calls. Kept as a seam so a level
// can opt back into waves without touching the loop.
function updateSpawning(dt) {
  if (!LEVEL.waves) return;
  const t = run.time;
  const mul = portal.channel > 0 ? 2.4 : 1;
  run.spawnTimer -= dt * mul;
  if (run.spawnTimer > 0) return;
  run.spawnTimer = Math.max(0.30, 1.40 - t * 0.0068);
  const batch = 1 + Math.floor(t / 70);
  for (let i = 0; i < batch; i++) spawnEnemy(t);
}

function update(dt) {
  run.time += dt;
  if (run.banner > 0) { run.banner -= dt;
    if (run.banner <= 0) { run.bannerText = null; run.bannerNote = null; } }
  if (run.toast) { run.toast.life -= dt; if (run.toast.life <= 0) run.toast = null; }
  if (run.bagWarned > 0) run.bagWarned -= dt;
  updatePlayer(dt);
  updateArcs(dt);
  updateEnemies(dt);
  compactEnemies();
  updateLoot(dt);
  updateInvasion(dt);
  updateProps(dt);
  updateSlams(dt);
  updateHazards(dt);
  updateBeams(dt);
  updateNulls(dt);
  updateTotems(dt);
  updateFallen(dt);
  updateRuptures(dt);
  if (run.boss && run.boss.hp > 0) updateAgony(dt);
  if (swapFlash > 0) swapFlash = Math.max(0, swapFlash - dt * 3.4);
  if (run.dawnPop > 0) run.dawnPop = Math.max(0, run.dawnPop - dt * 3.2);
  updateDrops(dt);
  updateCorpse(dt);
  updateParticles(dt);
  updateFloaters(dt);
  updateBolts(dt);
  updateChests(dt);
  updateBleed(dt);
  updateGloom(dt);
  updateRings(dt);
  updatePortal(dt);
  updateSpawning(dt);
  updateCamera(dt);
}


let state = 'menu';   // menu | play | levelup | pause | over

// Which screens are stations of the gate-house, and which tab lights up for
// each. The kit is in here, but only when it was opened from the gate-house:
// the same screen reached from the bag button mid-delve is an overlay on a
// run, and putting a tab bar over that would offer to walk you out of a fight.
const HUB_TAB = { delve: 'toDelve', gear: 'toKit', vendor: 'toVendor', hall: 'toHall' };

const fmtTime = s => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');

/* --- persistence (best-effort; private mode can throw on access) -------- */
const STORE_KEY = 'rivenmark.best.v1';
/* --- the stash -----------------------------------------------------------
   Gear outlives a delve, but only what you carried out. Extract and the bag
   comes home with you; die and it stays on the floor where you fell. What is
   actually worn survives either way -- losing the kit off your back to one bad
   tap would make every delve a decision about whether to risk playing at all.
   ---------------------------------------------------------------------- */
const STASH_KEY = 'rivenmark.stash.v1';
const VAULT_MAX = 60;

/* --- the gate-house -------------------------------------------------------
   Coin was worth exactly three things: a commissioned piece, a temper, and a
   reliquary. All three are consumables, so a good run bought a slightly better
   next run and nothing else -- there was nowhere for the money to accumulate
   into. The hall is that place. Four stations, three tiers each, every tier
   paid for once and kept forever, and each one changes a number the player can
   already feel.
   -------------------------------------------------------------------- */
const HALL = [
  { id: 'vault', name: 'The Vault', mark: '\u25a4',
    note: 'Shelves, and the stone to hold them.',
    tiers: [
      { cost: 900,  text: '+20 vault, +1 kit preset' },
      { cost: 2600, text: '+40 vault, +2 kit presets' },
      { cost: 6200, text: '+60 vault, +3 kit presets' }
    ] },
  { id: 'forge', name: 'The Forge', mark: '\u2692',
    note: 'A fire hot enough to argue with.',
    tiers: [
      { cost: 1100, text: 'Commissions and tempers cost 12% less' },
      { cost: 3000, text: '24% less' },
      { cost: 7000, text: '36% less, and a wider bag by four' }
    ] },
  { id: 'reliquary', name: 'The Reliquary', mark: '\u2735',
    note: 'Somewhere to keep what the delve gives up.',
    tiers: [
      { cost: 1400, text: 'Regalia falls 15% more often' },
      { cost: 3600, text: '30% more often, reliquaries cost 15% less' },
      { cost: 8000, text: '50% more often, reliquaries cost 30% less' }
    ] },
  { id: 'wardstone', name: 'The Wardstone', mark: '\u25c8',
    note: 'It remembers every Vanguard who came back.',
    tiers: [
      { cost: 1200, text: '+10 life, +1.5% ward' },
      { cost: 3200, text: '+22 life, +3% ward' },
      { cost: 7500, text: '+38 life, +5% ward' }
    ] }
];
const HALL_BY_ID = {};
for (const h of HALL) HALL_BY_ID[h.id] = h;
const HALL_MAX = 3;

const hallTier = id => clamp((stash.hall && stash.hall[id]) || 0, 0, HALL_MAX);
const hallTotal = () => HALL.reduce((n, h) => n + hallTier(h.id), 0);

// The caps the hall moves. Read through these rather than the constants, or a
// tier bought is a tier that does nothing.
const vaultCap   = () => VAULT_MAX + 20 * hallTier('vault');
const loadoutCap = () => LOADOUT_MAX + hallTier('vault');
const bagCap     = () => BAG_MAX + (hallTier('forge') >= 3 ? 4 : 0);
const forgeCut   = () => 1 - 0.12 * hallTier('forge');
const relicCut   = () => 1 - 0.15 * Math.max(0, hallTier('reliquary') - 1);
const setBoost   = () => 1 + [0, 0.15, 0.30, 0.50][hallTier('reliquary')];
const wardStone  = () => ({ maxHp: [0, 10, 22, 38][hallTier('wardstone')],
                            ward:  [0, 0.015, 0.03, 0.05][hallTier('wardstone')] });

function hallCost(h) {
  const t = hallTier(h.id);
  return t >= HALL_MAX ? 0 : h.tiers[t].cost;
}

function hallBuy(h) {
  const t = hallTier(h.id);
  if (t >= HALL_MAX) return 'already whole';
  const cost = h.tiers[t].cost;
  if ((stash.coins || 0) < cost) return 'not enough coin';
  stash.coins -= cost;
  stash.hall[h.id] = t + 1;
  saveStash();
  return null;
}

function blankStash() {
  const g = {};
  for (const sl of SLOTS) g[sl.id] = null;
  return { gear: g, vault: [], hero: 'isaac', seq: 0, xp: 0, level: 1,
           coins: 0, pity: 0, loadouts: [], corpse: null,
           hall: { vault: 0, forge: 0, reliquary: 0, wardstone: 0 } };
}

function validItem(it, slotId) {
  if (!it || typeof it !== 'object') return false;
  if (!SLOT_BY_ID[it.slot]) return false;
  if (slotId && it.slot !== slotId) return false;
  if (!RARITY.some(r => r.id === it.rarity)) return false;
  if (!Array.isArray(it.affixes)) return false;
  return it.affixes.every(a => AFFIX_BY_ID[a.id] && isFinite(a.v));
}

let stash = blankStash();

// Carried home from a finished delve. Equipped kit always; the bag only if the
// Vanguard actually walked out.
function bankRun(extracted) {
  // Slag is only worth anything if it leaves the delve with you.
  if (extracted) {
    stash.xp = (stash.xp || 0) + run.tech;
    stash.level = levelForXp(stash.xp);
    stash.coins = (stash.coins || 0) + run.coins;
  }
  for (const sl of SLOTS) stash.gear[sl.id] = player.gear[sl.id] || null;
  if (extracted) {
    for (const it of player.bag) {
      if (stash.vault.length >= vaultCap()) break;
      stash.vault.push(it);
    }
  }
  stash.hero = run.hero;
  saveStash();
}

/* --- HUD (written only when a value actually changes) ------------------- */
const hudCache = { hp: -1, tech: -1, time: -1, lvl: -1, gate: '' };

let flashTimer = 0;

/* --- what the horde does about dying ---------------------------------------
   Three behaviours, and all of them are the same idea from different angles:
   the delve does not simply stand there losing. It heals, it protects, and it
   eats its own dead, and each of those is a thing the player has to go and
   stop rather than out-damage.
   -------------------------------------------------------------------- */
const CALCIFY_AT   = 0.30;  // the share of life a heavy body breaks off at
const CALCIFY_TIME = 4;     // and how long you have to stop it
const CALCIFY_BREAK = 0.12; // damage in one blow, as a share of max, that stops it

const TOTEM_HP    = 60;
const TOTEM_R     = 180;    // the ring it heals inside
const TOTEM_HPS   = 9;      // life a second, to everything standing in it
const TOTEM_LIFE  = 22;

const CONSUME_R    = 90;    // how near a corpse an elite has to be
const CONSUME_TIME = 2.2;   // how long the feed lasts
const CONSUME_PCT  = 0.055; // and what it returns a second, as a share of max

let totems = [];

/* Calcification. A heavy body that is nearly down stops fighting, turns away
   and begins to close: the dust in the room is pulled into it on a cubic
   curve, a crystal shell rises, and if it is left alone for four seconds it
   comes back whole.

   It counts as a cast, which is deliberate -- it means Focal Decryption snaps
   it, and Zayd's interrupt has something to do outside a boss room. */
function beginCalcify(e) {
  e.calcify = CALCIFY_TIME;
  e.calcifyMax = CALCIFY_TIME;
  e.calcified = true;                 // once only: a body cannot keep retreating
  toast('It is closing', '#9fd8e8');
  ring(e.x, e.y, '#9fd8e8', e.r * 3, e.r * 0.8, 0.6);
}

function breakCalcify(e, hard) {
  if (!(e.calcify > 0)) return;
  e.calcify = 0;
  burst(e.x, e.y, '#cfe9f2', 18, 240);
  shake(5);
  if (hard) toast('The shell breaks', '#cfe9f2');
}

function updateCalcify(e, dt) {
  e.calcify -= dt;
  // The vacuum: motes pulled in, accelerating as they arrive. Cubic, so the
  // last third of the journey is most of the speed and the eye reads it as
  // being drawn in rather than as drifting.
  if (!lowFx && Math.random() < 0.7) {
    const a = Math.random() * TAU, d = e.r * (3 + Math.random() * 2.4);
    spark(e.x + Math.cos(a) * d, e.y + Math.sin(a) * d, e.x, e.y, '#9fd8e8');
  }
  if (e.calcify <= 0) {
    // Left alone. It comes back whole, and it says so.
    e.hp = e.maxHp;
    e.calcify = 0;
    burst(e.x, e.y, '#cfe9f2', 30, 320);
    ring(e.x, e.y, '#cfe9f2', 6, e.r * 4, 0.5);
    shake(8);
    toast('It is whole again', '#cfe9f2');
  }
}

// One mote of the vacuum. Kept in the particle pool so it costs what every
// other particle costs, and given a target it eases toward.
function spark(x, y, tx, ty, color) {
  if (particles.length >= MAX_PARTICLES) return;
  // Same shape as everything else in the pool -- `color` and `size`, not a
  // private pair of names -- plus the target it is being drawn toward.
  particles.push({ x, y, vx: 0, vy: 0, life: 0.55, max: 0.55, color,
                   size: 1.4 + Math.random() * 1.6,
                   sx: x, sy: y, tx, ty, suck: true });
}

/* Resonance Totems. A shaman plants one and the horde standing round it stops
   dying. It has its own life and no defence -- the difficulty is entirely that
   the bodies are in the way, which is what the horde's mass is for. */
function plantTotem(x, y) {
  if (totems.length >= 4) return;
  totems.push({ x, y, hp: TOTEM_HP * (1 + (LEVEL.depth || 0)), maxHp: TOTEM_HP * (1 + (LEVEL.depth || 0)),
                life: TOTEM_LIFE, pulse: 0 });
  ring(x, y, '#9dbb5a', 8, TOTEM_R, 0.5);
  toast('A totem is planted', '#9dbb5a');
}

function updateTotems(dt) {
  for (let i = totems.length - 1; i >= 0; i--) {
    const t = totems[i];
    t.life -= dt;
    t.pulse += dt;
    if (t.life <= 0 || t.hp <= 0) {
      burst(t.x, t.y, '#9dbb5a', 22, 260);
      ring(t.x, t.y, '#9dbb5a', 6, 70, 0.4);
      if (t.hp <= 0) toast('The totem falls', '#9dbb5a');
      totems.splice(i, 1);
      continue;
    }
    // It mends the horde, not the player. Standing in it is not a gift.
    enemyGrid.query(t.x, t.y, TOTEM_R, _near);
    for (let k = 0; k < _near.length; k++) {
      const e = _near[k];
      if (e.hp <= 0 || e.hp >= e.maxHp) continue;
      if (dist2(e.x, e.y, t.x, t.y) > TOTEM_R * TOTEM_R) continue;
      e.hp = Math.min(e.maxHp, e.hp + TOTEM_HPS * dt);
      e.mended = 0.2;
    }
  }
}

// The blade and everything else hits a totem the way it hits a body. Called
// from the places that already look for something to damage.
function hurtTotemsNear(x, y, r, dmg) {
  let hit = false;
  for (let i = 0; i < totems.length; i++) {
    const t = totems[i];
    if (dist2(x, y, t.x, t.y) > (r + 14) * (r + 14)) continue;
    t.hp -= dmg;
    floatDmg(t.x, t.y - 18, dmg, 'hit');
    burst(t.x, t.y, '#9dbb5a', 4, 120);
    hit = true;
  }
  return hit;
}

/* Ravenous Consumption. An elite standing over a thrall it did not kill will
   stop and take the slag out of it. It is the one time a champion is standing
   still and not looking at you. */
function tryConsume(e, dt) {
  if (e.consume > 0) {
    e.consume -= dt;
    e.hp = Math.min(e.maxHp, e.hp + e.maxHp * CONSUME_PCT * dt);
    e.mended = 0.2;
    if (!lowFx && Math.random() < 0.5 && e.feedX !== undefined) {
      spark(e.feedX + rand(-10, 10), e.feedY + rand(-10, 10), e.x, e.y, '#c8d63a');
    }
    return true;
  }
  if (!e.elite || e.fed) return false;
  // Corpses are the ones the delve keeps: a body that has just gone down.
  for (let i = 0; i < corpsesFresh.length; i++) {
    const c = corpsesFresh[i];
    if (c.taken) continue;
    if (dist2(e.x, e.y, c.x, c.y) > CONSUME_R * CONSUME_R) continue;
    c.taken = 1;
    e.consume = CONSUME_TIME;
    e.fed = true;                    // once each, or a field of dead is a full heal
    e.feedX = c.x; e.feedY = c.y;
    ring(c.x, c.y, '#c8d63a', 4, 40, 0.4);
    return true;
  }
  return false;
}

// Where a body went down, kept for a moment so an elite has something to feed
// on. Not the player's corpse -- that is a different thing entirely.
let corpsesFresh = [];
function noteFallen(x, y) {
  if (corpsesFresh.length > 24) corpsesFresh.shift();
  corpsesFresh.push({ x, y, life: 6, taken: 0 });
}
function updateFallen(dt) {
  for (let i = corpsesFresh.length - 1; i >= 0; i--) {
    corpsesFresh[i].life -= dt;
    if (corpsesFresh[i].life <= 0) corpsesFresh.splice(i, 1);
  }
}

/* --- the Gilded Deceiver ---------------------------------------------------
   Everything above this line is a delve you can walk out of. This is the one
   fight the game asks you to learn, and the whole of it is an argument for
   the two heroes: it is not survivable on one of them.

   He cannot be touched while his Lieutenants stand, so the fight opens on
   them. They answer with one coordinated cleave that Isaac has to plant
   himself into, and with a channel that feeds their master, which only Zayd
   can snap. Everything you fail to stop pushes a crystal toward full, and
   full is a wipe -- so the meter, not his health bar, is the clock.

   Kill the escort and the meter is already at ninety-five: he goes to the
   middle of the room and spends five seconds pushing it the rest of the way.
   That channel is the fight. A Null-Zone dropped underneath it reacts, empties
   the crystal, puts him down for ten seconds and leaves him Vulnerable -- and
   Vulnerable is the word the Guillotine has been waiting for since it was
   written. Swap, build three, and bring it down.
--------------------------------------------------------------------------- */

const DAWN_MAX      = 100;    // the crystal, full
const DAWN_PER_LIEUT= 13;     // what one Lieutenant's whole life is worth
const DAWN_SIPHON   = 12;     // and what one channel you let finish costs
const DAWN_BREATH   = 95;     // where it stands the moment the last one falls

const AGONY_CD      = 9.5;    // between coordinated cleaves
const AGONY_WIND    = 1.6;    // and how long you have to answer one
const AGONY_ARC     = 1.15;   // the half-angle it takes
const AGONY_REACH   = 168;
const AGONY_MULT    = 2.6;    // per Lieutenant with you in its arc

const SIPHON_CD     = 11;     // a Lieutenant's own clock, staggered
const SIPHON_TIME   = 3.2;
const SIPHON_R      = 150;    // how close to him it has to stand to pour
const SIPHON_HEAL   = 0.07;   // of his life, per channel you let finish

const RUPTURE_CD    = 7.5;
const RUPTURE_WIND  = 2;      // the golden circle, before it goes
const RUPTURE_R     = 96;
const RUPTURE_MULT  = 2.2;

const BREATH_TIME   = 5;      // the channel that finishes it
const NULLIFY_STUN  = 10;     // and what breaking the channel buys you

let ruptures = [];

// The crystal only exists while he does, so everything in here is a no-op in
// an ordinary delve rather than a branch every caller has to remember.
function dawnAdd(n, why) {
  if (!run || !run.boss || run.boss.hp <= 0) return;
  const was = run.dawn || 0;
  run.dawn = clamp(was + n, 0, DAWN_MAX);
  if (run.dawn > was) run.dawnPop = 1;
  if (run.dawn >= DAWN_MAX && was < DAWN_MAX) wipeRoom(why);
}

// Full. There is no answer to this one -- the answer was upstream, and this
// is the game saying which upstream thing you missed.
function wipeRoom(why) {
  run.dawnFired = true;
  shake(30);
  ring(player.x, player.y, '#fff2c8', 20, 900, 1.1);
  burst(player.x, player.y, '#ffd870', 60, 520);
  run.banner = 3.6;
  run.bannerText = 'False Dawn';
  run.bannerNote = why || 'The light came up, and it was not the sun.';
  player.invuln = 0;
  hurtPlayerBy(player.maxHp * 4, player.x, player.y - 200);
}

// --- Synchronized Agony ----------------------------------------------------
// They wind together and they land together, which is what makes it worth a
// cooldown rather than a dodge: three arcs from three directions leave one
// place to stand, and standing still behind Unyielding Mass is the other
// half of the answer.
function updateAgony(dt) {
  const live = [];
  for (let i = 0; i < enemies.length; i++) {
    const e = enemies[i];
    if (e.kind === 'lieutenant' && e.hp > 0 && !e.siphonOn) live.push(e);
  }
  if (!live.length) { run.agonyT = 0; return; }

  if ((run.agonyT || 0) > 0) {
    run.agonyT -= dt;
    if (run.agonyT <= 0) {
      run.agonyT = 0;
      // One blow, summed. Landing three separate hits would mean two of them
      // were eaten by the invulnerability the first one grants, so a cleave
      // you stood in the middle of would cost the same as one you clipped.
      let dmg = 0;
      for (let i = 0; i < live.length; i++) {
        const L = live[i];
        if (L.agonyA === undefined) continue;
        L.agony = 0;
        const d = Math.hypot(player.x - L.x, player.y - L.y);
        if (d > AGONY_REACH) continue;
        let off = Math.atan2(player.y - L.y, player.x - L.x) - L.agonyA;
        while (off >  Math.PI) off -= TAU;
        while (off < -Math.PI) off += TAU;
        if (Math.abs(off) > AGONY_ARC) continue;
        dmg += L.dmg * AGONY_MULT;
        ring(L.x, L.y, '#c2352a', 20, AGONY_REACH, 0.32);
      }
      for (let i = 0; i < live.length; i++) live[i].agonyA = undefined;
      shake(dmg > 0 ? 18 : 7);
      if (dmg > 0) {
        freeze(0.07);
        hurtPlayerBy(dmg, player.x, player.y + 40);
      }
    }
    return;
  }

  run.agonyCd = (run.agonyCd || 0) - dt;
  if (run.agonyCd > 0) return;
  // Only when at least one of them could actually reach you: winding a cleave
  // at an empty room teaches the tell without the lesson attached to it.
  let near = false;
  for (let i = 0; i < live.length; i++)
    if (Math.hypot(player.x - live[i].x, player.y - live[i].y) < AGONY_REACH * 1.15) near = true;
  if (!near) return;

  run.agonyT  = AGONY_WIND;
  run.agonyCd = AGONY_CD;
  for (let i = 0; i < live.length; i++) {
    const L = live[i];
    // Aimed once, at the wind-up. Walking out of the arc is an answer too --
    // it is just the one that stops working when there are three of them.
    L.agonyA = Math.atan2(player.y - L.y, player.x - L.x);
    L.agony  = AGONY_WIND;
  }
  toast('Synchronized Agony', '#c2352a');
}

// --- Slag Siphon -----------------------------------------------------------
// A Lieutenant breaks off, goes to its master and pours. It is a cast, so it
// is Zayd's problem: Focal Decryption ends it, and a Null-Zone under it drags
// it out long enough to reach.
function updateSiphon(e, dt) {
  const boss = run.boss;
  if (!boss || boss.hp <= 0) { e.siphonOn = false; return false; }

  if (e.siphonOn) {
    // Interrupted: silence() zeroes the cast bar, so a bar already at zero
    // when we arrive is one somebody snapped. Checked BEFORE the tick, or our
    // own subtraction would take it past zero and read as a finished channel.
    if ((e.silenced || 0) > 0 || (e.casting || 0) <= 0) {
      e.siphonOn = false;
      e.siphon = SIPHON_CD * 0.6;
      ring(e.x, e.y, '#7fd4ff', 8, 70, 0.4);
      toast('The pour is broken', '#7fd4ff');
      return false;
    }
    e.casting -= dt;
    if (e.casting <= 0) {
      e.casting = 0;
      e.siphonOn = false;
      e.siphon = SIPHON_CD;
      boss.hp = Math.min(boss.maxHp, boss.hp + boss.maxHp * SIPHON_HEAL);
      boss.mended = 0.3;
      dawnAdd(DAWN_SIPHON, 'They poured it into him and nobody stopped it.');
      ring(boss.x, boss.y, '#e8c060', 10, 120, 0.5);
      for (let k = 0; k < 14; k++)
        spark(e.x + rand(-14, 14), e.y + rand(-14, 14), boss.x, boss.y, '#e8c060');
      return false;
    }
    // Standing still and pouring. Not steered by anything else while it does.
    for (let k = 0; k < 2; k++)
      spark(e.x + rand(-12, 12), e.y + rand(-12, 12), boss.x, boss.y, '#e8c060');
    return true;
  }

  e.siphon = (e.siphon || 0) - dt;
  if (e.siphon > 0 || (e.silenced || 0) > 0) return false;
  // One at a time. Two channels at once cannot both be snapped -- Focal
  // Decryption takes one target -- so a second pour would not be a harder
  // test of the interrupt, it would be an untestable one.
  for (let i = 0; i < enemies.length; i++) {
    const o = enemies[i];
    if (o !== e && o.kind === 'lieutenant' && o.hp > 0 && o.siphonOn) return false;
  }

  // Walk to him first. Until it is close enough it is just a body leaving the
  // fight, which is its own tell.
  const d = Math.hypot(boss.x - e.x, boss.y - e.y);
  if (d > SIPHON_R) {
    const a = Math.atan2(boss.y - e.y, boss.x - e.x);
    const mx0 = e.x, my0 = e.y;
    moveEntity(e, Math.cos(a) * e.speed * 1.25 * dt, Math.sin(a) * e.speed * 1.25 * dt);
    e.face = Math.cos(a) < 0 ? -1 : 1;
    // Its legs still have to know it is moving, or a body crossing the room
    // to pour slides there in its standing pose.
    advanceGait(e, mx0, my0, dt);
    return true;
  }
  e.siphonOn = true;
  e.casting  = SIPHON_TIME;
  ring(e.x, e.y, '#e8c060', 6, 54, 0.4);
  toast('Slag Siphon — break it', '#e8c060');
  return true;
}

// Planted for the cleave, or gone to pour. Either way it is not chasing you,
// and neither one is steered by the seek below it.
function lieutenantBusy(e, dt) {
  if ((e.agony || 0) > 0) {
    // Planted while it winds. A cone aimed at where you were, thrown by a
    // body still walking toward you, is a cone that lands somewhere it was
    // never drawn.
    e.agony -= dt;
    return true;
  }
  if (!run || !run.boss || run.boss.hp <= 0) return false;
  if ((run.agonyT || 0) > 0) return false;   // about to swing: not now
  return updateSiphon(e, dt);
}

// --- Inverted Ley-Rupture --------------------------------------------------
// The ground under whoever is standing on it. It costs life, and it costs the
// resource -- so eating one does not only hurt, it puts the Guillotine or the
// Null-Zone back out of reach, which is the half that actually matters.
function beginRupture(x, y) {
  ruptures.push({ x, y, t: RUPTURE_WIND, max: RUPTURE_WIND });
}
function updateRuptures(dt) {
  for (let i = ruptures.length - 1; i >= 0; i--) {
    const r = ruptures[i];
    r.t -= dt;
    if (r.t > 0) continue;
    ruptures.splice(i, 1);
    ring(r.x, r.y, '#ffd870', 12, RUPTURE_R, 0.5);
    burst(r.x, r.y, '#e8c060', 22, 300);
    shake(9);
    if (dist2(player.x, player.y, r.x, r.y) > RUPTURE_R * RUPTURE_R) continue;
    const boss = run.boss;
    hurtPlayerBy((boss ? boss.dmg : 30) * RUPTURE_MULT, r.x, r.y);
    if (player.hero === 'isaac' && (player.charges || 0) > 0) {
      spendCharges(CHARGE_MAX);
      toast('The Sun-Gold is inverted', '#e8c060');
    } else if (player.hero === 'zayd' && (player.tension || 0) > 0) {
      player.tension = 0;
      toast('The Tension is inverted', '#e8c060');
    }
  }
}

// --- Breath of the Void, and the window it opens ---------------------------
// The escort is down, the crystal is at ninety-five, and he is going to spend
// five seconds pushing it the rest of the way. Everything the fight has been
// teaching is for these five seconds.
function beginBreath(boss) {
  run.breath = BREATH_TIME;
  run.dawn = Math.max(run.dawn || 0, DAWN_BREATH);
  // The five seconds have exactly one answer, and it is Zayd's. If the escort
  // went down on Isaac -- which is how it usually goes, because Isaac is who
  // survives the cleave -- then Zayd's Ley-Tension has been sitting banked and
  // frozen since the last swap, quite possibly at nothing, and the swap itself
  // may be four seconds into its own five. A wipe you could not have answered
  // because of a cooldown is not a mechanic, it is a coin toss, so the fight
  // hands you the tool and asks only whether you use it: the swap comes off
  // cooldown and the Spellbreaker arrives full.
  player.swapCd = 0;
  run.pools = run.pools || {};
  if (player.hero === 'zayd') player.tension = TENSION_MAX;
  else if (run.pools.zayd) run.pools.zayd.tension = TENSION_MAX;
  else run.pools.zayd = { hp: 0, charges: 0, tension: TENSION_MAX,
                          jars: JAR_USES, cds: {} };
  // A pool written before he has ever been out would otherwise hand him zero
  // life. He arrives whole the first time either way, so mark it.
  if (run.pools.zayd && !(run.pools.zayd.hp > 0)) run.pools.zayd.firstOut = true;
  boss.braced = false;
  boss.blink = 1e9;                 // he stops stepping about: he is committed
  boss.casting = BREATH_TIME;       // and it reads as a cast, because it is one
  const c = portal || { x: boss.x, y: boss.y };
  boss.breathX = c.x; boss.breathY = c.y;
  run.banner = 3.4;
  run.bannerText = 'Breath of the Void';
  run.bannerNote = 'Put a Null-Zone underneath him.';
  ring(boss.x, boss.y, '#e8c060', 20, 260, 0.7);
  shake(14);
}

function updateBreath(boss, dt) {
  // To the middle of the room, and then still.
  const dx = boss.breathX - boss.x, dy = boss.breathY - boss.y;
  const d = Math.hypot(dx, dy);
  if (d > 6) moveEntity(boss, (dx / d) * boss.speed * 1.6 * dt, (dy / d) * boss.speed * 1.6 * dt);

  run.breath -= dt;
  boss.casting = Math.max(0, run.breath);
  // The meter walks the last five points up over the channel, so the crystal
  // itself is the timer and there is no second clock to read.
  const f = 1 - clamp(run.breath / BREATH_TIME, 0, 1);
  run.dawn = Math.max(run.dawn || 0, DAWN_BREATH + (DAWN_MAX - DAWN_BREATH) * f);
  if (!lowFx && Math.random() < 0.6)
    spark(boss.x + rand(-90, 90), boss.y + rand(-90, 90), boss.x, boss.y, '#ffd870');
  if (run.breath <= 0) {
    run.breath = 0;
    boss.casting = 0;
    run.dawn = DAWN_MAX;
    wipeRoom('He finished the breath. Nothing was under him.');
  }
}

// A Null-Zone dropped on him while he breathes. This is the one interaction
// the whole encounter is built around, so it is checked from the ability
// rather than from a proximity sweep -- it happens because you did it.
function tryNullify(zx, zy, zr) {
  const boss = run && run.boss;
  if (!boss || boss.hp <= 0 || !((run.breath || 0) > 0)) return false;
  const reach = zr + boss.r;
  if (dist2(zx, zy, boss.x, boss.y) > reach * reach) return false;

  run.breath = 0;
  run.dawn = 0;
  run.dawnPop = 1;
  boss.casting = 0;
  boss.braced = false;
  boss.blink = 1e9;
  boss.stun = NULLIFY_STUN;
  boss.vuln = VULN_TIME;
  boss.silenced = Math.max(boss.silenced || 0, NULLIFY_STUN);
  freeze(0.09);
  shake(24);
  ring(boss.x, boss.y, '#b07cff', 14, 320, 0.8);
  burst(boss.x, boss.y, '#b07cff', 46, 420);
  burst(boss.x, boss.y, '#fff2c8', 30, 260);
  run.banner = 3.4;
  run.bannerText = 'Metaphysical Nullification';
  run.bannerNote = 'He is open. Swap, build three, bring it down.';
  return true;
}

// --- the crystal -----------------------------------------------------------
// Jagged, tall and on the right, where a thumb is not. It is the fight's real
// health bar: his own only starts mattering once this one is empty.
function dawnCrystalRect() {
  // Under the map, not through it. Read off minimapBox() rather than off the
  // same arithmetic written out again -- the first version put the crystal at
  // the top-right on its own numbers and drew it straight over the map, with
  // its label clipped by the screen edge on top of that.
  const m = minimapBox();
  const w = 34;
  const top = m.y + m.s + m.over + 18;          // clear of the stone, and of the label
  const h = Math.max(120, Math.min(215, view.h * 0.62 - top));
  return { x: view.w - view.safeR - w - 12, y: top, w, h };
}

/* --- the other one ---------------------------------------------------------
   Two of the Clear-Sighted went down there, and the fiction has always said
   so: Isaac is proof against the Deceiver's illusions and Zayd against his
   tether, which is a pair of answers to one antagonist. Until now you took one
   and left the other at the gate.

   They keep their own life. Swapping is not a heal and not an escape -- the
   one you leave keeps the wounds you left him with, and comes back with them.

   GEAR IS SHARED. One worn kit, and the hero-forged affixes pay out for
   whichever of them is holding it. Two kits would double what a run has to
   farm before either of them is dressed, and the alternative -- half your
   affixes idle at all times -- is worse.
   -------------------------------------------------------------------- */
function otherHero() { return player.hero === 'isaac' ? 'zayd' : 'isaac'; }

function swapBlocked() {
  if (state !== 'play') return 'no';
  if ((player.swapCd || 0) > 0) return 'cd';
  if (onGCD()) return 'gcd';
  return null;
}

function swapHero() {
  if (swapBlocked()) return false;
  const from = player.hero, to = otherHero();

  breakChannel('swap');
  // Bank what this one is carrying, then take up what the other was left with.
  run.pools = run.pools || {};
  run.pools[from] = { hp: player.hp, charges: player.charges || 0,
                      tension: player.tension || 0, jars: player.jars || 0,
                      cds: Object.assign({}, player.cds) };

  player.hero = to;
  recomputeStats(player);                 // stats and the forged-for bonus both
  const bank = run.pools[to];
  if (bank && bank.firstOut) {
    // A pool the encounter wrote before this hero had ever been out. Take the
    // resources it left and the full life a first arrival gets.
    player.hp = player.maxHp;
    player.charges = bank.charges; player.tension = bank.tension;
    player.jars = bank.jars; player.cds = bank.cds;
  } else if (bank) {
    player.hp = Math.min(bank.hp, player.maxHp);
    player.charges = bank.charges; player.tension = bank.tension;
    player.jars = bank.jars; player.cds = bank.cds;
  } else {
    // First time out. A hero who has not been down yet arrives whole.
    player.hp = player.maxHp;
    player.charges = 0; player.tension = 0;
    player.jars = JAR_USES; player.cds = {};
  }

  player.swapCd = SWAP_CD;
  startGCD(1.25);                          // 1.5s, the beat the brief asks for
  player.invuln = Math.max(player.invuln, 0.35);
  swapFlash = 1;
  shake(7);
  ring(player.x, player.y, HEROES[to].magic, 8, 90, 0.4);
  burst(player.x, player.y, HEROES[to].magic, 22, 260);
  buildKit();
  syncHeroSkin();
  toast(HEROES[to].name + ' takes the ground', HEROES[to].magic);
  return true;
}

// The composite flash. One frame-wide wash in the arriving hero's colour,
// drawn over everything, falling away fast.
let swapFlash = 0;

/* --- the kit, on the glass -------------------------------------------------
   Built once when a run starts, then only the state that changed is written
   each frame. The HUD next door already works this way and for the same
   reason: writing five buttons' worth of DOM sixty times a second is the one
   thing that will cost more than the whole simulation.
   -------------------------------------------------------------------- */
let kitCache = {};

/* --- run lifecycle ------------------------------------------------------ */

function resetRun(heroId, levelId, diffId) {
  const hero = heroId || (run && run.hero) || 'isaac';
  DIFF = DIFF_BY_ID[diffId || (run && run.diff_id) || DIFF.id] || DIFF_BY_ID.riven;
  LEVEL = LEVEL_BY_ID[levelId || (run && run.level_id) || LEVELS[0].id] || LEVELS[0];
  // The level decides which regions it can be cut from; the delve rolls one.
  const pool = LEVEL.regions;
  REGION = REGION_BY_ID[pool[(Math.random() * pool.length) | 0]] || REGIONS[0];
  PAL.stoneTop = REGION.stone[0];
  PAL.stoneMid = REGION.stone[1];
  PAL.stoneLow = REGION.stone[2];
  PAL.ember = REGION.lamp;
  wallGrads.clear();
  forgeGround();
  forgeWallCourses();

  const spawn = { x: WORLD.w / 2, y: WORLD.h / 2 };
  const a = Math.random() * TAU, d = rand(700, 880);
  const pt = {
    x: clamp(spawn.x + Math.cos(a) * d, 150, WORLD.w - 150),
    y: clamp(spawn.y + Math.sin(a) * d, 150, WORLD.h - 150)
  };

  generateWorld(spawn, pt);
  portal  = { x: pt.x, y: pt.y, pulse: 0, channel: 0, active: false, inside: false };
  player  = makePlayer(spawn.x, spawn.y, hero);
  enemies = []; arcs = []; loot = []; drops = []; particles = []; rings = [];
  floaters = []; bolts = []; chests = [];
  slams = [];
  beams = []; nulls = []; totems = []; corpsesFresh = []; hazards = [];
  ruptures = [];
  enemyGrid = new SpatialHash(ENEMY_CELL);

  run = { time: 0, tech: 0, kills: 0,
          // Where the one who is not on the ground keeps his wounds. Cleared
          // per run: swapping is not a heal, but a new delve is a new delve.
          pools: {},
          spawnTimer: 1.4, hero: hero, level_id: LEVEL.id,
          diff_id: DIFF.id,
          banner: 4.2,
          bannerText: null, bannerNote: null,
          bossCalled: false, bossDown: false, boss: null, gloom: 0,
          spawnX: spawn.x, spawnY: spawn.y, found: 0, toast: null, bagWarned: 0,
          coins: 0, gateOpen: false, holdTime: 0, holdTicks: 0, holdSpawn: 1.5,
          forcedOpen: false, corpse: null,
          holdWave: 0, holdLull: false, holdCrest: false,
          invader: null, invadeAt: 0, invadeKills: 0,
          // The Deceiver's clock. Nothing reads these outside his room, and
          // dawnAdd() is a no-op until he is standing, so an ordinary delve
          // carries them and never notices.
          dawn: 0, dawnPop: 0, dawnFired: false, breath: 0,
          agonyT: 0, agonyCd: AGONY_CD * 0.65 };
  run.invadeAt = rollInvasion();
  // If you died in this level and never came back for it, it is still here.
  run.corpse = placeCorpse();

  cam.x = clamp(player.x - view.w / 2, 0, Math.max(0, WORLD.w - view.w));
  cam.y = clamp(player.y - view.h / 2, 0, Math.max(0, WORLD.h - view.h));
  cam.shake = 0;

  recomputeStats();
  placePacks(spawn);
  placeChests(spawn, portal);
  flowFrom = -1;
  rebuildFlow();
  hudCache.hp = hudCache.tech = hudCache.time = hudCache.lvl = -1;
  syncBagBadge();
  stickEnd();
  keys.clear();
  syncHud();
}

function startRun(heroId, levelId, diffId) {
  resetRun(heroId, levelId, diffId);
  state = 'play';
  buildKit();
  syncHeroSkin();
  showScreen(null);
}

/* --- level-up ----------------------------------------------------------- */

/* rollUpgrades / openLevelUp / takeUpgrade are gone with the boons. Slag is
   experience now, banked on the hero when the delve ends, so nothing
   interrupts a run to offer a card. UPGRADES itself is kept only as the
   vendor's crafting table -- see the hub. */

/* --- loadouts -------------------------------------------------------------
   A preset is a list of item ids, not a copy of the items. Anything the
   preset names that is no longer in the kit or the vault is simply skipped,
   so a saved loadout degrades gracefully instead of conjuring back a piece
   that was tempered, sold or lost in a delve.
   ---------------------------------------------------------------------- */
const LOADOUT_MAX = 4;

function findItem(uid) {
  if (uid == null) return null;
  for (const sl of SLOTS) {
    const it = stash.gear[sl.id];
    if (it && it.uid === uid) return { it, from: 'gear', slot: sl.id };
  }
  for (let i = 0; i < stash.vault.length; i++) {
    if (stash.vault[i].uid === uid) return { it: stash.vault[i], from: 'vault', index: i };
  }
  return null;
}

function saveLoadout(name) {
  const slots = {};
  for (const sl of SLOTS) {
    const it = stash.gear[sl.id];
    slots[sl.id] = it ? it.uid : null;
  }
  const L = { name: (name || 'Kit ' + (stash.loadouts.length + 1)).slice(0, 18),
              hero: stash.hero || 'isaac', slots };
  stash.loadouts.push(L);
  if (stash.loadouts.length > loadoutCap()) stash.loadouts.shift();
  saveStash();
  return L;
}

// Returns how many pieces it could actually restore, so the UI can say when a
// preset has aged badly rather than silently equipping half a kit.
function applyLoadout(L) {
  if (!L) return { set: 0, missing: 0 };
  let set = 0, missing = 0;
  // Everything currently worn goes back to the vault first, or a swap could
  // drop a piece on the floor of the gate-house.
  for (const sl of SLOTS) {
    const it = stash.gear[sl.id];
    if (it) { stash.gear[sl.id] = null; stash.vault.push(it); }
  }
  for (const sl of SLOTS) {
    const uid = L.slots[sl.id];
    if (uid == null) continue;
    const found = findItem(uid);
    if (!found || found.from !== 'vault') { missing++; continue; }
    if (found.it.slot !== sl.id) { missing++; continue; }
    stash.vault.splice(found.index, 1);
    stash.gear[sl.id] = found.it;
    set++;
  }
  if (HEROES[L.hero]) stash.hero = L.hero;
  saveStash();
  return { set, missing };
}

/* --- the vendor ----------------------------------------------------------
   Coin exists to take the sting out of luck. Everything here is a way of
   spending it to make a specific thing happen rather than hoping it does:
   buy a piece for a slot you have never filled, reroll a piece you nearly
   like, or push the Regalia pity counter along.
   ---------------------------------------------------------------------- */
const VENDOR = [
  { id: 'commission', name: 'Commission a piece',
    note: 'A Spirit-wrought piece for a slot of your choosing.',
    cost: p => Math.round((180 + p * 6) * forgeCut()), slot: true },
  { id: 'temper', name: 'Temper a piece',
    note: 'Reroll every affix on something you are wearing, keeping its rarity.',
    cost: p => Math.round((120 + p * 4) * forgeCut()), worn: true },
  { id: 'reliquary', name: 'Open a reliquary',
    note: 'A piece of the Sundered Regalia. Costs less the longer one has ' +
          'refused to drop.', cost: p => Math.round(Math.max(300, 1400 - (stash.pity || 0) * 55) * relicCut()) }
];

function vendorCost(v) { return Math.round(v.cost(stashPower())); }

function canAfford(v) { return (stash.coins || 0) >= vendorCost(v); }

// Bad-luck protection: every delve that ends without a Regalia piece pushes
// the counter along, and the reliquary gets cheaper. Finding one resets it.
function notePity(foundSet) {
  if (foundSet) stash.pity = 0;
  else stash.pity = Math.min(20, (stash.pity || 0) + 1);
}

function vendorBuy(v, arg) {
  if (!canAfford(v)) return false;
  const cost = vendorCost(v);
  if (v.id === 'commission') {
    if (!arg || !SLOT_BY_ID[arg]) return false;
    if (stash.vault.length >= vaultCap()) return false;
    const it = rollItem(0.75, arg);
    it.rarity = 'wrought';
    // A commission is worth the price: three affixes, rolled at depth.
    const pool = SLOT_AFFIXES[arg].slice();
    it.affixes = [];
    for (let i = 0; i < 3 && pool.length; i++) {
      const id = pool.splice((Math.random() * pool.length) | 0, 1)[0];
      const a = AFFIX_BY_ID[id];
      let val = (a.lo + Math.random() * (a.hi - a.lo)) * 1.15;
      val = a.dp ? +val.toFixed(a.dp)
                 : (Math.abs(a.lo) >= 1 ? Math.max(1, Math.round(val)) : val);
      it.affixes.push({ id, v: val });
    }
    it.name = AFFIX_BY_ID[it.affixes[0].id].name + ' ' + it.base;
    stash.vault.push(it);
  } else if (v.id === 'temper') {
    const it = arg && stash.gear[arg];
    if (!it || it.set === SET_ID) return false;      // the Regalia is fixed
    const pool = SLOT_AFFIXES[it.slot].slice();
    const n = it.affixes.length;
    it.affixes = [];
    for (let i = 0; i < n && pool.length; i++) {
      const id = pool.splice((Math.random() * pool.length) | 0, 1)[0];
      const a = AFFIX_BY_ID[id];
      let val = (a.lo + Math.random() * (a.hi - a.lo)) * (0.8 + Math.random() * 0.6);
      val = a.dp ? +val.toFixed(a.dp)
                 : (Math.abs(a.lo) >= 1 ? Math.max(1, Math.round(val)) : val);
      it.affixes.push({ id, v: val });
    }
    it.name = AFFIX_BY_ID[it.affixes[0].id].name + ' ' + it.base;
  } else if (v.id === 'reliquary') {
    if (stash.vault.length >= vaultCap()) return false;
    stash.vault.push(rollSetPiece());
    stash.pity = 0;
  }
  stash.coins -= cost;
  saveStash();
  return true;
}

/* --- the bag ------------------------------------------------------------
   Opening it pauses the delve. There is no drag-and-drop: on a phone that is
   a fight with the touch target, so selection is a tap, and equipping is a
   second tap on a button big enough to hit. Selecting anything shows it
   measured against whatever is in its slot already, because "is this better"
   is the only question the screen exists to answer.
   --------------------------------------------------------------------- */
// {from:'bag', index, uid} | {from:'worn', slot}. The uid is what the
// selection really is: sorting reorders the array under it, so an index alone
// would silently start pointing at a different item the moment the order
// changed -- and the buttons beside it equip and sell by that index.
let gearSel = null;

/* The same screen serves the bag you are carrying mid-delve and the kit you
   keep between them. `gearCtx` says which, so none of the rendering or the
   equip logic has to be written twice. */
let gearCtx = null;

// Mid-delve the bag is a record of what you have found, not a workbench:
// sorting and equipping happen in the hub between delves, so a fight is never
// paused to compare two rings.
/* --- making a vault readable ---------------------------------------------
   Sorting reorders the array itself rather than keeping a display mapping.
   Nothing in the game depends on the order of the vault -- loadouts name
   items by id, banking appends, and the cap is a length -- so the simple
   thing is also the correct one, and a selection is carried across a re-sort
   by the item's id rather than by where it used to sit.
   -------------------------------------------------------------------- */
const BAG_SORTS = [
  { id: 'power',  name: 'Power',
    cmp: (a, b) => itemPower(b) - itemPower(a) },
  { id: 'slot',   name: 'Slot',
    cmp: (a, b) => (SLOT_INDEX[a.slot] - SLOT_INDEX[b.slot]) ||
                   (itemPower(b) - itemPower(a)) },
  { id: 'rarity', name: 'Rarity',
    cmp: (a, b) => (RARITY_INDEX[b.rarity] - RARITY_INDEX[a.rarity]) ||
                   (itemPower(b) - itemPower(a)) },
  { id: 'found',  name: 'Found',
    cmp: (a, b) => b.uid - a.uid }
];
const SLOT_INDEX = {};
SLOTS.forEach((sl, i) => { SLOT_INDEX[sl.id] = i; });
const RARITY_INDEX = {};
RARITY.forEach((r, i) => { RARITY_INDEX[r.id] = i; });

let bagSort = 'power';
let bagFilter = 'all';     // 'all' | 'up' | a slot id

// Would wearing this beat what is in its slot now? A ring is compared against
// the weaker of the two you have on, since that is the one it would replace.
function isUpgrade(it, gear) {
  if (!it) return false;
  if (it.slot === 'ring1' || it.slot === 'ring2') {
    const a = itemPower(gear.ring1), b = itemPower(gear.ring2);
    return itemPower(it) > Math.min(a, b);
  }
  return itemPower(it) > itemPower(gear[it.slot]);
}

function sortBag(C) {
  const s = BAG_SORTS.find(x => x.id === bagSort) || BAG_SORTS[0];
  C.bag.sort(s.cmp);
}

function bagShown(C) {
  if (bagFilter === 'all') return C.bag.map((it, i) => ({ it, i }));
  if (bagFilter === 'up') {
    return C.bag.map((it, i) => ({ it, i })).filter(o => isUpgrade(o.it, C.gear));
  }
  const want = bagFilter === 'ring1' || bagFilter === 'ring2' ? 'ring' : bagFilter;
  return C.bag.map((it, i) => ({ it, i })).filter(o =>
    (o.it.slot === 'ring1' || o.it.slot === 'ring2' ? 'ring' : o.it.slot) === want);
}

function runCtx() {
  return { gear: player.gear, bag: player.bag, cap: bagCap(), live: true,
           readOnly: true,
           sub: 'Carried so far', back: 'Back to the delve',
           bagName: 'Bag' };
}
function stashCtx() {
  return { gear: stash.gear, bag: stash.vault, cap: vaultCap(), live: false,
           sub: 'What you carried home', back: 'Leave the gate-house',
           bagName: 'Vault' };
}

function openGear(which) {
  if (which === 'stash') {
    gearCtx = stashCtx();
  } else {
    if (state !== 'play' && state !== 'pause') return;
    gearCtx = runCtx();
    stickEnd();
    keys.clear();
  }
  gearReturn = which === 'stash' ? 'splash' : null;
  state = 'gear';
  gearSel = null;
  renderGear();
  showScreen('gear');
}

let gearReturn = null;

function closeGear() {
  if (state !== 'gear') return;
  if (gearReturn === 'splash') {
    if (!gearCtx.live) saveStash();
    state = 'menu';
    refreshKitLine();
    showScreen('splash');
    return;
  }
  state = 'play';
  showScreen(null);
}

// The stat lines worth showing on the left. Derived, so they already include
// boons and everything equipped.
// Stats shown against the kit on display: the live player mid-delve, or a
// stand-in wearing the stash so the menu can show what a swap would do.
function statLines() {
  const p = gearCtx && !gearCtx.live ? previewPlayer() : player;
  return [
    ['Life',    Math.round(p.maxHp)],
    ['Damage',  Math.round(p.damage)],
    ['Swing',   p.fireDelay.toFixed(2) + 's'],
    ['Reach',   Math.round(p.range)],
    ['Sweep',   Math.round(p.sweep)],
    ['Stride',  Math.round(p.speed)],
    ['Ward',    Math.round((p.ward || 0) * 100) + '%'],
    ['Mending', (p.regen || 0).toFixed(1) + '/s']
  ];
}

// A throwaway player wearing the stash, so the menu can show real derived
// numbers without touching the one in the delve.
let _preview = null;
function previewPlayer() {
  const keepPlayer = player, keepGear = player && player.gear, keepUpg = player && player.upg;
  _preview = makePlayer(0, 0, stash.hero || 'isaac');
  _preview.gear = gearCtx.gear;
  _preview.upg = {};
  const save = player;
  player = _preview;
  recomputeStats();
  player = save;
  void keepPlayer; void keepGear; void keepUpg;
  return _preview;
}

function selectedItem() {
  if (!gearSel) return null;
  const C = gearCtx;
  return gearSel.from === 'bag' ? C.bag[gearSel.index] : C.gear[gearSel.slot];
}

// What each affix on `it` is worth against what is worn in that slot, so the
// comparison is per-stat rather than a single made-up score.
function compareLines(it) {
  const worn = gearCtx.gear[it.slot];
  const totals = {};
  const add = (src, sign) => {
    if (!src) return;
    for (const af of src.affixes) {
      const a = AFFIX_BY_ID[af.id];
      const key = a.stat + (a.mul ? '%' : '');
      totals[key] = (totals[key] || 0) + sign * af.v;
    }
  };
  add(it, 1); add(worn, -1);
  const NAMES = { damage:'damage', maxHp:'life', ward:'ward', speed:'stride',
                  range:'reach', sweep:'sweep', fireDelay:'swing time',
                  magnet:'draw', regen:'mending' };
  const out = [];
  for (const k in totals) {
    const v = totals[k];
    if (Math.abs(v) < 0.005) continue;
    const pct = k.endsWith('%');
    const stat = pct ? k.slice(0, -1) : k;
    // less swing time is better, so its sign reads backwards
    const good = stat === 'fireDelay' ? v < 0 : v > 0;
    const txt = pct ? (v > 0 ? '+' : '') + Math.round(v * 100) + '%'
                    : (v > 0 ? '+' : '') + (Math.abs(v) < 1 ? v.toFixed(1) : Math.round(v));
    out.push({ txt, name: NAMES[stat] || stat, good });
  }
  return out;
}

function afterGearChange() {
  const C = gearCtx;
  if (C.live) recomputeStats(); else saveStash();
  gearSel = null;
  renderGear();
  syncBagBadge();
}

function equipSelected() {
  const it = selectedItem();
  if (!it || gearSel.from !== 'bag') return;
  const C = gearCtx;
  const prev = C.gear[it.slot];
  C.bag.splice(gearSel.index, 1);
  C.gear[it.slot] = it;
  if (prev) C.bag.push(prev);            // the old one goes back where it came from
  afterGearChange();
}

function unequipSelected() {
  const it = selectedItem();
  if (!it || gearSel.from !== 'worn') return;
  const C = gearCtx;
  if (C.bag.length >= C.cap) return;     // nowhere to put it
  C.gear[gearSel.slot] = null;
  C.bag.push(it);
  afterGearChange();
}

function discardSelected() {
  if (!gearSel || gearSel.from !== 'bag') return;
  gearCtx.bag.splice(gearSel.index, 1);
  afterGearChange();
}

/* --- pause -------------------------------------------------------------- */

function pauseRun() {
  if (state !== 'play') return;
  state = 'pause';
  stickEnd();
  keys.clear();
  showScreen('paused');
}
function resumeRun() {
  if (state !== 'pause') return;
  state = 'play';
  showScreen(null);
}

/* --- input listeners ---------------------------------------------------- */

function localPoint(e) {
  const r = canvas.getBoundingClientRect();
  return { x: e.clientX - r.left, y: e.clientY - r.top };
}

function releasePointer(e) {
  if (stick.active && e.pointerId === stick.id) stickEnd();
}

// How much is waiting in the vault, shown on the menu so the kit is not a
// door you have to open to find out whether anything is behind it.
let vendorSel = null;

let hallSel = null;

function openHall() {
  hallSel = null;
  state = 'menu';
  renderHall();
  showScreen('hall');
}

// The delve tab carries the power you would take in, which is the number the
// whole ladder is read against.
function refreshDelveLine() {
  const t = $('delveLine');
  if (t) t.textContent = 'power ' + stashPower();
}

// All four at once. Every station can change what another one says -- buying
// at the vendor moves the purse and the kit both -- so they are refreshed
// together rather than each caller remembering which ones it touched.
function refreshHubLines() {
  refreshKitLine(); refreshVendorLine(); refreshHallLine(); refreshDelveLine();
}

function openVendor() {
  vendorSel = null;
  state = 'menu';
  renderVendor();
  showScreen('vendor');
}

/* --- main loop ---------------------------------------------------------- */

let last = 0;

let lowFx = false;              // auto-drops the light pass on slow devices

/* --- the dead ------------------------------------------------------------
   Drawn front-on and mirrored by heading, like the warden, for the same
   reason: a body seen from directly overhead is a blob, and a blob with two
   lit dots on it reads as a face no matter what you shade it. Each one is a
   figure with a posture -- the wretch stoops, the shade hangs, the revenant
   plants itself -- so they are told apart by silhouette before colour.
   ---------------------------------------------------------------------- */

/* --- gait -----------------------------------------------------------------
   A body is forged as a short cycle of poses rather than one still frame, and
   the pose is chosen by how far the body has actually travelled -- not by a
   clock -- so feet land on the ground instead of skating over it.

   Enemies get one cycle. They are either dormant, in which case they do not
   move at all, or they have woken and are coming at you flat out; there is no
   third speed to animate. The hero gets two, because the stick is analogue:
   ease it over and he walks, push it to the ring and he runs, and stride is
   the one part of that difference which cannot be faked at blit time. Cadence,
   lean and bob all can, and are.
   ------------------------------------------------------------------------ */
// Eight, not six: sin repeats its magnitude in pairs over six samples, so a
// six-pose cycle is really four poses with two of them shown twice, and the
// stutter is visible.
const GAIT_N = 8;            // poses in a cycle
const GAIT_STEP = 21;        // world units of travel per pose at a run
const WALK_STEP = 13;        // and at a walk, which is a shorter, quicker one
const WALK_PACE = 0.62;      // above this fraction of top speed, he is running

// Book the ground a body just covered against its stride, and keep a smoothed
// reading of how hard it is travelling. Pace is what picks walk from run and
// what tells a body it has stopped: gait alone cannot, because a body held up
// against a wall keeps its last frame and would stand there mid-step forever.
function advanceGait(e, x0, y0, dt) {
  const moved = Math.hypot(e.x - x0, e.y - y0);
  e.gait += moved;
  const want = dt > 0 ? Math.min(1.4, (moved / dt) / (e.speed || 1)) : 0;
  e.pace += (want - e.pace) * Math.min(1, dt * 9);
}

// Which sprite a body wears this frame. Below GAIT_STILL it is standing.
const GAIT_STILL = 0.16;

/* --- strikes --------------------------------------------------------------
   One crescent thrown the same way every time is the whole of the fight seen
   from the outside, so the strike is a shape now rather than only a timer.
   Three cycle in order: the blade comes across level, then up from low, then
   down the centre. `from` and `to` are the weapon's angle through the swing,
   in the hero's own space so it mirrors with his facing; `lunge` is how far he
   is drawn into it; `span` and `wide` shape the streak it leaves.

   The forms are drawing only. Damage, reach and the crescent's hit geometry
   are untouched by which one is playing -- a strike that hit differently
   depending on where you were in the cycle would be a balance change wearing
   an animation's clothes.
   ------------------------------------------------------------------------ */
const STRIKES = [
  { id: 'slash', from: -1.75, to:  1.15, lunge:  5, span: 1.7,  wide: 1.0,  R: 1.0 },
  { id: 'rise',  from:  1.30, to: -1.55, lunge:  4, span: 1.45, wide: 0.78, R: 0.94 },
  { id: 'chop',  from: -2.45, to:  0.30, lunge: 12, span: 1.0,  wide: 1.5,  R: 1.12 }
];
const RECOVER_TIME = 0.13;     // and how long it takes to come back to it

let LEVEL = LEVELS[0];
let REGION = REGIONS[0];

// The breakable subset, gathered once a delve is cut. Pillars and pitch
// barrels only -- a crate is furniture.
function indexBreakables() {
  // A rung that has not taught pitch yet does not contain any. The scenery
  // scatter puts barrels down on its own, quite apart from the pass that seeds
  // them beside the packs, so suppressing one source is not enough.
  if (LEVEL && LEVEL.pitch === 0) props = props.filter(pr => pr.kind !== 'barrel');
  propGrid = [];
  for (let i = 0; i < props.length; i++) {
    const pr = props[i];
    if (!PROP_HP[pr.kind]) continue;
    pr.hp = PROP_HP[pr.kind];
    pr.gone = false;
    pr.shake = 0;
    propGrid.push(pr);
  }
}

function endRun(won) {
  if (state === 'over') return;
  state = 'over';
  stickEnd();

  const b = loadBest();
  b.runs = (b.runs || 0) + 1;
  if (won) b.extractions = (b.extractions || 0) + 1;
  b.bestTime = Math.max(b.bestTime || 0, run.time);
  b.bestKills = Math.max(b.bestKills || 0, run.kills);
  saveBest(b);

  const carried = player.bag.length;
  // Only a piece you actually carried out counts against the pity counter.
  notePity(won && player.bag.some(it => it.set === SET_ID));
  // Dying leaves everything unbanked on the floor, and the delve keeps it
  // until you come back for it. Only one corpse exists at a time -- dying on
  // the walk back is what makes the walk back cost something.
  let lost = 0;
  if (!won) {
    const items = player.bag.slice(0, CORPSE_CARRY);
    lost = (stash.corpse && (stash.corpse.items.length || stash.corpse.coins)) ? 1 : 0;
    stash.corpse = (items.length || run.coins)
      ? { level_id: LEVEL.id, hero: run.hero, x: player.x, y: player.y,
          items, coins: run.coins }
      : null;
  }
  bankRun(won);

  el.overTitle.innerHTML = won ? '<em>Escaped</em>' : '<span>Slain</span>';
  el.overSub.textContent = won
    ? (carried ? 'The ley-gate held. You carried ' + carried +
                 (carried === 1 ? ' find' : ' finds') + ' out with the slag.'
               : 'The ley-gate held. You carried the slag out.')
    : (stash.corpse
        ? 'The hive-mind claimed another of the Clear-Sighted. ' +
          (carried ? carried + (carried === 1 ? ' find' : ' finds') + ' and ' : '') +
          run.coins + ' coin lie in ' + LEVEL.name + '. Descend again and take them back.' +
          (lost ? ' Your older corpse is gone.' : '')
        : 'The hive-mind claimed another of the Clear-Sighted.');
  el.overStats.innerHTML =
    '<div>Endured<b>' + fmtTime(run.time) + '</b></div>' +
    '<div>Slain<b>' + run.kills + '</b></div>' +
    '<div>Slag<b>' + run.tech + '</b></div>' +
    '<div>' + (won ? 'Carried out' : 'Left behind') + '<b>' + carried + '</b></div>' +
    '<div>' + (won ? 'Coin banked' : 'Coin left') + '<b>' + run.coins + '</b></div>';
  showScreen('over');
  refreshBestLine();
}

